-- =====================================================================
-- 094 — Perfil completo + farmacologia de 30 fármacos (lote 3)
-- ---------------------------------------------------------------------
-- Perfis (drug_profiles, padrão 090) E farmacologia (drug_pharmacology,
-- padrão 088/091/092) dos 30 fármacos seguintes por nº de pares na BD,
-- todos sem perfil e sem farmacologia (confirmado por consulta read-only).
-- Fontes (citadas por linha):
--   • 24 fármacos: secções INDICATIONS AND USAGE, ADVERSE REACTIONS,
--     CONTRAINDICATIONS, WARNINGS AND PRECAUTIONS + secção 12 CLINICAL
--     PHARMACOLOGY dos rótulos aprovados DailyMed (setIDs validados);
--   • sulfadoxina-pirimetamina: SmPC WHO-prequalificada (MA193);
--   • domperidona: SmPC europeia Motilium (Comissão Europeia, 2002);
--   • metamizol: Prontuário Terapêutico + revisão de farmacocinética
--     (Levy M, Clin Pharmacokinet 1995 — PMID 7758252);
--   • paracetamol, ferro, fexofenadina, loratadina: rótulos OTC DailyMed
--     (Drug Facts, sem secção 12) + farmacocinética PubMed (citadas);
--   • haloperidol e ampicilina: rótulos DailyMed + farmacocinética
--     PubMed (PMID 2689040 e PMID 2660866, respetivamente).
-- Conteúdo autoral (não copiado), ancorado nos números das fontes.
-- Idempotente: ON CONFLICT (drug_id) DO NOTHING — reaplicar é seguro.
-- Padrão 7.6 (JOIN ON d.slug = v.slug). Aplicar na ordem 079 → 094.
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('nitroglicerina',
   'A nitroglicerina sublingual é um vasodilatador de ação rápida usado para aliviar a crise de angina de peito (dor no peito por falta de oxigénio no coração). O comprimido coloca-se debaixo da língua, onde é absorvido em poucos minutos: o efeito começa em 1 a 3 minutos e dura cerca de 25 minutos. Não deve ser usada com medicamentos para a disfunção erétil (sildenafil, tadalafil, vardenafil).',
   'Sublingual nitroglycerin is a fast-acting vasodilator used to relieve an angina attack (chest pain due to reduced oxygen supply to the heart). The tablet is placed under the tongue, where it is absorbed within minutes: the effect starts within 1 to 3 minutes and lasts about 25 minutes. It must not be used with erectile dysfunction medicines (sildenafil, tadalafil, vardenafil).',
   'Nitrato orgânico de ação rápida (comprimido sublingual) indicado no alívio agudo e na profilaxia aguda da angina de peito por doença coronária. Gera óxido nítrico (NO) que ativa a guanilato ciclase, aumentando o GMPc no músculo liso e causando vasodilatação venosa predominante (redução da pré-carga) e arterial (redução da pós-carga), com melhoria do equilíbrio oferta/consumo de oxigénio miocárdico. Não confere benefício de sobrevivência; usar com precaução face ao risco de hipotensão grave.',
   'Fast-acting organic nitrate (sublingual tablet) indicated for the acute relief or acute prophylaxis of angina pectoris due to coronary artery disease. It generates nitric oxide (NO), which activates guanylate cyclase, raising cyclic GMP in smooth muscle and causing predominantly venous vasodilation (reduced preload) and arterial vasodilation (reduced afterload), improving the myocardial oxygen supply/demand balance. No survival benefit; use cautiously given the risk of severe hypotension.',
   E'Alívio agudo da crise de angina de peito por doença coronária.\nProfilaxia aguda da angina (toma imediatamente antes do esforço previsível).',
   E'Acute relief of an angina attack due to coronary artery disease.\nAcute prophylaxis of angina (taken immediately before predictable exertion).',
   E'Cefaleia pulsátil (o efeito adverso mais frequente).\nHipotensão ortostática, tonturas, vertigens, fraqueza e palidez.\nRubor facial (flushing).\nTaquicardia reflexa e palpitações.\nNáuseas, vómitos e colapso em doentes muito sensíveis ao efeito hipotensor.\nSíncope por vasodilatação; dermatite exfoliativa (rara).',
   E'Pulsatile headache (the most frequent adverse effect).\nOrthostatic hypotension, dizziness, vertigo, weakness and pallor.\nFacial flushing.\nReflex tachycardia and palpitations.\nNausea, vomiting and collapse in patients highly sensitive to the hypotensive effect.\nSyncope due to vasodilation; exfoliative dermatitis (rare).',
   E'Não usar com inibidores da fosfodiesterase-5 (avanafil, sildenafil, tadalafil, vardenafil) nem com estimuladores da guanilato ciclase solúvel (riociguat) — risco de hipotensão grave, síncope ou isquemia miocárdica.\nContraindicado na anemia grave (risco de metaemoglobinemia), na pressão intracraniana aumentada (hemorragia cerebral, traumatismo craniano) e no choque/insuficiência circulatória aguda.\nHipersensibilidade a nitratos ou nitritos.\nSentar-se durante a toma para evitar quedas por hipotensão.\nSe a dor não aliviar com 1 comprimido em 5 minutos, tomar outro e contactar emergência (possível enfarte).',
   E'Do not use with phosphodiesterase-5 inhibitors (avanafil, sildenafil, tadalafil, vardenafil) or soluble guanylate cyclase stimulators (riociguat) — risk of severe hypotension, syncope or myocardial ischaemia.\nContraindicated in severe anaemia (risk of methaemoglobinaemia), increased intracranial pressure (cerebral haemorrhage, head trauma) and acute circulatory failure/shock.\nHypersensitivity to nitrates or nitrites.\nSit down when taking the tablet to avoid falls from hypotension.\nIf pain is not relieved by one tablet within 5 minutes, take another and call emergency services (possible heart attack).',
   'DailyMed/FDA (NIH/NLM) — rótulo Nitroglycerin Sublingual Tablets: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=84739085-81df-4a43-8456-c9edfbf971e9',
   'DailyMed/FDA (NIH/NLM) — Nitroglycerin Sublingual Tablets label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=84739085-81df-4a43-8456-c9edfbf971e9'),

  ('paracetamol',
   'O paracetamol é um analgésico e antipirético de venda livre, eficaz na dor ligeira a moderada (cefaleias, dores musculares, febre). É bem tolerado nas doses recomendadas, mas a dose máxima diária de 4 g não deve ser excedida: em excesso pode causar lesão hepática grave, sobretudo com consumo de álcool ou se combinado com outros medicamentos que contenham paracetamol.',
   'Paracetamol (acetaminophen) is an over-the-counter analgesic and antipyretic, effective for mild to moderate pain (headache, muscle aches, fever). It is well tolerated at recommended doses, but the 4 g daily maximum must not be exceeded: in excess it can cause severe liver damage, especially with alcohol use or when combined with other paracetamol-containing medicines.',
   'Analgésico/antipirético (derivado do para-aminofenol) de primeira linha para a dor ligeira a moderada e a febre. O mecanismo analgésico é predominantemente central. Em doses supraterapêuticas, o metabolito reativo (NAPQI) esgota a glutationa hepática e causa necrose hepatocelular — risco major de sobredosagem, potenciado pelo álcool e pela doença hepática; a dose máxima é de 4 g/dia em adultos.',
   'First-line analgesic/antipyretic (para-aminophenol derivative) for mild to moderate pain and fever. The analgesic mechanism is predominantly central. At supratherapeutic doses the reactive metabolite (NAPQI) depletes hepatic glutathione and causes hepatocellular necrosis — a major overdose risk, potentiated by alcohol and liver disease; maximum dose is 4 g/day in adults.',
   E'Alívio temporário de dores ligeiras a moderadas: constipação, cefaleia, dor lombar, dor da artrose, dor de dentes, dores musculares, cólicas menstruais.\nRedução temporária da febre.',
   E'Temporary relief of mild to moderate aches and pains: common cold, headache, backache, osteoarthritis pain, toothache, muscular aches, menstrual cramps.\nTemporary reduction of fever.',
   E'Nas doses recomendadas é geralmente bem tolerado.\nReações cutâneas graves (raras): vermelhidão, bolhas, erupção — parar e procurar ajuda médica.\nToxicidade hepática (dose-dependente) — sobretudo acima de 4 g/dia ou com álcool/doença hepática.\nHipersensibilidade/anafilaxia (rara).',
   E'Generally well tolerated at recommended doses.\nSevere skin reactions (rare): reddening, blisters, rash — stop and seek medical help.\nHepatotoxicity (dose-dependent) — mainly above 4 g/day or with alcohol/liver disease.\nHypersensitivity/anaphylaxis (rare).',
   E'Não exceder 4 000 mg (4 g) de paracetamol em 24 horas, nem usar em simultâneo com outros medicamentos que contenham paracetamol (receita ou venda livre).\nLimitar o consumo de álcool durante o tratamento (risco hepático).\nConsultar o médico antes de usar em caso de doença hepática.\nConsultar médico ou farmacêutico se toma varfarina (aumento do risco hemorrágico com uso prolongado).\nEm caso de sobredosagem, procurar ajuda médica imediatamente mesmo sem sintomas.',
   E'Do not exceed 4,000 mg (4 g) of acetaminophen in 24 hours, nor use with other acetaminophen-containing drugs (prescription or OTC).\nLimit alcohol intake during treatment (liver risk).\nAsk a doctor before use if you have liver disease.\nAsk a doctor or pharmacist if you take the blood thinner warfarin (increased bleeding risk with prolonged use).\nIn case of overdose, seek medical help immediately even without symptoms.',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Acetaminophen Tablet (Drug Facts) + Prescott LF, Clin Pharmacokinet 1982 (PMID 7039926): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=50e7b939-e0eb-44ea-82ea-034e844e2c29',
   'DailyMed/FDA (NIH/NLM) — OTC Acetaminophen Tablet label (Drug Facts) + Prescott LF, Clin Pharmacokinet 1982 (PMID 7039926): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=50e7b939-e0eb-44ea-82ea-034e844e2c29'),

  ('praziquantel',
   'O praziquantel é um antiparasitário usado no tratamento da esquistossomose e de infeções por trematódeos hepáticos (clonorquíase e opistorquíase). Toma-se por via oral, geralmente em dose única ou em esquemas curtos calculados pelo peso. É bem tolerado; os efeitos secundários mais comuns são cefaleia, tonturas e desconforto abdominal.',
   'Praziquantel is an antiparasitic medicine used to treat schistosomiasis and liver fluke infections (clonorchiasis and opisthorchiasis). It is taken orally, usually as a single dose or short course calculated by weight. It is well tolerated; the most common side effects are headache, dizziness and abdominal discomfort.',
   'Anti-helmíntico sintético (pirazino-isoquinolina) ativo contra todas as espécies de Schistosoma e contra os trematódeos hepáticos Clonorchis sinensis/Opisthorchis viverrini. Induz contração rápida e vacuolização do tegumento do parasita. Metabolizado pelo CYP3A4: os indutores fortes (rifampicina, efavirenz) reduzem drasticamente a exposição — contraindicação com rifampicina.',
   'Synthetic anthelmintic (pyrazinoisoquinoline) active against all Schistosoma species and the liver flukes Clonorchis sinensis/Opisthorchis viverrini. It induces rapid contraction and vacuolization of the parasite tegument. Metabolized by CYP3A4: strong inducers (rifampin, efavirenz) markedly reduce exposure — contraindicated with rifampin.',
   E'Esquistossomose por todas as espécies de Schistosoma (S. mansoni, S. haematobium, S. japonicum, S. mekongi), em doentes com 1 ano ou mais.\nClonorquíase e opistorquíase por trematódeos hepáticos (Clonorchis sinensis/Opisthorchis viverrini).',
   E'Schistosomiasis due to all Schistosoma species (S. mansoni, S. haematobium, S. japonicum, S. mekongi), in patients aged 1 year and older.\nClonorchiasis and opisthorchiasis due to liver flukes (Clonorchis sinensis/Opisthorchis viverrini).',
   E'Cefaleia, tonturas e desconforto abdominal (os mais comuns, em adultos e crianças).\nMal-estar, febre e urticária.\nEosinofilia; vertigens e zumbidos.\nArritmias (bradicardia, ritmos ectópicos, fibrilhação ventricular, bloqueios AV) — reportadas em experiência pós-comercialização.\nConvulsões, sonolência e tremor intencional (raros).\nSíndrome de Stevens-Johnson (rara).',
   E'Headache, dizziness and abdominal discomfort (most common, in adults and children).\nMalaise, pyrexia and urticaria.\nEosinophilia; vertigo and tinnitus.\nArrhythmias (bradycardia, ectopic rhythms, ventricular fibrillation, AV blocks) — reported postmarketing.\nConvulsions, somnolence and intention tremor (rare).\nStevens-Johnson syndrome (rare).',
   E'Não usar em caso de hipersensibilidade, cisticercose ocular ou toma de indutores fortes do CYP3A4 (ex.: rifampicina) — risco de falência terapêutica.\nOs efeitos adversos podem ser mais frequentes/graves com carga parasitária elevada.\nEm doentes com compromisso hepático moderado a grave (Child-Pugh B/C) a semivida e a exposição aumentam — considerar vigilância.\nVigiar sinais de deterioração clínica na neurocisticercose.\nInterromper o tratamento se ocorrerem reações cutâneas graves.',
   E'Do not use in hypersensitivity, ocular cysticercosis, or with strong CYP3A inducers (e.g., rifampin) — risk of therapeutic failure.\nAdverse reactions may be more frequent/serious with a heavy worm burden.\nIn patients with moderate-to-severe hepatic impairment (Child-Pugh B/C) half-life and exposure increase — consider monitoring.\nMonitor for signs of clinical deterioration in neurocysticercosis.\nDiscontinue treatment if severe skin reactions occur.',
   'DailyMed/FDA (NIH/NLM) — rótulo Biltricide (praziquantel) Bayer: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34ce1cdd-648e-4f1e-8512-bf3d4cc22eb9',
   'DailyMed/FDA (NIH/NLM) — Biltricide (praziquantel) Bayer label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34ce1cdd-648e-4f1e-8512-bf3d4cc22eb9'),

  ('valsartana',
   'A valsartana é um medicamento para a tensão arterial alta (hipertensão), que também é usada na insuficiência cardíaca e após enfarte do miocárdio. Pertence à classe dos antagonistas dos recetores da angiotensina II (ARA). É geralmente bem tolerada; pode causar tonturas, fadiga e, menos frequentemente, aumento do potássio ou alteração da função renal.',
   'Valsartan is a medicine for high blood pressure (hypertension), also used in heart failure and after myocardial infarction. It belongs to the angiotensin II receptor blocker (ARB) class. It is generally well tolerated; it can cause dizziness, fatigue and, less often, increased potassium or changes in kidney function.',
   'Antagonista seletivo do recetor AT1 da angiotensina II (ARA), indicado na hipertensão (adultos e crianças ≥6 anos), na insuficiência cardíaca (NYHA II–IV) para reduzir o risco de hospitalização, e na disfunção ventricular esquerda pós-enfarte para reduzir a mortalidade cardiovascular. Bloqueia a vasoconstrição e a secreção de aldosterona mediadas pela angiotensina II; não inibe a ACE (sem tosse associada).',
   'Selective AT1 angiotensin II receptor antagonist (ARB), indicated in hypertension (adults and children ≥6 years), in heart failure (NYHA II–IV) to reduce the risk of hospitalisation, and in post-MI left ventricular dysfunction to reduce cardiovascular mortality. It blocks angiotensin II-mediated vasoconstriction and aldosterone secretion; it does not inhibit ACE (no associated cough).',
   E'Hipertensão arterial — redução da pressão arterial e do risco de eventos cardiovasculares fatais e não fatais (acidente vascular cerebral, enfarte do miocárdio); isolada ou em associação.\nInsuficiência cardíaca (NYHA II–IV) — redução do risco de hospitalização.\nDisfunção ventricular esquerda ou insuficiência cardíaca após enfarte do miocárdio — redução da mortalidade cardiovascular.',
   E'Hypertension — lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events (stroke, myocardial infarction); alone or in combination.\nHeart failure (NYHA II–IV) — reduction in the risk of hospitalisation.\nLeft ventricular failure or dysfunction after myocardial infarction — reduction in cardiovascular mortality.',
   E'Na hipertensão: infeção viral (3%), fadiga (2%) e dor abdominal (2%) mais frequentes que placebo; cefaleia e tonturas foram os motivos mais comuns de suspensão.\nNa insuficiência cardíaca: tonturas (17%), hipotensão (7%), diarreia (5%), hipercaliemia (2%), insuficiência renal.\nTosse seca significativamente menos frequente do que com inibidores da ACE (2,6% vs 7,9%).\nPós-comercialização: angioedema, elevação das enzimas hepáticas, hepatite (rara), rabdomiólise, insuficiência renal, trombocitopenia.',
   E'In hypertension: viral infection (3%), fatigue (2%) and abdominal pain (2%) more frequent than placebo; headache and dizziness were the most common reasons for discontinuation.\nIn heart failure: dizziness (17%), hypotension (7%), diarrhoea (5%), hyperkalaemia (2%), renal impairment.\nDry cough significantly less frequent than with ACE inhibitors (2.6% vs 7.9%).\nPostmarketing: angioedema, elevated liver enzymes, hepatitis (rare), rhabdomyolysis, renal failure, thrombocytopenia.',
   E'Não usar em caso de hipersensibilidade; não coadministrar com aliscireno em doentes com diabetes.\nVigiar potássio e creatinina — risco de hipercaliemia e agravamento da função renal, sobretudo na insuficiência cardíaca ou com AINEs/diuréticos poupadores de potássio.\nEvitar na gravidez (toxicidade fetal); suspender o mais cedo possível se ocorrer gravidez.\nHipotensão sintomática possível em doentes depletados de volume — corrigir antes de iniciar.\nNão readministrar a doentes com história de angioedema.',
   E'Do not use in hypersensitivity; do not coadminister with aliskiren in patients with diabetes.\nMonitor potassium and creatinine — risk of hyperkalaemia and worsening renal function, especially in heart failure or with NSAIDs/potassium-sparing diuretics.\nAvoid in pregnancy (fetal toxicity); discontinue as early as possible if pregnancy occurs.\nSymptomatic hypotension possible in volume-depleted patients — correct before starting.\nDo not re-administer to patients with a history of angioedema.',
   'DailyMed/FDA (NIH/NLM) — rótulo Valsartan Tablets (Macleods): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=251ccff4-bf86-453b-9d1c-e3c1ecfd3a46',
   'DailyMed/FDA (NIH/NLM) — Valsartan Tablets label (Macleods): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=251ccff4-bf86-453b-9d1c-e3c1ecfd3a46'),

  ('vancomicina',
   'A vancomicina (cápsulas orais) é um antibiótico usado no tratamento da diarreia associada à infeção por Clostridioides difficile e da enterocolite por Staphylococcus aureus, incluindo estirpes resistentes. Tomada por via oral, atua no intestino sem ser absorvida para o sangue. Não é eficaz para outros tipos de infeção por esta via.',
   'Vancomycin (oral capsules) is an antibiotic used to treat diarrhoea associated with Clostridioides difficile infection and enterocolitis caused by Staphylococcus aureus, including resistant strains. Taken orally, it acts in the gut without being absorbed into the blood. It is not effective for other types of infection by this route.',
   'Glicopéptido bactericida ativo contra Gram-positivos; por via oral é praticamente não absorvido, atuando localmente no lúmen intestinal — indicado na diarreia associada a C. difficile e na enterocolite por S. aureus (incluindo MRSA) em doentes <18 anos. A administração parentérica não é eficaz nestas indicações. Inibição da síntese da parede celular bacteriana.',
   'Bactericidal glycopeptide active against Gram-positives; given orally it is virtually unabsorbed, acting locally in the gut lumen — indicated for C. difficile-associated diarrhoea and S. aureus enterocolitis (including MRSA) in patients <18 years. Parenteral administration is not effective for these indications. Inhibits bacterial cell-wall synthesis.',
   E'Diarreia associada a infeção por Clostridioides difficile (cápsulas orais).\nEnterocolite por Staphylococcus aureus (incluindo estirpes resistentes à meticilina) em doentes pediátricos (<18 anos).',
   E'Clostridioides difficile-associated diarrhoea (oral capsules).\nEnterocolitis caused by Staphylococcus aureus (including methicillin-resistant strains) in paediatric patients (<18 years).',
   E'Nas cápsulas orais (estudos de fase 3, ≥5%): náuseas (17%), dor abdominal (15%), hipocaliemia (13%), vómitos (9%), diarreia (9%), febre (9%), cefaleia (7%), infeção urinária (8%).\nNefrotoxicidade em 5% (insuficiência renal, creatinina elevada), mais frequente em >65 anos.\nPós-comercialização (sobretudo IV): ototoxicidade (perda auditiva, vertigens, zumbidos), neutropenia reversível, trombocitopenia, reações cutâneas graves (SJS, TEN, DRESS), anafilaxia.',
   E'Oral capsules (phase 3 trials, ≥5%): nausea (17%), abdominal pain (15%), hypokalaemia (13%), vomiting (9%), diarrhoea (9%), pyrexia (9%), headache (7%), urinary tract infection (8%).\nNephrotoxicity in 5% (renal failure, increased creatinine), more frequent in >65 years.\nPostmarketing (mainly IV): ototoxicity (hearing loss, vertigo, tinnitus), reversible neutropenia, thrombocytopenia, severe skin reactions (SJS, TEN, DRESS), anaphylaxis.',
   E'Reservar para infeções comprovadas ou fortemente suspeitas por bactérias suscetíveis.\nNefrotoxicidade (5% na diarreia por C. difficile) — vigiar função renal, sobretudo em idosos e com outras drogas nefrotóxicas.\nOtotoxicidade associada sobretudo à via IV; antecedentes de disfunção renal ou audição prévia aumentam o risco.\nReações cutâneas graves: suspender e instituir terapêutica adequada.\nNão usar por via oral para outros tipos de infeção.',
   E'Reserve for proven or strongly suspected infections caused by susceptible bacteria.\nNephrotoxicity (5% in C. difficile diarrhoea) — monitor renal function, especially in the elderly and with other nephrotoxic drugs.\nOtotoxicity mainly associated with IV use; prior renal dysfunction or hearing loss increase the risk.\nSevere skin reactions: discontinue and institute appropriate therapy.\nDo not use orally for other types of infection.',
   'DailyMed/FDA (NIH/NLM) — rótulo Vancomycin Hydrochloride Capsules + Vancomycin Injection (Hospira): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=57d23aed-a3f7-f92e-e063-6394a90add7d',
   'DailyMed/FDA (NIH/NLM) — Vancomycin Hydrochloride Capsules label + Vancomycin Injection (Hospira): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=57d23aed-a3f7-f92e-e063-6394a90add7d'),
  ('sulfadoxina-pirimetamina',
   'A associação sulfadoxina + pirimetamina é um antimalárico usado sobretudo na prevenção intermitente da malária na gravidez e na quimioprevenção sazonal em crianças, em zonas onde o parasita ainda é sensível. São comprimidos tomados por via oral, geralmente em doses únicas supervisionadas. Como todos os medicamentos com sulfonamidas, pode causar reações cutâneas graves.',
   'Sulfadoxine + pyrimethamine is an antimalarial used mainly for intermittent preventive treatment of malaria in pregnancy and seasonal chemoprevention in children, in areas where the parasite remains sensitive. It is taken orally, usually as supervised single doses. Like all sulfonamide medicines, it can cause severe skin reactions.',
   'Associação antifolato de ação prolongada (sulfadoxina, sulfonamida, + pirimetamina, antagonista do di-hidrofolato) indicada no tratamento preventivo intermitente da malária na gravidez e na quimioprevenção da malária sazonal em crianças de alto risco, em áreas de transmissão moderada a elevada onde a eficácia se mantém. Ambas as moléculas têm semividas longas (sulfadoxina ~8-9 dias; pirimetamina ~4 dias). Risco de reações cutâneas graves e hematológicas.',
   'Long-acting antifolate combination (sulfadoxine, a sulfonamide, + pyrimethamine, a dihydrofolate antagonist) indicated for intermittent preventive treatment of malaria in pregnancy and seasonal malaria chemoprevention in high-risk children, in areas of moderate to high transmission where efficacy is maintained. Both molecules have long half-lives (sulfadoxine ~8-9 days; pyrimethamine ~4 days). Risk of severe skin and haematological reactions.',
   E'Tratamento preventivo intermitente da malária na gravidez (cuidados pré-natais) em zonas endémicas.\nQuimioprevenção perene da malária em crianças de alto risco em áreas de transmissão perene moderada a elevada (prevalência de P. falciparum >10%) onde a sulfadoxina-pirimetamina é eficaz.',
   E'Intermittent preventive treatment of malaria in pregnancy (antenatal care) in endemic areas.\nPerennial malaria chemoprevention in children at high risk in areas of moderate to high perennial transmission (P. falciparum prevalence >10%) where sulfadoxine-pyrimethamine is effective.',
   E'Reações gastrintestinais: glossite, estomatite, náuseas, vómitos, dor abdominal, diarreia.\nCutâneas: fotossensibilidade, urticária, prurido, eritema multiforme, síndrome de Stevens-Johnson, necrólise epidérmica tóxica (raras mas graves).\nHematológicas (raras): agranulocitose, anemia aplástica e megaloblástica, trombocitopenia, leucopenia, anemia hemolítica, eosinofilia.\nNeurológicas: cefaleia, convulsões, ataxia, alucinações, insónia, fadiga.\nHepatotoxicidade (rara).\nFebre, arrepios, fenómeno de lúpus eritematoso.',
   E'Gastrointestinal: glossitis, stomatitis, nausea, vomiting, abdominal pain, diarrhoea.\nSkin: photosensitivity, urticaria, pruritus, erythema multiforme, Stevens-Johnson syndrome, toxic epidermal necrolysis (rare but serious).\nHaematological (rare): agranulocytosis, aplastic and megaloblastic anaemia, thrombocytopenia, leukopenia, haemolytic anaemia, eosinophilia.\nNeurological: headache, convulsions, ataxia, hallucinations, insomnia, fatigue.\nHepatotoxicity (rare).\nFever, chills, lupus erythematosus phenomenon.',
   E'Suspender se ocorrerem erupções cutâneas, citopenias ou sobreinfeção bacteriana/fúngica.\nPrecaução na administração repetida em doentes com discrasias sanguíneas e com insuficiência renal ou hepática (acumulação).\nNÃO administrar ácido fólico ≥5 mg/dia em conjunto (neutraliza a eficácia antimalárica); 0,4 mg/dia é seguro.\nContraindicado em prematuros e recém-nascidos <2 meses, em anemia megaloblástica documentada por défice de folato e em hipersensibilidade a sulfonamidas.\nNão administrar a criança com doença aguda; se tiver malária tratar com esquema curativo específico.',
   E'Discontinue if skin eruptions, cytopenia or bacterial/fungal superinfection occur.\nCaution with repeated administration in patients with blood dyscrasias and renal or hepatic failure (accumulation).\nDo NOT give folic acid ≥5 mg/day concomitantly (counteracts antimalarial efficacy); 0.4 mg/day is safe.\nContraindicated in premature and newborn infants <2 months, in documented megaloblastic anaemia due to folate deficiency, and in sulfonamide hypersensitivity.\nDo not give to a child with acute illness; if the child has malaria, treat with a specific curative regimen.',
   'SmPC WHO-prequalificada — Sulfadoxine/Pyrimethamine (MA193), secções 4.1, 4.3, 4.4, 4.8: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA193part4v1.pdf',
   'WHO-prequalified SmPC — Sulfadoxine/Pyrimethamine (MA193), sections 4.1, 4.3, 4.4, 4.8: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA193part4v1.pdf'),

  ('ampicilina',
   'A ampicilina é um antibiótico penicilínico de largo espetro, ativo contra várias bactérias Gram-positivas e Gram-negativas. É usada em infeções respiratórias, urinárias, do tubo digestivo e meningite, entre outras. Como todas as penicilinas, pode causar alergia grave (anafilaxia) e erupções cutâneas.',
   'Ampicillin is a broad-spectrum penicillin antibiotic, active against many Gram-positive and Gram-negative bacteria. It is used in respiratory, urinary, gastrointestinal infections and meningitis, among others. Like all penicillins, it can cause severe allergy (anaphylaxis) and skin rashes.',
   'Aminopenicilina bactericida (inibição da síntese da parede celular), estável ao ácido gástrico e bem absorvida por via oral, com espetro alargado a Gram-negativos (E. coli, Salmonella, Shigella, H. influenzae não produtor de penicilinase, Proteus mirabilis, enterococos). Sensível às beta-lactamases. Penetra pouco no LCR exceto com meninges inflamadas; excreção renal predominante, atrasada por probenecida.',
   'Bactericidal aminopenicillin (inhibition of cell-wall synthesis), acid-stable and well absorbed orally, with an extended Gram-negative spectrum (E. coli, Salmonella, Shigella, non-penicillinase-producing H. influenzae, Proteus mirabilis, enterococci). Sensitive to beta-lactamases. Penetrates CSF poorly except with inflamed meninges; predominantly renal excretion, delayed by probenecid.',
   E'Infeções do trato geniturinário (incluindo gonorreia): E. coli, P. mirabilis, enterococos, Shigella, Salmonella, N. gonorrhoeae não produtor de penicilinase.\nInfeções respiratórias: H. influenzae não produtor de penicilinase, estafilococos e estreptococos (incluindo S. pneumoniae).\nInfeções do trato gastrointestinal: Shigella, Salmonella, E. coli, P. mirabilis, enterococos.\nMeningite por N. meningitidis.',
   E'Genitourinary tract infections (including gonorrhoea): E. coli, P. mirabilis, enterococci, Shigella, Salmonella, non-penicillinase-producing N. gonorrhoeae.\nRespiratory tract infections: non-penicillinase-producing H. influenzae, staphylococci and streptococci (including S. pneumoniae).\nGastrointestinal tract infections: Shigella, Salmonella, E. coli, P. mirabilis, enterococci.\nMeningitis due to N. meningitidis.',
   E'Reações de hipersensibilidade (as mais frequentes): erupção maculopapular eritematosa, prurido, urticária, eritema multiforme; reações cutâneas graves (SJS, TEN, DRESS, AGEP); anafilaxia (mais associada à via parentérica).\nGastrintestinais: glossite, estomatite, náuseas, vómitos, enterocolite, colite pseudomembranosa (C. difficile), diarreia.\nHepáticas: elevação moderada das transaminases; disfunção hepática/icterícia colestática (rara).\nHematológicas: anemia, trombocitopenia, eosinofilia, leucopenia, agranulocitose (reversíveis).',
   E'Hypersensitivity reactions (most frequent): erythematous maculopapular rash, pruritus, urticaria, erythema multiforme; severe cutaneous reactions (SJS, TEN, DRESS, AGEP); anaphylaxis (more associated with the parenteral route).\nGastrointestinal: glossitis, stomatitis, nausea, vomiting, enterocolitis, pseudomembranous colitis (C. difficile), diarrhoea.\nHepatic: moderate transaminase elevation; hepatic dysfunction/cholestatic jaundice (rare).\nHaematological: anaemia, thrombocytopenia, eosinophilia, leukopenia, agranulocytosis (reversible).',
   E'Inquirir sempre sobre alergia prévia a penicilinas, cefalosporinas ou outros alergénios antes de iniciar — risco de anafilaxia grave e por vezes fatal.\nContraindicado em hipersensibilidade a beta-lactâmicos, em infeções por organismos produtores de penicilinase e com história de icterícia colestática/disfunção hepática associada à ampicilina.\nVigiar diarreia (possível colite por C. difficile, até 2 meses após o fim).\nVigiar função hepática em doentes com compromisso hepático.\nEm reação cutânea: suspender e monitorizar (podem progredir para SJS/TEN).',
   E'Always enquire about prior allergy to penicillins, cephalosporins or other allergens before starting — risk of severe and occasionally fatal anaphylaxis.\nContraindicated in beta-lactam hypersensitivity, in infections caused by penicillinase-producing organisms, and with a history of cholestatic jaundice/hepatic dysfunction associated with ampicillin.\nMonitor for diarrhoea (possible C. difficile colitis, up to 2 months after completion).\nMonitor liver function in patients with hepatic impairment.\nIf a skin rash occurs: discontinue and monitor closely (may progress to SJS/TEN).',
   'DailyMed/FDA (NIH/NLM) — rótulo Ampicillin Capsules: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4134cd79-c895-4e6e-b1d5-8e01c38bf2d1',
   'DailyMed/FDA (NIH/NLM) — Ampicillin Capsules label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4134cd79-c895-4e6e-b1d5-8e01c38bf2d1'),

  ('lamotrigina',
   'A lamotrigina é um medicamento antiepilético usado na epilepsia (crises parciais, crises tónico-clónicas generalizadas e síndrome de Lennox-Gastaut) e na prevenção de episódios de humor na perturbação bipolar. A dose aumenta-se lentamente para evitar erupções cutâneas, que podem ser graves. Não deve ser suspensa de repente.',
   'Lamotrigine is an antiepileptic medicine used in epilepsy (partial-onset seizures, primary generalised tonic-clonic seizures and Lennox-Gastaut syndrome) and for the maintenance treatment of bipolar disorder. The dose is increased slowly to avoid skin rashes, which can be serious. It should not be stopped suddenly.',
   'Estabilizador de membrana (bloqueio dos canais de sódio dependentes de voltagem) com efeito antiepilético e estabilizador do humor. Indicado como terapêutica adjuvante em crises parciais, crises tónico-clónicas primárias generalizadas e síndrome de Lennox-Gastaut (≥2 anos), na conversão para monoterapia a partir de outros FAEs, e na manutenção da perturbação bipolar I. O risco de erupção cutânea grave (SJS/TEN) impõe titulação lenta; o valproato duplica a semivida e o risco de rash.',
   'Membrane stabiliser (voltage-sensitive sodium channel blockade) with antiepileptic and mood-stabilising effects. Indicated as adjunctive therapy in partial-onset seizures, primary generalised tonic-clonic seizures and Lennox-Gastaut syndrome (≥2 years), for conversion to monotherapy from other AEDs, and for maintenance treatment of bipolar I disorder. The risk of serious skin rash (SJS/TEN) requires slow titration; valproate doubles the half-life and increases the rash risk.',
   E'Epilepsia (adjuvante, ≥2 anos): crises parciais; crises tónico-clónicas primárias generalizadas; crises generalizadas da síndrome de Lennox-Gastaut.\nConversão para monoterapia em adultos (≥16 anos) com crises parciais tratados com carbamazepina, fenitoína, fenobarbital, primidona ou valproato.\nManutenção da perturbação bipolar I — atraso do tempo até novo episódio de humor (depressão, mania, hipomania, episódios mistos).',
   E'Epilepsy (adjunctive, ≥2 years): partial-onset seizures; primary generalised tonic-clonic seizures; generalised seizures of Lennox-Gastaut syndrome.\nConversion to monotherapy in adults (≥16 years) with partial-onset seizures receiving carbamazepine, phenytoin, phenobarbital, primidone or valproate.\nMaintenance treatment of bipolar I disorder — delays the time to occurrence of mood episodes (depression, mania, hypomania, mixed episodes).',
   E'Em epilepsia (adultos, adjuvante): tonturas (38%), ataxia (22%), sonolência (14%), cefaleia (29%), diplopia (28%), visão turva (16%), náuseas (19%), vómitos, rash (10%), prurido.\nDose-dependentes: ataxia, diplopia, visão turva, tonturas, náuseas, vómitos.\nRash (incluindo rash grave/SJS) — mais frequente com valproato e com titulação rápida; 0,08-0,13% de rash grave nos adultos.\nEm pediatria: infeção, vómitos, rash, febre, sonolência, ataxia.\nNa bipolaridade: cefaleia (25%), rash (11%), tonturas (10%), diarreia (8%).\nPensamentos/comportamento suicida (risco de classe).',
   E'In epilepsy (adults, adjunctive): dizziness (38%), ataxia (22%), somnolence (14%), headache (29%), diplopia (28%), blurred vision (16%), nausea (19%), vomiting, rash (10%), pruritus.\nDose-related: ataxia, diplopia, blurred vision, dizziness, nausea, vomiting.\nRash (including serious rash/SJS) — more frequent with valproate and rapid titration; 0.08-0.13% serious rash in adults.\nIn paediatrics: infection, vomiting, rash, fever, somnolence, ataxia.\nIn bipolar disorder: headache (25%), rash (11%), dizziness (10%), diarrhoea (8%).\nSuicidal thoughts/behaviour (class risk).',
   E'Suspender imediatamente se surgir rash, exceto se claramente não relacionado — risco de SJS/TEN, sobretudo nas primeiras 8 semanas e com titulação rápida.\nNunca suspender bruscamente (risco de crises de privação); reduzir gradualmente.\nCom valproato: reduzir a dose para metade e titulação mais lenta (semivida ~59 h; risco de rash aumentado).\nCom indutores enzimáticos (carbamazepina, fenitoína, fenobarbital, primidona, rifampicina): dose mais elevada necessária.\nVigiar sinais de pensamentos suicidas.\nContraindicado em hipersensibilidade à lamotrigina.',
   E'Discontinue immediately if a rash appears, unless clearly unrelated — risk of SJS/TEN, mainly in the first 8 weeks and with rapid titration.\nNever stop abruptly (risk of withdrawal seizures); taper gradually.\nWith valproate: halve the dose and titrate more slowly (half-life ~59 h; increased rash risk).\nWith enzyme inducers (carbamazepine, phenytoin, phenobarbital, primidone, rifampin): higher dose required.\nMonitor for signs of suicidal ideation.\nContraindicated in hypersensitivity to lamotrigine.',
   'DailyMed/FDA (NIH/NLM) — rótulo Lamotrigine Tablets (Alembic): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=60958229-5b5f-49e2-97f4-a8722138f7ce',
   'DailyMed/FDA (NIH/NLM) — Lamotrigine Tablets label (Alembic): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=60958229-5b5f-49e2-97f4-a8722138f7ce'),

  ('haloperidol',
   'O haloperidol é um antipsicótico clássico usado no tratamento das manifestações de doenças psicóticas (como a esquizofrenia), na síndrome de Tourette e em problemas graves de comportamento em crianças. É eficaz mas pode causar efeitos extrapiramidais (movimentos involuntários, rigidez), que devem ser vigiados.',
   'Haloperidol is a classical antipsychotic used to treat the manifestations of psychotic disorders (such as schizophrenia), Tourette syndrome and severe behavioural problems in children. It is effective but can cause extrapyramidal effects (involuntary movements, rigidity) that must be monitored.',
   'Antipsicótico típico (butirofenona), antagonista dopaminérgico D2. Indicado no tratamento das manifestações das doenças psicóticas, no controlo dos tiques da síndrome de Tourette e em problemas graves de comportamento em crianças. Antagonista D2 potente com elevado risco extrapiramidal (distonia, acatisia, parkinsonismo, discinesia tardia), prolongamento do QT e síndrome neuroléptica maligna. Não aprovado na psicose associada a demência (aumento da mortalidade).',
   'Typical antipsychotic (butyrophenone), dopamine D2 antagonist. Indicated for the management of the manifestations of psychotic disorders, control of tics in Tourette syndrome and severe behavioural problems in children. Potent D2 antagonist with a high risk of extrapyramidal effects (dystonia, akathisia, parkinsonism, tardive dyskinesia), QT prolongation and neuroleptic malignant syndrome. Not approved for dementia-related psychosis (increased mortality).',
   E'Tratamento das manifestações de doenças psicóticas.\nControlo dos tiques e vocalizações da síndrome de Tourette em crianças e adultos.\nTratamento de problemas graves de comportamento em crianças (hiperexcitabilidade explosiva) e tratamento de curta duração de crianças hiperativas com perturbação de conduta — após falência de psicoterapia ou medicação não antipsicótica.',
   E'Management of the manifestations of psychotic disorders.\nControl of tics and vocal utterances of Tourette syndrome in children and adults.\nTreatment of severe behaviour problems in children (combative, explosive hyperexcitability) and short-term treatment of hyperactive children with conduct disorder — after failure of psychotherapy or non-antipsychotic medication.',
   E'Efeitos extrapiramidais (frequentes, sobretudo nos primeiros dias): sintomas parkinsonianos, acatisia, distonia (incluindo crise oculógira e opistótono).\nDiscinesia tardia (potencialmente irreversível) em tratamentos prolongados — maior risco em idosos e mulheres.\nSíndrome neuroléptica maligna (hiperpirexia, rigidez, alteração do estado mental).\nProlongamento do QT e arritmias ventriculares (torsades de pointes), morte súbita — mais com altas doses.\nSonolência, insónia, agitação, ansiedade, depressão, convulsões.\nEfeitos anticolinérgicos: boca seca, visão turva, retenção urinária.\nHipotenção ortostática e quedas.',
   E'Extrapyramidal effects (frequent, mainly in the first days): parkinsonian symptoms, akathisia, dystonia (including oculogyric crisis and opisthotonos).\nTardive dyskinesia (potentially irreversible) in long-term treatment — higher risk in the elderly and women.\nNeuroleptic malignant syndrome (hyperpyrexia, rigidity, altered mental status).\nQT prolongation and ventricular arrhythmias (torsades de pointes), sudden death — more with high doses.\nSomnolence, insomnia, agitation, anxiety, depression, seizures.\nAnticholinergic effects: dry mouth, blurred vision, urinary retention.\nOrthostatic hypotension and falls.',
   E'Não usar em doentes idosos com psicose associada a demência (aumento do risco de morte) nem em depressão grave do SNC/estado comatoso, hipersensibilidade ou doença de Parkinson.\nVigiar QT (hipocaliemia/hipomagnesemia, fármacos que prolongam o QT, doença cardíaca, hipotiroidismo, síndrome QT longo familiar).\nAvaliar risco de quedas (sonolência, hipotensão postural).\nEvitar álcool (efeitos aditivos e hipotensão).\nAssociação com lítio: vigiar sinais de encefalopatia.\nRetirar gradualmente em tratamentos prolongados.',
   E'Do not use in elderly patients with dementia-related psychosis (increased risk of death) nor in severe CNS depression/coma, hypersensitivity or Parkinson disease.\nMonitor QT (hypokalaemia/hypomagnesaemia, QT-prolonging drugs, cardiac disease, hypothyroidism, familial long QT syndrome).\nAssess fall risk (somnolence, postural hypotension).\nAvoid alcohol (additive effects and hypotension).\nWith lithium: monitor for signs of encephalopathy.\nWithdraw gradually after prolonged treatment.',
   'DailyMed/FDA (NIH/NLM) — rótulo Haloperidol Tablets (Upsher-Smith) + Kudo S, Ishizaki T. Clin Pharmacokinet 1999 (PMID 10628896): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb3ac3e-7459-42d3-b5ca-e0d6d27ced73',
   'DailyMed/FDA (NIH/NLM) — Haloperidol Tablets label (Upsher-Smith) + Kudo S, Ishizaki T. Clin Pharmacokinet 1999 (PMID 10628896): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb3ac3e-7459-42d3-b5ca-e0d6d27ced73'),

  ('clozapina',
   'A clozapina é um antipsicótico reservado para a esquizofrenia resistente ao tratamento habitual e para reduzir o risco de comportamentos suicidas repetidos na esquizofrenia ou perturbação esquizoafetiva. É muito eficaz, mas exige vigilância apertada: pode causar diminuição grave dos neutrófilos (agranulocitose), pelo que são obrigatórias análises ao sangue regulares.',
   'Clozapine is an antipsychotic reserved for treatment-resistant schizophrenia and for reducing the risk of recurrent suicidal behaviour in schizophrenia or schizoaffective disorder. It is highly effective but requires close monitoring: it can cause severe neutropenia (agranulocytosis), so regular blood tests are mandatory.',
   'Antipsicótico atípico com afinidade por múltiplos recetores (D2, 5-HT2A, H1, M1, adrenérgicos). Reservado a doentes com esquizofrenia grave que não responderam ao tratamento antipsicótico padrão e à redução do risco de comportamento suicida recorrente. Eficácia comprovada, mas perfil de segurança exigente: neutropenia grave (obriga a monitorização hematológica), miocardite, convulsões, hipomotilidade gastrointestinal, alterações metabólicas e prolongamento do QT.',
   'Atypical antipsychotic with affinity for multiple receptors (D2, 5-HT2A, H1, M1, adrenergic). Reserved for severely ill patients with schizophrenia who fail standard antipsychotic treatment and for reducing the risk of recurrent suicidal behaviour. Proven efficacy, but a demanding safety profile: severe neutropenia (mandatory haematological monitoring), myocarditis, seizures, gastrointestinal hypomotility, metabolic changes and QT prolongation.',
   E'Esquizofrenia resistente ao tratamento (doentes graves que não responderam adequadamente a antipsicóticos padrão).\nRedução do risco de comportamento suicida recorrente em doentes com esquizofrenia ou perturbação esquizoafetiva em risco crónico.',
   E'Treatment-resistant schizophrenia (severely ill patients who fail to respond adequately to standard antipsychotic treatment).\nReducing the risk of recurrent suicidal behaviour in patients with schizophrenia or schizoaffective disorder judged to be at chronic risk.',
   E'Sedação/sonolência (39%), sialorreia (31-48%), taquicardia (17-25%), tonturas (14-19%), obstipação (14-25%), hipotensão (9-13%), cefaleia (7-10%), náuseas/vómitos, febre, ganho de peso (4-31%).\nNeutropenia grave/agranulocitose (obriga a monitorização hematológica).\nConvulsões (3%, dose-dependentes).\nMiocardite, pericardite, cardiomiopatia (raras mas graves).\nAlterações metabólicas: hiperglicemia/diabetes, dislipidemia, ganho de peso.\nHipersalivação, obstipação grave (íleo), síndrome neuroléptica maligna, discinesia tardia.',
   E'Sedation/somnolence (39%), hypersalivation (31-48%), tachycardia (17-25%), dizziness (14-19%), constipation (14-25%), hypotension (9-13%), headache (7-10%), nausea/vomiting, fever, weight gain (4-31%).\nSevere neutropenia/agranulocytosis (mandatory haematological monitoring).\nSeizures (3%, dose-dependent).\nMyocarditis, pericarditis, cardiomyopathy (rare but serious).\nMetabolic changes: hyperglycaemia/diabetes, dyslipidaemia, weight gain.\nHypersalivation, severe constipation (ileus), neuroleptic malignant syndrome, tardive dyskinesia.',
   E'Usar apenas em doentes que falharam o tratamento antipsicótico padrão — riscos de neutropenia grave e convulsões.\nMonitorização hematológica obrigatória (neutrófilos) — regras do programa de vigilância; suspender se neutropenia grave.\nVigiar sinais de miocardite/pericardite (febre, dor torácica, taquicardia) sobretudo nas primeiras semanas.\nVigiar obstipação grave/íleo (hipomotilidade GI), sintomas ortostáticos e quedas, glicemia/lípidos/peso.\nNunca suspender bruscamente (recorrência psicótica e rebote colinérgico).\nContraindicado em hipersensibilidade à clozapina.',
   E'Use only in patients who failed standard antipsychotic treatment — risks of severe neutropenia and seizures.\nMandatory haematological monitoring (neutrophils) — surveillance programme rules; discontinue if severe neutropenia.\nMonitor for myocarditis/pericarditis (fever, chest pain, tachycardia), especially in the first weeks.\nMonitor for severe constipation/ileus (GI hypomotility), orthostatic symptoms and falls, glucose/lipids/weight.\nNever stop abruptly (psychotic recurrence and cholinergic rebound).\nContraindicated in hypersensitivity to clozapine.',
   'DailyMed/FDA (NIH/NLM) — rótulo Clozapine Tablets (Aurobindo): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5021d643-32d2-4167-b5d8-90870e68a787',
   'DailyMed/FDA (NIH/NLM) — Clozapine Tablets label (Aurobindo): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5021d643-32d2-4167-b5d8-90870e68a787'),
  ('acido_folico',
   'O ácido fólico (vitamina B9) é usado no tratamento das anemias megaloblásticas por défice de folato, incluindo as anemias de origem nutricional, da gravidez, da infância e associadas a doença celíaca. É uma vitamina essencial para a formação das células do sangue. A suplementação de 0,4 mg/dia é recomendada na gravidez para prevenir defeitos do tubo neural.',
   'Folic acid (vitamin B9) is used to treat megaloblastic anaemias due to folate deficiency, including anaemias of nutritional origin, pregnancy, infancy and childhood, and those associated with coeliac disease. It is an essential vitamin for blood cell formation. Supplementation of 0.4 mg/day is recommended in pregnancy to prevent neural tube defects.',
   'Vitamina hidrossolúvel (folato) essencial para a síntese de nucleoproteínas e eritropoiese normal; precursora do tetrahidrofolato, cofator nas reações de transformilação (síntese de purinas e timidilatos). Indicada nas anemias megaloblásticas por défice de folato (sprue tropical/não tropical, causas nutricionais, gravidez, infância). Importante: NÃO tratar a anemia perniciosa com ácido fólico isolado (mascara a défice de B12 e permite progressão neurológica).',
   'Water-soluble vitamin (folate) essential for nucleoprotein synthesis and normal erythropoiesis; precursor of tetrahydrofolate, a cofactor in transformylation reactions (purine and thymidylate synthesis). Indicated in megaloblastic anaemias due to folate deficiency (tropical/nontropical sprue, nutritional causes, pregnancy, infancy). Important: do NOT treat pernicious anaemia with folic acid alone (masks B12 deficiency and allows neurological progression).',
   E'Anemias megaloblásticas por défice de ácido fólico (sprue tropical ou não tropical, anemia de origem nutricional, da gravidez, da infância).\nPrevenção de defeitos do tubo neural na gravidez (suplementação de 0,4 mg/dia — uso consensual, fora do rótulo americano).',
   E'Megaloblastic anaemias due to folic acid deficiency (tropical or nontropical sprue, anaemias of nutritional origin, pregnancy, infancy or childhood).\nPrevention of neural tube defects in pregnancy (0.4 mg/day supplementation — consensus use, outside the US label).',
   E'Relativamente atóxico; reações alérgicas raras (eritema, erupção cutânea, prurido, mal-estar, broncospasmo; anafilaxia reportada após injeção).\nEm doses altas (15 mg/dia): anorexia, náuseas, distensão abdominal, flatulência, alterações do sono, irritabilidade, depressão, confusão.\nPode diminuir os níveis séricos de B12 em terapêutica prolongada.\nPode aumentar a frequência de crises em doentes epiléticos tratados com fenobarbital, primidona ou fenitoína, e diminuir os níveis de fenitoína.',
   E'Relatively nontoxic; rare allergic reactions (erythema, skin rash, itching, malaise, bronchospasm; anaphylaxis reported after injection).\nAt high doses (15 mg/day): anorexia, nausea, abdominal distension, flatulence, sleep disturbances, irritability, depression, confusion.\nMay decrease serum B12 levels with prolonged therapy.\nMay increase seizure frequency in epileptic patients on phenobarbital, primidone or phenytoin, and lower phenytoin levels.',
   E'O ácido fólico isolado é terapêutica inadequada na anemia perniciosa e noutras anemias megaloblásticas com défice de vitamina B12 — pode mascarar a anemia e permitir a progressão neurológica.\nContraindicado em doentes com intolerância prévia.\nAntes de iniciar, excluir défice de B12 (dosear B12/folato).\nNa gravidez: dose habitual 0,4 mg/dia; doses ≥5 mg/dia contraindicadas com sulfadoxina-pirimetamina (neutralizam a eficácia antimalárica).',
   E'Folic acid alone is improper therapy for pernicious anaemia and other megaloblastic anaemias with vitamin B12 deficiency — it can mask the anaemia and allow neurological progression.\nContraindicated in patients with previous intolerance.\nBefore starting, exclude B12 deficiency (measure B12/folate).\nIn pregnancy: usual dose 0.4 mg/day; doses ≥5 mg/day contraindicated with sulfadoxine-pyrimethamine (counteract antimalarial efficacy).',
   'DailyMed/FDA (NIH/NLM) — rótulo Folic Acid Tablets: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0baa10dd-6d1d-4946-8236-566451132da3',
   'DailyMed/FDA (NIH/NLM) — Folic Acid Tablets label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0baa10dd-6d1d-4946-8236-566451132da3'),

  ('amicacina',
   'A amicacina é um antibiótico aminoglicosídeo administrado por injeção, usado no tratamento de infeções graves por bactérias Gram-negativas (incluindo Pseudomonas, E. coli e Klebsiella), sobretudo em ambiente hospitalar. É eficaz, mas pode lesar os rins (nefrotoxicidade) e o ouvido interno (ototoxicidade), pelo que requer vigilância apertada e monitorização dos níveis no sangue.',
   'Amikacin is an aminoglycoside antibiotic given by injection, used to treat serious infections caused by Gram-negative bacteria (including Pseudomonas, E. coli and Klebsiella), mainly in hospital. It is effective but can damage the kidneys (nephrotoxicity) and the inner ear (ototoxicity), so close monitoring and blood level monitoring are required.',
   'Aminoglicosídeo bactericida (ligação ao ribossoma procariótico, inibição da síntese proteica), ativo contra Gram-negativos, incluindo estirpes resistentes à gentamicina/tobramicina (Proteus rettgeri, Providencia stuartii, Serratia marcescens, Pseudomonas aeruginosa), e alguns estafilococos. Reservado a infeções graves (sepse, respiratórias, ósseas, SNC, intra-abdominais, urinárias complicadas). Risco de ototoxicidade (predominantemente auditiva), nefrotoxicidade e bloqueio neuromuscular; a monitorização de níveis e função renal é essencial.',
   'Bactericidal aminoglycoside (binds the prokaryotic ribosome, inhibits protein synthesis), active against Gram-negatives, including gentamicin/tobramycin-resistant strains (Proteus rettgeri, Providencia stuartii, Serratia marcescens, Pseudomonas aeruginosa), and some staphylococci. Reserved for serious infections (septicaemia, respiratory, bone, CNS, intra-abdominal, complicated UTI). Risk of ototoxicity (predominantly auditory), nephrotoxicity and neuromuscular blockade; monitoring of levels and renal function is essential.',
   E'Tratamento de curta duração de infeções graves por estirpes suscetíveis de bactérias Gram-negativas: Pseudomonas, E. coli, Proteus (indol-positivo e negativo), Providencia, Klebsiella-Enterobacter-Serratia, Acinetobacter.\nSepsis bacteriana (incluindo sépsis neonatal), infeções respiratórias, ósseas e articulares, SNC (incluindo meningite), pele e tecidos moles, intra-abdominais (peritonite), queimaduras e infeções pós-operatórias.\nInfeções urinárias complicadas e recorrentes; infeções por estafilococos (em condições específicas).',
   E'Short-term treatment of serious infections due to susceptible Gram-negative strains: Pseudomonas, E. coli, Proteus (indole-positive and negative), Providencia, Klebsiella-Enterobacter-Serratia, Acinetobacter.\nBacterial septicaemia (including neonatal sepsis), respiratory, bone and joint infections, CNS (including meningitis), skin and soft tissue, intra-abdominal (peritonitis), burns and postoperative infections.\nComplicated and recurrent urinary tract infections; staphylococcal infections (under specific conditions).',
   E'Ototoxicidade auditiva (perda auditiva de alta frequência, geralmente antes da surdez clínica) e vestibular; nefrotoxicidade (elevação da creatinina, albuminúria, cilindros, azotemia, oligúria — geralmente reversível).\nBloqueio neuromuscular (paralisia muscular aguda e apneia).\nOutros: erupção cutânea, febre medicamentosa, cefaleia, parestesias, tremor, náuseas, eosinofilia, anemia, hipotensão, hipomagnesemia.\nO risco é maior com função renal comprometida, doses altas/duração prolongada e associação com outros ototóxicos/nefrotóxicos.',
   E'Auditory ototoxicity (high-frequency hearing loss, usually before clinical deafness) and vestibular toxicity; nephrotoxicity (raised creatinine, albuminuria, casts, azotaemia, oliguria — usually reversible).\nNeuromuscular blockade (acute muscular paralysis and apnoea).\nOthers: skin rash, drug fever, headache, paraesthesia, tremor, nausea, eosinophilia, anaemia, hypotension, hypomagnesaemia.\nRisk is higher with impaired renal function, high doses/prolonged duration and combination with other ototoxic/nephrotoxic drugs.',
   E'Vigiar função renal (creatinina) e níveis séricos; ajustar dose na insuficiência renal.\nAvaliar audição em tratamentos prolongados ou em doentes de risco (ototoxicidade pode ser irreversível).\nHistória de hipersensibilidade à amicacina ou reações graves a aminoglicosídeos contraindica o uso (reactividade cruzada).\nVigiar sinais de bloqueio neuromuscular, sobretudo com relaxantes musculares.\nEvitar associação com outros fármacos ototóxicos/nefrotóxicos (diuréticos de ansa, outros aminoglicosídeos, vancomicina).\nNa gravidez, avaliar o risco fetal (atravessa a placenta).',
   E'Monitor renal function (creatinine) and serum levels; adjust dose in renal impairment.\nAssess hearing in prolonged treatment or at-risk patients (ototoxicity may be irreversible).\nHistory of hypersensitivity to amikacin or serious reactions to aminoglycosides contraindicates use (cross-reactivity).\nMonitor for neuromuscular blockade, especially with muscle relaxants.\nAvoid combination with other ototoxic/nephrotoxic drugs (loop diuretics, other aminoglycosides, vancomycin).\nIn pregnancy, weigh fetal risk (crosses the placenta).',
   'DailyMed/FDA (NIH/NLM) — rótulo Amikacin Sulfate Injection (Sagent): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f260ff2a-76a0-4672-9516-91c344b67890',
   'DailyMed/FDA (NIH/NLM) — Amikacin Sulfate Injection label (Sagent): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f260ff2a-76a0-4672-9516-91c344b67890'),

  ('azitromicina',
   'A azitromicina é um antibiótico macrólido usado no tratamento de várias infeções respiratórias, da pele e de transmissão sexual, entre outras. Toma-se por via oral, geralmente em esquemas curtos (3 a 5 dias), porque permanece muito tempo nos tecidos. É geralmente bem tolerada; os efeitos mais comuns são gastrointestinais.',
   'Azithromycin is a macrolide antibiotic used to treat various respiratory, skin and sexually transmitted infections, among others. It is taken orally, usually in short courses (3 to 5 days), because it persists for a long time in tissues. It is generally well tolerated; the most common effects are gastrointestinal.',
   'Macrólido azalida bacteriostático (ligação à subunidade 50S do ribossoma bacteriano, inibição da síntese proteica), com extensa distribuição tecidual e semivida terminal longa (~68 h), o que permite esquemas curtos. Espetro: Gram-positivos, atípicos (Mycoplasma, Chlamydia, Legionella), H. influenzae e M. catarrhalis. Pode prolongar o intervalo QT (dose-dependente); interação com antiácidos (redução do pico).',
   'Bacteriostatic azalide macrolide (binds the bacterial 50S ribosomal subunit, inhibits protein synthesis), with extensive tissue distribution and a long terminal half-life (~68 h), allowing short courses. Spectrum: Gram-positives, atypicals (Mycoplasma, Chlamydia, Legionella), H. influenzae and M. catarrhalis. May prolong the QT interval (dose-dependent); interacts with antacids (reduced peak).',
   E'Infeções do trato respiratório superior e inferior (faringite/amigdalite, sinusite bacteriana aguda, otite média aguda, pneumonia adquirida na comunidade, bronquite).\nInfeções da pele e tecidos moles não complicadas.\nUretrite/cervicite por Chlamydia trachomatis e uretrite não gonocócica; cancroide; infeções por Mycobacterium avium (profilaxia e tratamento em doentes com VIH).',
   E'Upper and lower respiratory tract infections (pharyngitis/tonsillitis, acute bacterial sinusitis, acute otitis media, community-acquired pneumonia, bronchitis).\nUncomplicated skin and soft tissue infections.\nUrethritis/cervicitis due to Chlamydia trachomatis and non-gonococcal urethritis; chancroid; Mycobacterium avium infections (prophylaxis and treatment in HIV patients).',
   E'Gastrointestinais (os mais frequentes): diarreia, náuseas, dor abdominal, vómitos, dispepsia, flatulência.\nCefaleia, tonturas, sonolência.\nProlongamento do intervalo QT (dose-dependente; risco de torsades de pointes, sobretudo em idosos e com fatores de risco).\nReações de hipersensibilidade (rash, prurido, angioedema; raramente SJS/TEN, DRESS, anafilaxia).\nHepatotoxicidade (rara, incluindo falência hepática).\nColite por C. difficile.',
   E'Gastrointestinal (most frequent): diarrhoea, nausea, abdominal pain, vomiting, dyspepsia, flatulence.\nHeadache, dizziness, somnolence.\nQT interval prolongation (dose-dependent; risk of torsades de pointes, especially in the elderly and with risk factors).\nHypersensitivity reactions (rash, pruritus, angioedema; rarely SJS/TEN, DRESS, anaphylaxis).\nHepatotoxicity (rare, including hepatic failure).\nC. difficile colitis.',
   E'Vigiar risco de QT prolongado em doentes com fatores de risco (hipocaliemia, bradicardia, fármacos que prolongam o QT, idosos).\nNÃO tomar com antiácidos contendo alumínio/magnésio (reduzem o pico plasmático) — separar 2 horas.\nVigiar sinais de hepatotoxicidade (icterícia, urina escura).\nContraindicado na hipersensibilidade a macrólidos (azitromicina, eritromicina, claritromicina).\nSuspender se surgirem reações cutâneas graves.\nCautela na miastenia gravis (pode agravar) e em doentes com doença hepática grave.',
   E'Monitor QT risk in patients with risk factors (hypokalaemia, bradycardia, QT-prolonging drugs, elderly).\nDo NOT take with aluminium/magnesium antacids (reduce peak plasma levels) — separate by 2 hours.\nMonitor for signs of hepatotoxicity (jaundice, dark urine).\nContraindicated in macrolide hypersensitivity (azithromycin, erythromycin, clarithromycin).\nDiscontinue if severe skin reactions occur.\nCaution in myasthenia gravis (may worsen) and in severe liver disease.',
   'DailyMed/FDA (NIH/NLM) — rótulo Zithromax (Pfizer): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=db52b91e-79f7-4cc1-9564-f2eee8e31c45',
   'DailyMed/FDA (NIH/NLM) — Zithromax label (Pfizer): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=db52b91e-79f7-4cc1-9564-f2eee8e31c45'),

  ('bumetanida',
   'A bumetanida é um diurético de ansa, usado no tratamento da retenção de líquidos (edema) associada a insuficiência cardíaca, doença hepática e doença renal, incluindo síndrome nefrótica. É mais potente que a furosemida (1 mg ≈ 40 mg de furosemida) e atua rapidamente. Exige vigilância dos eletrólitos e da função renal.',
   'Bumetanide is a loop diuretic used to treat fluid retention (oedema) associated with heart failure, liver disease and kidney disease, including nephrotic syndrome. It is more potent than furosemide (1 mg ≈ 40 mg of furosemide) and acts rapidly. Electrolytes and renal function must be monitored.',
   'Diurético de ansa de início rápido e curta duração, 40-60 vezes mais potente que a furosemida (1 mg ≈ 40 mg). Inibe a reabsorção de sódio e cloro no ramo ascendente da ansa de Henle; aumenta a excreção de potássio, cálcio e magnésio; reduz a excreção de ácido úrico (hiperuricemia). Indicado no edema da insuficiência cardíaca, hepática e renal (incluindo síndrome nefrótica).',
   'Loop diuretic with rapid onset and short duration, 40-60 times more potent than furosemide (1 mg ≈ 40 mg). Inhibits sodium and chloride reabsorption in the ascending limb of the loop of Henle; increases potassium, calcium and magnesium excretion; reduces uric acid excretion (hyperuricaemia). Indicated for oedema in heart failure, hepatic and renal disease (including nephrotic syndrome).',
   E'Tratamento do edema associado a insuficiência cardíaca congestiva, doença hepática e doença renal, incluindo síndrome nefrótica.',
   E'Treatment of oedema associated with congestive heart failure, hepatic and renal disease, including nephrotic syndrome.',
   E'Cãibras musculares (1,1%), tonturas (1,1%), hipotensão (0,8%), cefaleia (0,6%), náuseas (0,6%), encefalopatia em doentes com doença hepática prévia (0,6%).\nAlterações laboratoriais frequentes: hiperuricemia (18,4%), hipocloremia (14,9%), hipocaliemia (14,7%), azotemia (10,6%), hiponatremia (9,2%), aumento da creatinina (7,4%), hiperglicemia (6,6%).\nPerda auditiva/ototoxicidade (0,5%) — sobretudo IV em altas doses; risco com aminoglicosídeos.\nReações cutâneas graves (SJS/TEN) — reportadas.\nTrombocitopenia (raras).',
   E'Muscle cramps (1.1%), dizziness (1.1%), hypotension (0.8%), headache (0.6%), nausea (0.6%), encephalopathy in patients with pre-existing liver disease (0.6%).\nFrequent laboratory changes: hyperuricaemia (18.4%), hypochloraemia (14.9%), hypokalaemia (14.7%), azotaemia (10.6%), hyponatraemia (9.2%), increased creatinine (7.4%), hyperglycaemia (6.6%).\nHearing loss/ototoxicity (0.5%) — mainly IV at high doses; risk with aminoglycosides.\nSevere skin reactions (SJS/TEN) — reported.\nThrombocytopenia (rare).',
   E'Contraindicado na anúria, no coma hepático ou em depleção eletrolítica grave até correção.\nDoses excessivas/frequentes → perda profunda de água e eletrólitos, depleção do volume, colapso circulatório (risco de trombose/embolia, sobretudo em idosos).\nHipocaliemia: atenção redobrada com digitálicos, cirrose com ascite, arritmias ventriculares prévias; suplementar potássio/espironolactona na cirrose.\nEm cirrose com ascite, iniciar em ambiente hospitalar com doses pequenas (risco de encefalopatia/coma).\nAlergia a sulfonamidas: possível hipersensibilidade cruzada.\nVigiar trombocitopenia.',
   E'Contraindicated in anuria, hepatic coma, or severe electrolyte depletion until corrected.\nExcessive/frequent doses → profound water and electrolyte loss, volume depletion, circulatory collapse (risk of thrombosis/embolism, especially in the elderly).\nHypokalaemia: extra caution with digitalis, cirrhosis with ascites, previous ventricular arrhythmias; supplement potassium/spironolactone in cirrhosis.\nIn cirrhosis with ascites, start in hospital with small doses (risk of encephalopathy/coma).\nSulfonamide allergy: possible cross-hypersensitivity.\nMonitor for thrombocytopenia.',
   'DailyMed/FDA (NIH/NLM) — rótulo Bumetanide Tablets (Sandoz): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8914d8bf-61b7-4cd2-a8ef-7e1c5df37828',
   'DailyMed/FDA (NIH/NLM) — Bumetanide Tablets label (Sandoz): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8914d8bf-61b7-4cd2-a8ef-7e1c5df37828'),

  ('buprenorfina',
   'A buprenorfina é um medicamento opióide usado no tratamento de substituição da dependência de opióides (como a heroína), em comprimidos sublinguais. Reduz os sintomas de privação e o desejo pela droga, com efeito máximo limitado (efeito teto) que diminui o risco de depressão respiratória grave em comparação com agonistas totais. Só deve ser usada sob prescrição e acompanhamento especializado.',
   'Buprenorphine is an opioid medicine used for the substitution treatment of opioid dependence (such as heroin), as sublingual tablets. It reduces withdrawal symptoms and drug craving, with a ceiling effect that lowers the risk of severe respiratory depression compared with full agonists. It must only be used under prescription and specialist follow-up.',
   'Agonista parcial dos recetores opióides mu (com efeito teto na depressão respiratória), antagonista dos recetores kappa. Indicado no tratamento da dependência de opióides (em monoterapia ou com naloxona). Biodisponibilidade sublingual com semivida longa (31-35 h) que permite toma diária; metabolizado por CYP3A4. Menor risco de depressão respiratória que os agonistas totais, mas risco de desvio/abuso; QT prolongado ≤15 ms nos estudos.',
   'Partial mu-opioid receptor agonist (with a ceiling effect on respiratory depression), kappa antagonist. Indicated for the treatment of opioid dependence (alone or with naloxone). Sublingual bioavailability with a long half-life (31-35 h) allowing daily dosing; metabolised by CYP3A4. Lower risk of respiratory depression than full agonists, but risk of diversion/abuse; QT prolongation ≤15 ms in studies.',
   E'Tratamento da dependência de opióides (manutenção e descontinuação), como parte de um programa de tratamento integrado (médico, psicológico, social).',
   E'Treatment of opioid dependence (maintenance and discontinuation), as part of an integrated treatment programme (medical, psychological, social).',
   E'Síndrome de privação de opióides (quando iniciada cedo demais).\nObstipação, náuseas, vómitos, sudorese, insónia.\nSedação, sonolência, tonturas, cefaleia.\nSíndrome de privação neonatal em recém-nascidos de mães tratadas.\nHepatotoxicidade (raras, sobretudo com doença hepática prévia).\nHipoventilação (mais frequente com doses ≥4 mg sublingual do que com metadona).\nProlongamento do QT (≤15 ms).',
   E'Opioid withdrawal syndrome (when started too early).\nConstipation, nausea, vomiting, sweating, insomnia.\nSedation, somnolence, dizziness, headache.\nNeonatal opioid withdrawal syndrome in newborns of treated mothers.\nHepatotoxicity (rare, mainly with pre-existing liver disease).\nHypoventilation (more frequent with sublingual doses ≥4 mg than with methadone).\nQT prolongation (≤15 ms).',
   E'Medicamento sujeito a controlo especial — risco de dependência, abuso e desvio; avaliar risco antes de prescrever.\nNÃO iniciar antes de sinais objetivos de privação (risco de síndrome de privação precipitada).\nInterações com depressores do SNC (benzodiazepinas, álcool) — risco de sedação profunda e morte.\nNão usar com agonistas totais (pode precipitar privação) — exceto na transição supervisionada.\nInsuficiência hepática moderada/grave: reduzir dose e vigiar (aumento de exposição e semivida).\nEvitar na gravidez exceto se o benefício justificar (síndrome de privação neonatal).',
   E'Controlled medicine — risk of dependence, abuse and diversion; assess risk before prescribing.\nDo NOT start before objective signs of withdrawal (risk of precipitated withdrawal syndrome).\nInteractions with CNS depressants (benzodiazepines, alcohol) — risk of profound sedation and death.\nDo not use with full agonists (may precipitate withdrawal) — except in supervised transition.\nModerate/severe hepatic impairment: reduce dose and monitor (increased exposure and half-life).\nAvoid in pregnancy unless benefit justifies (neonatal withdrawal syndrome).',
   'DailyMed/FDA (NIH/NLM) — rótulo Buprenorphine HCl Sublingual Tablets (SpecGx): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b60d514d-a88a-4fa2-a5b0-30ac29e04973',
   'DailyMed/FDA (NIH/NLM) — Buprenorphine HCl Sublingual Tablets label (SpecGx): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b60d514d-a88a-4fa2-a5b0-30ac29e04973'),
  ('celecoxib',
   'O celecoxib é um anti-inflamatório não esteroide (AINE) do grupo dos inibidores seletivos da COX-2, usado na artrose, artrite reumatoide, espondilite anquilosante, dor aguda e cólicas menstruais. Tem menor risco de irritação gástrica do que os AINE clássicos, mas mantém os riscos cardiovasculares e renais da classe.',
   'Celecoxib is a nonsteroidal anti-inflammatory drug (NSAID) of the selective COX-2 inhibitor group, used in osteoarthritis, rheumatoid arthritis, ankylosing spondylitis, acute pain and menstrual cramps. It has a lower risk of gastric irritation than classic NSAIDs, but retains the cardiovascular and renal risks of the class.',
   'AINE seletivo da COX-2 (inibição preferencial da prostaglandina sintase-2), com analgesia, anti-inflamação e antipirése e menor interferência plaquetária do que os AINE não seletivos. Indicado na artrose, artrite reumatoide, artrite reumatoide juvenil (≥2 anos), espondilite anquilosante, dor aguda e dismenorreia primária. Metabolizado por CYP2C9. Mantém os riscos cardiovasculares, GI e renais da classe.',
   'COX-2 selective NSAID (preferential inhibition of prostaglandin synthase-2), providing analgesia, anti-inflammation and antipyresis with less platelet interference than non-selective NSAIDs. Indicated in osteoarthritis, rheumatoid arthritis, juvenile rheumatoid arthritis (≥2 years), ankylosing spondylitis, acute pain and primary dysmenorrhoea. Metabolised by CYP2C9. Retains the cardiovascular, GI and renal risks of the class.',
   E'Artrose — controlo dos sinais e sintomas.\nArtrite reumatoide — controlo dos sinais e sintomas.\nArtrite reumatoide juvenil (≥2 anos).\nEspondilite anquilosante.\nDor aguda em adultos.\nDismenorreia primária.',
   E'Osteoarthritis — management of signs and symptoms.\nRheumatoid arthritis — management of signs and symptoms.\nJuvenile rheumatoid arthritis (≥2 years).\nAnkylosing spondylitis.\nAcute pain in adults.\nPrimary dysmenorrhoea.',
   E'Gastrointestinais: dispepsia (8,8%), diarreia (5,6%), dor abdominal (4,1%), flatulência, náuseas, vómitos.\nCefaleia (15,8%), tonturas, insónia.\nEdema periférico (2,1%) e retenção de líquidos.\nEventos cardiovasculares trombóticos (risco de classe; não substitui a aspirina na profilaxia cardiovascular).\nHemorragia/úlcera/perfuração GI (risco menor que AINE não seletivos, mas presente).\nHipertensão, agravamento da insuficiência cardíaca, toxicidade renal e hipercaliemia.\nReações cutâneas graves (SJS, TEN, DRESS, AGEP) e anafilaxia (raras).',
   E'Gastrointestinal: dyspepsia (8.8%), diarrhoea (5.6%), abdominal pain (4.1%), flatulence, nausea, vomiting.\nHeadache (15.8%), dizziness, insomnia.\nPeripheral oedema (2.1%) and fluid retention.\nCardiovascular thrombotic events (class risk; not a substitute for aspirin in cardiovascular prophylaxis).\nGI bleeding/ulceration/perforation (lower risk than non-selective NSAIDs, but present).\nHypertension, worsening heart failure, renal toxicity and hyperkalaemia.\nSevere skin reactions (SJS, TEN, DRESS, AGEP) and anaphylaxis (rare).',
   E'Contraindicado em doentes com hipersensibilidade, história de asma/urticária após aspirina ou AINE, no contexto de cirurgia CABG, e com alergia a sulfonamidas.\nRisco cardiovascular trombótico (enfarte, AVC) — usar a menor dose eficaz pelo menor tempo; não usar como substituto da aspirina (não inibe a agregação plaquetária).\nRisco GI (hemorragia, úlcera, perfuração) — considerar proteção gástrica nos doentes de risco.\nVigiar função renal e potássio, sobretudo em idosos, hipovolemia e com diuréticos/IECA/ARA.\nEvitar na gravidez (a partir das 20 semanas, risco de disfunção renal fetal/oligohidrâmnios).',
   E'Contraindicated in hypersensitivity, history of asthma/urticaria after aspirin or NSAIDs, in the setting of CABG surgery, and in sulfonamide allergy.\nCardiovascular thrombotic risk (MI, stroke) — use the lowest effective dose for the shortest time; not a substitute for aspirin (does not inhibit platelet aggregation).\nGI risk (bleeding, ulceration, perforation) — consider gastric protection in at-risk patients.\nMonitor renal function and potassium, especially in the elderly, volume depletion and with diuretics/ACE inhibitors/ARBs.\nAvoid in pregnancy (from 20 weeks, risk of fetal renal dysfunction/oligohydramnios).',
   'DailyMed/FDA (NIH/NLM) — rótulo Celecoxib Capsules: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2c86ece8-1cf5-4688-91b1-8aef5d60b7e4',
   'DailyMed/FDA (NIH/NLM) — Celecoxib Capsules label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2c86ece8-1cf5-4688-91b1-8aef5d60b7e4'),

  ('codeina',
   'A codeína é um analgésico opióide usado no tratamento da dor ligeira a moderada quando os analgésicos simples não são suficientes, geralmente em associação com paracetamol. É um pró-fármaco: o efeito depende da sua conversão em morfina, que varia com a genética de cada pessoa. Em crianças <12 anos está contraindicada pelo risco de depressão respiratória.',
   'Codeine is an opioid analgesic used for mild to moderate pain when simple analgesics are not enough, usually combined with paracetamol. It is a prodrug: its effect depends on its conversion to morphine, which varies with each person genetics. It is contraindicated in children under 12 due to the risk of respiratory depression.',
   'Opióide fraco (agonista mu com afinidade muito menor que a morfina), pró-fármaco da morfina via CYP2D6 — a eficácia e a toxicidade dependem do genótipo (metabolizadores ultrarrápidos podem ter níveis tóxicos de morfina). Indicado na dor ligeira a moderada quando o tratamento alternativo é inadequado. Semivida ~2,9 h. Contraindicado em crianças <12 anos e no pós-operatório de amigdalectomia/adenoidectomia em <18 anos.',
   'Weak opioid (mu agonist with much lower affinity than morphine), a prodrug of morphine via CYP2D6 — efficacy and toxicity depend on genotype (ultrarapid metabolisers can develop toxic morphine levels). Indicated for mild to moderate pain when alternative treatment is inadequate. Half-life ~2.9 h. Contraindicated in children <12 years and post-tonsillectomy/adenoidectomy in <18 years.',
   E'Tratamento da dor ligeira a moderada quando o tratamento com um opióide é apropriado e as alternativas são inadequadas (geralmente em associação com paracetamol).',
   E'Management of mild to moderate pain where treatment with an opioid is appropriate and for which alternative treatments are inadequate (usually combined with paracetamol).',
   E'Sonolência, tonturas, sedação, cefaleia, vertigens.\nNáuseas, vómitos, obstipação, boca seca.\nDepressão respiratória (risco grave — sobretudo em metabolizadores ultrarrápidos e crianças).\nPrurido, sudorese, reações alérgicas, euforia/disforia.\nHipotensão ortostática, palpitações, síncope.\nDependência, tolerância e síndrome de privação com uso prolongado.',
   E'Somnolence, dizziness, sedation, headache, vertigo.\nNausea, vomiting, constipation, dry mouth.\nRespiratory depression (serious risk — especially in ultrarapid metabolisers and children).\nPruritus, sweating, allergic reactions, euphoria/dysphoria.\nOrthostatic hypotension, palpitations, syncope.\nDependence, tolerance and withdrawal syndrome with prolonged use.',
   E'Contraindicado em crianças <12 anos, no pós-operatório de amigdalectomia/adenoidectomia em <18 anos, em depressão respiratória significativa, asma aguda/grave não monitorizada, obstrução gastrointestinal, com IMAO (ou <14 dias) e hipersensibilidade.\nMetabolizadores ultrarrápidos do CYP2D6 (1-10% dos caucasianos; >10% em alguns grupos) — risco de níveis tóxicos de morfina; NÃO usar.\nCautela com depressores do SNC (benzodiazepinas, álcool) — risco de sedação profunda e morte.\nNão exceder 4 g/dia de paracetamol nos produtos combinados.\nEvitar na amamentação (morte reportada em lactente de mãe metabolizadora ultrarrápida).\nRetirar gradualmente após uso prolongado.',
   E'Contraindicated in children <12 years, post-tonsillectomy/adenoidectomy in <18 years, significant respiratory depression, acute/severe asthma in an unmonitored setting, GI obstruction, with MAOIs (or within 14 days) and hypersensitivity.\nCYP2D6 ultrarapid metabolisers (1-10% of Whites; >10% in some groups) — risk of toxic morphine levels; do NOT use.\nCaution with CNS depressants (benzodiazepines, alcohol) — risk of profound sedation and death.\nDo not exceed 4 g/day of paracetamol in combination products.\nAvoid in breastfeeding (death reported in an infant of an ultrarapid metaboliser mother).\nTaper gradually after prolonged use.',
   'DailyMed/FDA (NIH/NLM) — rótulo Acetaminophen and Codeine Phosphate Tablets (SpecGx): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=eadc80fa-13c3-471a-a22f-6fe7e1ab290f',
   'DailyMed/FDA (NIH/NLM) — Acetaminophen and Codeine Phosphate Tablets label (SpecGx): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=eadc80fa-13c3-471a-a22f-6fe7e1ab290f'),

  ('desloratadina',
   'A desloratadina é um anti-histamínico não sedativo, usado no alívio dos sintomas da rinite alérgica (espirros, corrimento nasal, comichão nos olhos e nariz). Toma-se uma vez por dia e tem pouco efeito de sonolência. É o metabolito ativo da loratadina.',
   'Desloratadine is a non-sedating antihistamine, used to relieve the symptoms of allergic rhinitis (sneezing, runny nose, itchy eyes and nose). It is taken once a day and causes little drowsiness. It is the active metabolite of loratadine.',
   'Anti-histamínico tricíclico de ação prolongada, antagonista seletivo dos recetores H1 periféricos; não atravessa facilmente a barreira hematoencefálica (baixa sedação). É o metabolito ativo da loratadina, com semivida ~27 h (toma única diária). Indicado na rinite alérgica sazonal e perene (≥12 anos). Sem efeito clinicamente relevante no QTc.',
   'Long-acting tricyclic antihistamine, selective antagonist of peripheral H1 receptors; does not readily cross the blood-brain barrier (low sedation). It is the active metabolite of loratadine, with a half-life of ~27 h (once-daily dosing). Indicated in seasonal and perennial allergic rhinitis (≥12 years). No clinically relevant QTc effect.',
   E'Alívio dos sintomas nasais e não nasais da rinite alérgica sazonal (≥12 anos).\nAlívio dos sintomas da rinite alérgica perene (≥12 anos).',
   E'Relief of the nasal and non-nasal symptoms of seasonal allergic rhinitis (≥12 years).\nRelief of the symptoms of perennial allergic rhinitis (≥12 years).',
   E'Geralmente bem tolerado; incidência de efeitos adversos semelhante ao placebo.\nFaringite (4,1%), boca seca (3,0%), sonolência (2,1%), mialgia (2,1%), dismenorreia (2,1%), fadiga (2,1%).\nPós-comercialização: taquicardia, palpitações, dispneia, rash, prurido, reações de hipersensibilidade (urticária, edema, anafilaxia), elevação das enzimas hepáticas, hepatite.',
   E'Generally well tolerated; adverse event incidence similar to placebo.\nPharyngitis (4.1%), dry mouth (3.0%), somnolence (2.1%), myalgia (2.1%), dysmenorrhoea (2.1%), fatigue (2.1%).\nPostmarketing: tachycardia, palpitations, dyspnoea, rash, pruritus, hypersensitivity reactions (urticaria, oedema, anaphylaxis), elevated liver enzymes, hepatitis.',
   E'Contraindicado em doentes com hipersensibilidade à desloratadina, aos seus componentes ou à loratadina.\nMetabolizadores lentos (cerca de 6% da população, mais frequentes em negros 17%): exposição ~6x superior — sem diferenças de segurança nos estudos.\nInsuficiência renal ou hepática: ajustar dose (exposição aumentada).\nEm caso de reação de hipersensibilidade, suspender e procurar ajuda médica.',
   E'Contraindicated in hypersensitivity to desloratadine, its components or loratadine.\nPoor metabolisers (about 6% of the population, more frequent in Blacks 17%): ~6-fold higher exposure — no safety differences in studies.\nRenal or hepatic impairment: adjust dose (increased exposure).\nIf a hypersensitivity reaction occurs, discontinue and seek medical help.',
   'DailyMed/FDA (NIH/NLM) — rótulo Desloratadine Tablets (Lupin): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c',
   'DailyMed/FDA (NIH/NLM) — Desloratadine Tablets label (Lupin): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c'),

  ('domperidona',
   'A domperidona é um medicamento usado para aliviar náuseas e vómitos e a sensação de enfartamento e desconforto abdominal alto. Atua no estômago e intestino sem atravessar a barreira hematoencefálica, pelo que causa menos efeitos no sistema nervoso do que a metoclopramida. Por risco de arritmias cardíacas, deve ser usada na menor dose eficaz e pelo menor tempo possível.',
   'Domperidone is a medicine used to relieve nausea and vomiting and the feeling of fullness, upper abdominal discomfort and regurgitation. It acts on the stomach and gut without crossing the blood-brain barrier, so it causes fewer nervous system effects than metoclopramide. Because of the risk of cardiac arrhythmias, it should be used at the lowest effective dose for the shortest possible time.',
   'Procinético e antiemético, antagonista periférico dos recetores D2 da dopamina, sem passagem relevante da barreira hematoencefálica (baixa incidência de efeitos extrapiramidais). Aumenta a motilidade gástrica e o peristaltismo duodenal. Risco de prolongamento do QT e arritmias ventriculares — contraindicado em combinação com inibidores potentes do CYP3A4 e em doentes com QT prolongado; biodisponibilidade oral ~15% (efeito de primeira passagem) e semivida 7-9 h.',
   'Prokinetic and antiemetic, peripheral dopamine D2 receptor antagonist, without relevant blood-brain barrier crossing (low incidence of extrapyramidal effects). Increases gastric motility and duodenal peristalsis. Risk of QT prolongation and ventricular arrhythmias — contraindicated with potent CYP3A4 inhibitors and in patients with QT prolongation; oral bioavailability ~15% (first-pass effect) and half-life 7-9 h.',
   E'Adultos: alívio dos sintomas de náuseas e vómitos, sensação de enfartamento epigástrico, desconforto abdominal alto e regurgitação do conteúdo gástrico.\nCrianças: alívio dos sintomas de náuseas e vómitos.',
   E'Adults: relief of the symptoms of nausea and vomiting, epigastric fullness, upper abdominal discomfort and regurgitation of gastric contents.\nChildren: relief of the symptoms of nausea and vomiting.',
   E'Boca seca, cefaleia, diarreia (os mais comuns).\nAumento da prolactina: galactorreia, ginecomastia, alterações menstruais (reversíveis).\nProlongamento do intervalo QT e arritmias ventriculares (torsades de pointes) — risco aumentado com doses altas, doença cardíaca prévia e interações.\nEfeitos extrapiramidais (raros, sobretudo em crianças e com passagem BHE imatura).\nReações alérgicas (rash, urticária; anafilaxia rara).',
   E'Dry mouth, headache, diarrhoea (most common).\nIncreased prolactin: galactorrhoea, gynaecomastia, menstrual changes (reversible).\nQT interval prolongation and ventricular arrhythmias (torsades de pointes) — increased risk with high doses, pre-existing cardiac disease and interactions.\nExtrapyramidal effects (rare, especially in children and with immature BBB).\nAllergic reactions (rash, urticaria; anaphylaxis rare).',
   E'Usar a menor dose eficaz e a duração mais curta (geralmente até 1 semana; reavaliar às 4 semanas).\nContraindicado em doentes com QT prolongado, doença cardíaca significativa, com inibidores potentes do CYP3A4 (cetoconazol, itraconazol, claritromicina, eritromicina, ritonavir) e com fármacos que prolongam o QT.\nContraindicado em hemorragia, obstrução ou perfuração gastrointestinal e em prolactinoma.\nPrecaução na insuficiência renal grave (semivida prolongada — reduzir frequência) e hepática.\nNão recomendado na amamentação.\nEvitar em crianças sempre que possível (risco neurológico nos primeiros meses de vida).',
   E'Use the lowest effective dose for the shortest duration (generally up to 1 week; reassess at 4 weeks).\nContraindicated in QT prolongation, significant cardiac disease, with potent CYP3A4 inhibitors (ketoconazole, itraconazole, clarithromycin, erythromycin, ritonavir) and with QT-prolonging drugs.\nContraindicated in gastrointestinal haemorrhage, obstruction or perforation, and in prolactinoma.\nCaution in severe renal impairment (prolonged half-life — reduce frequency) and hepatic impairment.\nNot recommended in breastfeeding.\nAvoid in children whenever possible (neurological risk in the first months of life).',
   'SmPC europeia — Motilium (domperidona), Comissão Europeia 2002, secções 4.1, 4.3, 4.4, 4.8, 5.2: https://ec.europa.eu/health/documents/community-register/2002/200210175767/anx_5767_en.pdf',
   'European SmPC — Motilium (domperidone), European Commission 2002, sections 4.1, 4.3, 4.4, 4.8, 5.2: https://ec.europa.eu/health/documents/community-register/2002/200210175767/anx_5767_en.pdf'),

  ('doxiciclina',
   'A doxiciclina é um antibiótico da família das tetraciclinas, usado em muitas infeções: respiratórias, por clamídia, rickettsioses (como a febre das montanhas rochosas), cólera, peste, antraz, brucelose e na profilaxia da malária em viajantes. Também é usada na acne. Não deve ser tomada com leite, antiácidos ou ferro, e pode causar fotossensibilidade.',
   'Doxycycline is a tetracycline antibiotic, used in many infections: respiratory, chlamydial, rickettsial (such as Rocky Mountain spotted fever), cholera, plague, anthrax, brucellosis and malaria prophylaxis in travellers. It is also used in acne. It should not be taken with milk, antacids or iron, and can cause photosensitivity.',
   'Tetraciclina bacteriostática (ligação à subunidade ribossomal 30S, inibição da síntese proteica) com absorção oral quase completa, semivida longa (18-22 h) independente da função renal e extenso espetro (rickettsias, clamídias, micoplasmas, espiroquetas, Vibrio, Yersinia, Bacillus anthracis, plasmódios). Indicada em múltiplas infeções e na profilaxia da malária. Avisos: coloração dos dentes em crianças <8 anos, fotossensibilidade, hipertensão intracraniana.',
   'Bacteriostatic tetracycline (binds the 30S ribosomal subunit, inhibits protein synthesis) with almost complete oral absorption, a long half-life (18-22 h) independent of renal function and a broad spectrum (rickettsiae, chlamydiae, mycoplasmas, spirochaetes, Vibrio, Yersinia, Bacillus anthracis, plasmodia). Indicated in multiple infections and malaria prophylaxis. Warnings: tooth discoloration in children <8 years, photosensitivity, intracranial hypertension.',
   E'Infeções por rickettsias: febre das montanhas rochosas, tifo, febre Q, riquetsiose variceliforme.\nInfeções respiratórias por Mycoplasma pneumoniae; psitacose; tracoma e conjuntivite de inclusão; infeções urogenitais por Chlamydia trachomatis; uretrite não gonocócica.\nCólera, peste, tularemia, brucelose (com estreptomicina), antraz (incluindo pós-exposição inalatória).\nQuando a penicilina está contraindicada: gonorreia não complicada, sífilis, listeriose, actinomicose.\nAcne grave (adjuvante).\nProfilaxia da malária por P. falciparum em viajantes de curta duração (<4 meses).',
   E'Rickettsial infections: Rocky Mountain spotted fever, typhus, Q fever, rickettsialpox.\nRespiratory infections due to Mycoplasma pneumoniae; psittacosis; trachoma and inclusion conjunctivitis; urogenital Chlamydia trachomatis infections; non-gonococcal urethritis.\nCholera, plague, tularaemia, brucellosis (with streptomycin), anthrax (including inhalational post-exposure).\nWhen penicillin is contraindicated: uncomplicated gonorrhoea, syphilis, listeriosis, actinomycosis.\nSevere acne (adjunctive).\nMalaria prophylaxis due to P. falciparum in short-term travellers (<4 months).',
   E'Gastrointestinais: anorexia, náuseas, vómitos, diarreia (menos frequente que outras tetraciclinas — absorção quase completa), esofagite/úlcera esofágica (tomar com líquidos, não deitar de imediato).\nFotossensibilidade (queimadura solar exagerada).\nColoração dos dentes (amarelo-cinza-acastanhada) e hipoplasia do esmalte em crianças <8 anos e na gravidez.\nHipertensão intracraniana (pseudotumor cerebral): cefaleia, visão turva, diplopia.\nReações cutâneas graves (SJS, TEN, DRESS, eritema multiforme, erupção fixa).\nElevação do BUN (ação antianabólica).',
   E'Gastrointestinal: anorexia, nausea, vomiting, diarrhoea (less frequent than other tetracyclines — almost complete absorption), oesophagitis/oesophageal ulceration (take with fluids, do not lie down immediately).\nPhotosensitivity (exaggerated sunburn).\nTooth discoloration (yellow-grey-brown) and enamel hypoplasia in children <8 years and in pregnancy.\nIntracranial hypertension (pseudotumour cerebri): headache, blurred vision, diplopia.\nSevere skin reactions (SJS, TEN, DRESS, erythema multiforme, fixed drug eruption).\nRaised BUN (antianabolic action).',
   E'Evitar em crianças <8 anos, na gravidez (2.º/3.º trimestres) e na amamentação — coloração dentária e hipoplasia do esmalte; usar apenas se benefício superar o risco (antraz, febre das montanhas rochosas).\nTomar com água, em pé, e não deitar 30-60 min após a toma (risco de esofagite); não tomar com leite, antiácidos, ferro ou zinco (quelatos).\nEvitar exposição solar/UV (fotossensibilidade); suspender ao primeiro sinal de eritema.\nVigiar cefaleia/visão (hipertensão intracraniana); evitar com isotretinoína.\nNÃO usar após a data de validade (nefrotoxicidade das tetraciclinas degradadas).\nContraindicado em hipersensibilidade às tetraciclinas.',
   E'Avoid in children <8 years, in pregnancy (2nd/3rd trimesters) and breastfeeding — tooth discoloration and enamel hypoplasia; use only if benefit outweighs risk (anthrax, Rocky Mountain spotted fever).\nTake with water, standing, and do not lie down for 30-60 min after (oesophagitis risk); do not take with milk, antacids, iron or zinc (chelation).\nAvoid sun/UV exposure (photosensitivity); discontinue at the first sign of erythema.\nMonitor headache/vision (intracranial hypertension); avoid with isotretinoin.\nDo NOT use after the expiry date (nephrotoxicity of degraded tetracyclines).\nContraindicated in tetracycline hypersensitivity.',
   'DailyMed/FDA (NIH/NLM) — rótulo Doxycycline Hyclate Capsules: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=bcc95094-80ed-4023-b2a6-955a4810bfbe',
   'DailyMed/FDA (NIH/NLM) — Doxycycline Hyclate Capsules label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=bcc95094-80ed-4023-b2a6-955a4810bfbe'),
  ('febuxostat',
   'O febuxostat é um medicamento usado no tratamento crónico da gota, para baixar o ácido úrico no sangue. É uma alternativa ao alopurinol quando este não é eficaz ou não é tolerado. Não é recomendado para a hiperuricemia sem sintomas. Como todos os redutores do ácido úrico, no início pode precipitar crises de gota.',
   'Febuxostat is a medicine used in the chronic treatment of gout, to lower uric acid in the blood. It is an alternative to allopurinol when this is ineffective or not tolerated. It is not recommended for asymptomatic hyperuricaemia. Like all uric-acid-lowering drugs, it can precipitate gout flares at the start.',
   'Inibidor seletivo da xantina oxidase (não purínico), reduz a produção de ácido úrico. Indicado no tratamento crónico da hiperuricemia na gota com resposta inadequada, intolerância ou contraindicação ao alopurinol. Redução de 40-55% do ácido úrico sérico com 40-80 mg/dia. Contraindicado com azatioprina e mercaptopurina (aumento de 6-mercaptopurina). Semivida 5-8 h.',
   'Selective non-purine xanthine oxidase inhibitor, reduces uric acid production. Indicated for the chronic management of hyperuricaemia in gout with inadequate response, intolerance or contraindication to allopurinol. Reduces serum uric acid by 40-55% at 40-80 mg/day. Contraindicated with azathioprine and mercaptopurine (increased 6-mercaptopurine). Half-life 5-8 h.',
   E'Tratamento crónico da hiperuricemia em adultos com gota que tiveram resposta inadequada à dose máxima titulada de alopurinol, que são intolerantes ao alopurinol, ou para quem o alopurinol não é aconselhável.\nNÃO é recomendado no tratamento da hiperuricemia assintomática.',
   E'Chronic management of hyperuricaemia in adult patients with gout who have an inadequate response to a maximally titrated dose of allopurinol, who are intolerant to allopurinol, or for whom allopurinol is not advisable.\nNOT recommended for the treatment of asymptomatic hyperuricaemia.',
   E'Anomalias da função hepática (6,6% a 40 mg; 4,6% a 80 mg) — principal causa de suspensão.\nNáuseas, artralgias, rash (1-2%).\nNo estudo CARES: maior incidência de morte cardiovascular com febuxostat vs alopurinol (embora a causalidade não esteja estabelecida — ver precauções).\nPós-comercialização: falência hepática (alguns fatais), reações cutâneas graves (SJS, TEN, DRESS, eritema multiforme), anafilaxia, rabdomiólise, agranulocitose, nefrite tubulointersticial.',
   E'Liver function abnormalities (6.6% at 40 mg; 4.6% at 80 mg) — main cause of discontinuation.\nNausea, arthralgia, rash (1-2%).\nIn the CARES study: higher incidence of cardiovascular death with febuxostat vs allopurinol (causality not established — see precautions).\nPostmarketing: hepatic failure (some fatal), severe skin reactions (SJS, TEN, DRESS, erythema multiforme), anaphylaxis, rhabdomyolysis, agranulocytosis, tubulointerstitial nephritis.',
   E'Contraindicado em doentes tratados com azatioprina ou mercaptopurina (risco de toxicidade grave da 6-mercaptopurina).\nConsiderar o risco cardiovascular no estudo CARES (morte cardiovascular) ao decidir entre febuxostat e alopurinol.\nVigiar função hepática; suspender se elevação persistente das transaminases.\nNo início, associar profilaxia das crises de gota (AINE, colchicina) — as crises podem ocorrer nos primeiros meses.\nSuspender se surgirem reações cutâneas graves.\nCautela com a teofilina (aumento de 1-metilxantina por inibição da XO).',
   E'Contraindicated in patients treated with azathioprine or mercaptopurine (risk of severe 6-mercaptopurine toxicity).\nConsider the CARES cardiovascular mortality signal when deciding between febuxostat and allopurinol.\nMonitor liver function; discontinue if persistent transaminase elevation.\nAt initiation, provide gout flare prophylaxis (NSAID, colchicine) — flares may occur in the first months.\nDiscontinue if severe skin reactions occur.\nCaution with theophylline (increased 1-methylxanthine via XO inhibition).',
   'DailyMed/FDA (NIH/NLM) — rótulo Uloric (febuxostat) Takeda: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=54de10ef-fe5f-4930-b91d-6bbb04c664bd',
   'DailyMed/FDA (NIH/NLM) — Uloric (febuxostat) Takeda label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=54de10ef-fe5f-4930-b91d-6bbb04c664bd'),

  ('fentanilo',
   'O fentanilo (sistema transdérmico — adesivo) é um analgésico opióide forte, usado no tratamento da dor grave e persistente em doentes já tolerantes a opióides, quando outras opções não controlam a dor. O adesivo liberta o medicamento de forma contínua durante 72 horas. Tem elevado potencial de dependência, abuso e overdose, e só deve ser usado sob vigilância médica apertada.',
   'Fentanyl (transdermal system — patch) is a strong opioid analgesic, used to treat severe and persistent pain in opioid-tolerant patients when other options do not control the pain. The patch releases the medicine continuously over 72 hours. It has a high potential for dependence, abuse and overdose, and must only be used under close medical supervision.',
   'Agonista opióide mu de elevada potência (cerca de 100x a morfina), em sistema transdérmico de libertação contínua (72 h) para dor grave e persistente em doentes tolerantes a opióides. NÃO indicado como analgésico à procura (prn), dor aguda ou pós-operatória, nem em doentes não tolerantes. Depressão respiratória potencialmente fatal; metabolizado por CYP3A4 (interações com inibidores/indutores). Semivida após remoção ~20-27 h.',
   'High-potency mu opioid agonist (about 100x morphine), as a transdermal continuous-release system (72 h) for severe and persistent pain in opioid-tolerant patients. NOT indicated as an as-needed (prn) analgesic, acute or postoperative pain, nor in non-tolerant patients. Potentially fatal respiratory depression; metabolised by CYP3A4 (interactions with inhibitors/inducers). Half-life after removal ~20-27 h.',
   E'Tratamento da dor grave e persistente em doentes tolerantes a opióides que requerem um analgésico opióide e que não pode ser adequadamente tratada com alternativas, incluindo opióides de libertação imediata.\nNÃO é indicado como analgésico à procura (prn).',
   E'Management of severe and persistent pain in opioid-tolerant patients requiring an opioid analgesic that cannot be adequately treated with alternative options, including immediate-release opioids.\nNOT indicated as an as-needed (prn) analgesic.',
   E'Náuseas (41%), vómitos (26%), sonolência (19%), tonturas (10%), insónia (10%), obstipação (9%), hiperidrose (6%), fadiga (6%), sensação de frio (6%), anorexia (5%), palpitações (4%).\nDepressão respiratória potencialmente fatal (risco máximo no início e com aumentos de dose).\nDependência, abuso, desvio e overdose.\nSíndrome de privação neonatal e de privação por opióides.\nHipoventilação, apneia, hipotensão grave, convulsões, íleo paralítico, síndrome serotoninérgico.',
   E'Nausea (41%), vomiting (26%), somnolence (19%), dizziness (10%), insomnia (10%), constipation (9%), hyperhidrosis (6%), fatigue (6%), feeling cold (6%), anorexia (5%), palpitations (4%).\nPotentially fatal respiratory depression (maximum risk at initiation and dose increases).\nDependence, abuse, diversion and overdose.\nNeonatal opioid withdrawal and opioid withdrawal syndromes.\nHypoventilation, apnoea, severe hypotension, seizures, paralytic ileus, serotonin syndrome.',
   E'Reservar para doentes tolerantes a opióides (ex.: ≥60 mg de morfina/dia durante ≥1 semana) — contraindicado em não tolerantes, dor aguda/intermitente/pós-operatória, depressão respiratória significativa, asma aguda/grave não monitorizada e obstrução gastrointestinal.\nNÃO aplicar calor sobre o adesivo (aumento de 120% da exposição) nem expor a fontes de calor.\nInterações com depressores do SNC (benzodiazepinas, álcool) — risco de sedação profunda e morte; e com inibidores do CYP3A4 (aumento da exposição).\nManter fora do alcance de crianças (exposição acidental fatal); eliminar os adesivos usados de forma segura.\nVigiar depressão respiratória, sobretudo no início e com aumento de dose.\nRetirar gradualmente (não suspender bruscamente).',
   E'Reserve for opioid-tolerant patients (e.g., ≥60 mg of morphine/day for ≥1 week) — contraindicated in non-tolerant patients, acute/intermittent/postoperative pain, significant respiratory depression, acute/severe asthma in an unmonitored setting and GI obstruction.\nDo NOT apply heat over the patch (120% increase in exposure) nor expose to heat sources.\nInteractions with CNS depressants (benzodiazepines, alcohol) — risk of profound sedation and death; and with CYP3A4 inhibitors (increased exposure).\nKeep out of the reach of children (accidental exposure is fatal); dispose of used patches safely.\nMonitor for respiratory depression, especially at initiation and dose increases.\nTaper gradually (do not stop abruptly).',
   'DailyMed/FDA (NIH/NLM) — rótulo Fentanyl Transdermal System (SpecGx): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e15a7e9b-8025-49dd-9a6d-bafcccf1959f',
   'DailyMed/FDA (NIH/NLM) — Fentanyl Transdermal System label (SpecGx): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e15a7e9b-8025-49dd-9a6d-bafcccf1959f'),

  ('ferro',
   'O ferro (sulfato ferroso) é um suplemento usado no tratamento e prevenção da anemia por défice de ferro. A absorção é limitada (cerca de 10-20% da dose) e melhora quando tomado com o estômago vazio e com vitamina C. A sobredosagem acidental de ferro é perigosa em crianças — manter fora do alcance.',
   'Iron (ferrous sulfate) is a supplement used to treat and prevent iron deficiency anaemia. Absorption is limited (about 10-20% of the dose) and improves when taken on an empty stomach and with vitamin C. Accidental iron overdose is dangerous in children — keep out of reach.',
   'Suplemento mineral (sais ferrosos) essencial para a eritropoiese e o transporte de oxigénio. A absorção duodenal/proximal é regulada pela hepcidina e limitada (~10-20% em indivíduos com défice; menos com níveis normais). Interfere com a absorção de antibióticos (tetraciclinas, quinolonas) e é interferido por antiácidos, leite e chá. Indicado na anemia ferropénica e na suplementação da gravidez.',
   'Mineral supplement (ferrous salts) essential for erythropoiesis and oxygen transport. Duodenal/proximal absorption is regulated by hepcidin and limited (~10-20% in deficient individuals; less with normal levels). Interferes with antibiotic absorption (tetracyclines, quinolones) and is interfered with by antacids, milk and tea. Indicated in iron deficiency anaemia and pregnancy supplementation.',
   E'Tratamento da anemia por défice de ferro.\nPrevenção do défice de ferro na gravidez e em situações de aumento das necessidades.',
   E'Treatment of iron deficiency anaemia.\nPrevention of iron deficiency in pregnancy and states of increased requirements.',
   E'Obstipação (o mais frequente), diarreia, fezes escuras (normais — não é hemorragia).\nDor/desconforto abdominal, náuseas, vómitos.\nSobredosagem (especialmente em crianças): vómitos, diarreia hemorrágica, choque — emergência médica imediata.',
   E'Constipation (most frequent), diarrhoea, dark stools (normal — not bleeding).\nAbdominal pain/discomfort, nausea, vomiting.\nOverdose (especially in children): vomiting, haemorrhagic diarrhoea, shock — immediate medical emergency.',
   E'Não tomar na mesma altura que antibióticos (tetraciclinas, quinolonas), antiácidos, leite, chá ou café — separar pelo menos 2 horas.\nManter fora do alcance das crianças: a sobredosagem de ferro é uma das principais causas de envenenamento fatal em crianças <6 anos.\nEm caso de sobredosagem, contactar imediatamente o centro antivenenos.\nConsultar o médico na gravidez/amamentação ou com outros medicamentos.\nSuspender e consultar se ocorrerem reações adversas.',
   E'Do not take at the same time as antibiotics (tetracyclines, quinolones), antacids, milk, tea or coffee — separate by at least 2 hours.\nKeep out of the reach of children: iron overdose is a leading cause of fatal poisoning in children under 6.\nIn case of overdose, contact a poison control centre immediately.\nConsult a doctor in pregnancy/breastfeeding or with other medicines.\nDiscontinue and consult if adverse reactions occur.',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Ferrous Sulfate (Drug Facts) + Santiago P. Pharmaceutics 2012 (PMC3857035): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e88a847-397b-4ddb-83d7-42c9b963a0b7',
   'DailyMed/FDA (NIH/NLM) — OTC Ferrous Sulfate label (Drug Facts) + Santiago P. Pharmaceutics 2012 (PMC3857035): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e88a847-397b-4ddb-83d7-42c9b963a0b7'),

  ('fexofenadina',
   'A fexofenadina é um anti-histamínico não sedativo, usado no alívio dos sintomas da rinite alérgica (espirros, corrimento nasal, comichão nos olhos e nariz) e da urticária. Não atravessa o cérebro, pelo que não causa sonolência significativa. Toma-se uma vez por dia.',
   'Fexofenadine is a non-sedating antihistamine, used to relieve the symptoms of allergic rhinitis (sneezing, runny nose, itchy eyes and nose) and urticaria. It does not cross into the brain, so it does not cause significant drowsiness. It is taken once a day.',
   'Anti-histamínico de segunda geração, antagonista seletivo periférico dos recetores H1, sem atividade anticolinérgica ou sedativa relevante (não atravessa a barreira hematoencefálica). Não sofre metabolização significativa (substrato de OATP e glicoproteína-P). Indicado na rinite alérgica e na urticária idiopática crónica. Semivida ~14,4 h.',
   'Second-generation antihistamine, selective peripheral H1 antagonist, without relevant anticholinergic or sedative activity (does not cross the blood-brain barrier). Undergoes no significant metabolism (substrate of OATP and P-glycoprotein). Indicated in allergic rhinitis and chronic idiopathic urticaria. Half-life ~14.4 h.',
   E'Alívio temporário dos sintomas da rinite alérgica (corrimento nasal, espirros, comichão nos olhos, nariz ou garganta).\nAlívio da comichão e urticária (em formulações de venda livre).',
   E'Temporary relief of hay fever/allergic rhinitis symptoms (runny nose, sneezing, itchy, watery eyes, itching of the nose or throat).\nRelief of itching and hives (in OTC formulations).',
   E'Cefaleia, sonolência (ligeira e semelhante ao placebo), tonturas.\nNáuseas, dispepsia, fadiga.\nReações de hipersensibilidade (rash, urticária, prurido; anafilaxia e angioedema raros).',
   E'Headache, drowsiness (mild and similar to placebo), dizziness.\nNausea, dyspepsia, fatigue.\nHypersensitivity reactions (rash, urticaria, pruritus; anaphylaxis and angioedema rare).',
   E'Não usar em caso de alergia à fexofenadina ou aos seus componentes.\nNÃO tomar em simultâneo com antiácidos de alumínio/magnésio (reduzem a absorção) — separar pelo menos 2 horas.\nEvitar sumo de fruta (laranja, maçã, toranja) na altura da toma (reduzem a absorção).\nConsultar o médico na gravidez/amamentação.\nNão conduzir se ocorrer sonolência.',
   E'Do not use if allergic to fexofenadine or its components.\nDo NOT take with aluminium/magnesium antacids (reduce absorption) — separate by at least 2 hours.\nAvoid fruit juice (orange, apple, grapefruit) at the time of dosing (reduces absorption).\nConsult a doctor in pregnancy/breastfeeding.\nDo not drive if drowsiness occurs.',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Fexofenadine (Drug Facts) + Cvetkovic M et al. Drug Metab Dispos 1999 (PMID 10421612): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb',
   'DailyMed/FDA (NIH/NLM) — OTC Fexofenadine label (Drug Facts) + Cvetkovic M et al. Drug Metab Dispos 1999 (PMID 10421612): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb'),

  ('flecainida',
   'A flecainida é um medicamento antiarrítmico usado na prevenção de taquicardias supraventriculares paroxísticas, fibrilhação/fluíter auricular paroxístico e certas arritmias ventriculares graves. É eficaz mas pode provocar novas arritmias (efeito proarrítmico), pelo que o seu uso é reservado para doentes em que o benefício supera o risco e, em muitos casos, iniciado em ambiente hospitalar.',
   'Flecainide is an antiarrhythmic medicine used to prevent paroxysmal supraventricular tachycardias, paroxysmal atrial fibrillation/flutter and certain serious ventricular arrhythmias. It is effective but can provoke new arrhythmias (proarrhythmic effect), so its use is reserved for patients in whom the benefit outweighs the risk and, in many cases, initiated in hospital.',
   'Antiarrítmico da classe IC (estabilizador de membrana), com potente bloqueio da condução (maior efeito no sistema His-Purkinje). Indicado na prevenção de taquicardia supraventricular paroxística, fibrilhação/fluíter auricular paroxístico com sintomas incapacitantes (sem doença estrutural) e arritmias ventriculares documentadas potencialmente fatais. Efeito proarrítmico e inotrópico negativo; estudo CAST: excesso de mortalidade pós-enfarte. Semivida ~20 h; metabolizado por CYP2D6.',
   'Class IC antiarrhythmic (membrane stabiliser), with potent conduction blockade (greatest effect on the His-Purkinje system). Indicated for the prevention of paroxysmal supraventricular tachycardia, disabling paroxysmal atrial fibrillation/flutter (no structural heart disease) and documented life-threatening ventricular arrhythmias. Proarrhythmic effect and negative inotropy; CAST study: excess mortality post-MI. Half-life ~20 h; metabolised by CYP2D6.',
   E'Prevenção de taquicardias supraventriculares paroxísticas (incluindo taquicardia por reentrada nodal e auriculoventricular) associadas a sintomas incapacitantes, em doentes sem doença cardíaca estrutural.\nPrevenção de fibrilhação/fluíter auricular paroxístico com sintomas incapacitantes.\nPrevenção de arritmias ventriculares documentadas (taquicardia ventricular sustentada) potencialmente fatais.',
   E'Prevention of paroxysmal supraventricular tachycardias (including AV nodal and AV reentrant tachycardia) associated with disabling symptoms, in patients without structural heart disease.\nPrevention of paroxysmal atrial fibrillation/flutter associated with disabling symptoms.\nPrevention of documented ventricular arrhythmias (sustained ventricular tachycardia) that are life-threatening.',
   E'Tonturas (18,9%), perturbações visuais (15,9%), dispneia (10,3%), cefaleia (9,6%), náuseas (8,9%), fadiga (7,7%), palpitações (6,1%), dor torácica (5,4%), tremor, obstipação.\nProarrítmias: novas/agravamento de arritmias (1% na TSVP; 7% na FAP; 7-13% na TV sustentada) — incluindo TV/FV irrecuperável e paragem cardíaca.\nAgravamento ou novo aparecimento de insuficiência cardíaca (6,3%; 9,1% na TV sustentada).\nBloqueios AV (2.º grau 0,5%; 3.º grau 0,4%), bradicardia sinusal, pausas.\nEstudo CAST: maior mortalidade pós-enfarte vs placebo (5,1% vs 2,3%).',
   E'Dizziness (18.9%), visual disturbances (15.9%), dyspnoea (10.3%), headache (9.6%), nausea (8.9%), fatigue (7.7%), palpitations (6.1%), chest pain (5.4%), tremor, constipation.\nProarrhythmias: new/worsened arrhythmias (1% in PSVT; 7% in PAF; 7-13% in sustained VT) — including unresuscitatable VT/VF and cardiac arrest.\nNew or worsened heart failure (6.3%; 9.1% in sustained VT).\nAV blocks (2nd degree 0.5%; 3rd degree 0.4%), sinus bradycardia, pauses.\nCAST study: higher post-MI mortality vs placebo (5.1% vs 2.3%).',
   E'NÃO usar em doentes com enfarte do miocárdio recente, fibrilhação auricular crónica, nem em arritmias ventriculares menos graves (mesmo sintomáticas) — risco proarrítmico.\nContraindicado em bloqueio AV de 2.º/3.º grau ou bloqueio bifascicular sem pacemaker, choque cardiogénico e hipersensibilidade.\nNa TV sustentada, iniciar em ambiente hospitalar; monitorizar ECG e níveis plasmáticos (alvo <1 mcg/mL).\nVigiar função renal e hepática (semivida prolongada na insuficiência renal).\nInibidor do CYP2D6 (paroxetina, fluoxetina, quinidina): aumentam os níveis — reduzir dose.\nNÃO usar com ritonavir, lopinavir, cobicistate (níveis muito elevados).',
   E'Do NOT use in patients with recent myocardial infarction, chronic atrial fibrillation, or less severe ventricular arrhythmias (even if symptomatic) — proarrhythmic risk.\nContraindicated in 2nd/3rd degree AV block or bifascicular block without a pacemaker, cardiogenic shock and hypersensitivity.\nIn sustained VT, initiate in hospital; monitor ECG and plasma levels (target <1 mcg/mL).\nMonitor renal and hepatic function (prolonged half-life in renal impairment).\nCYP2D6 inhibitors (paroxetine, fluoxetine, quinidine): raise levels — reduce dose.\nDo NOT use with ritonavir, lopinavir, cobicistat (very high levels).',
   'DailyMed/FDA (NIH/NLM) — rótulo Flecainide Acetate Tablets (Epic Pharma): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=74c1eb2a-a37f-4f33-86bf-51e0d1d0c2bc',
   'DailyMed/FDA (NIH/NLM) — Flecainide Acetate Tablets label (Epic Pharma): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=74c1eb2a-a37f-4f33-86bf-51e0d1d0c2bc'),
  ('gentamicina',
   'A gentamicina é um antibiótico aminoglicosídeo administrado por injeção, usado no tratamento de infeções graves por bactérias Gram-negativas (Pseudomonas, E. coli, Klebsiella, Proteus, Serratia), incluindo sépsis, meningite, infeções urinárias e respiratórias. Como os outros aminoglicosídeos, pode lesar os rins e o ouvido interno; requer monitorização dos níveis e da função renal.',
   'Gentamicin is an aminoglycoside antibiotic given by injection, used to treat serious infections caused by Gram-negative bacteria (Pseudomonas, E. coli, Klebsiella, Proteus, Serratia), including sepsis, meningitis, urinary and respiratory infections. Like other aminoglycosides, it can damage the kidneys and the inner ear; monitoring of levels and renal function is required.',
   'Aminoglicosídeo bactericida (ligação ao ribossoma 30S, inibição da síntese proteica) com atividade sobretudo contra Gram-negativos aeróbios e sinergia com beta-lactâmicos (endocardite por estreptococos do grupo D, Pseudomonas). Indicado em infeções graves: sépsis neonatal, septicemia, meningite, infeções urinárias, respiratórias, gastrointestinais (peritonite), pele, osso e tecidos moles. Ototoxicidade e nefrotoxicidade dose-dependentes; monitorização terapêutica recomendada.',
   'Bactericidal aminoglycoside (binds the 30S ribosome, inhibits protein synthesis) active mainly against aerobic Gram-negatives, with synergy with beta-lactams (group D streptococcal endocarditis, Pseudomonas). Indicated in serious infections: neonatal sepsis, septicaemia, meningitis, urinary, respiratory, gastrointestinal (peritonitis), skin, bone and soft tissue. Dose-dependent ototoxicity and nephrotoxicity; therapeutic drug monitoring recommended.',
   E'Tratamento de infeções graves por estirpes suscetíveis de: Pseudomonas aeruginosa, Proteus (indol-positivo e negativo), E. coli, Klebsiella-Enterobacter-Serratia, Citrobacter e Staphylococcus (coagulase-positivo e negativo).\nSépsis neonatal bacteriana, septicemia, meningite, infeções do trato urinário, respiratório e gastrointestinal (incluindo peritonite), pele, osso e tecidos moles (incluindo queimaduras).\nEm associação com penicilina/cefalosporina quando o agente é desconhecido; com carbenicilina na infeção por Pseudomonas; com penicilina na endocardite por estreptococos do grupo D.',
   E'Treatment of serious infections due to susceptible strains of: Pseudomonas aeruginosa, Proteus (indole-positive and negative), E. coli, Klebsiella-Enterobacter-Serratia, Citrobacter and Staphylococcus (coagulase-positive and negative).\nNeonatal bacterial sepsis, septicaemia, meningitis, urinary, respiratory and gastrointestinal tract infections (including peritonitis), skin, bone and soft tissue (including burns).\nIn combination with a penicillin/cephalosporin when the causative organism is unknown; with carbenicillin in Pseudomonas infection; with penicillin in group D streptococcal endocarditis.',
   E'Nefrotoxicidade: cilindros, células ou proteínas na urina, elevação do BUN/creatinina, oligúria — mais frequente com função renal prévia comprometida, doses altas ou tratamento prolongado.\nOtotoxicidade vestibular e auditiva (tonturas, vertigens, zumbidos, perda auditiva de alta frequência — pode ser irreversível).\nBloqueio neuromuscular (depressão respiratória, fraqueza, síndrome miasténico).\nOutros: rash, prurido, urticária, febre, náuseas, vómitos, hipocaliemia/hipomagnesemia, anemia, leucopenia, trombocitopenia.',
   E'Nephrotoxicity: casts, cells or protein in urine, raised BUN/creatinine, oliguria — more frequent with pre-existing renal impairment, high doses or prolonged treatment.\nVestibular and auditory ototoxicity (dizziness, vertigo, tinnitus, high-frequency hearing loss — may be irreversible).\nNeuromuscular blockade (respiratory depression, weakness, myasthenic-like syndrome).\nOthers: rash, pruritus, urticaria, fever, nausea, vomiting, hypokalaemia/hypomagnesaemia, anaemia, leukopenia, thrombocytopenia.',
   E'Vigiar função renal (creatinina) e níveis séricos; ajustar dose na insuficiência renal (semivida correlaciona-se com a depuração da creatinina).\nAvaliar audição e equilíbrio em tratamentos prolongados/doses altas (ototoxicidade pode ser irreversível).\nHistória de hipersensibilidade à gentamicina ou reações graves a aminoglicosídeos contraindica o uso (reactividade cruzada).\nEvitar associação com outros ototóxicos/nefrotóxicos (diuréticos de ansa, vancomicina, outros aminoglicosídeos).\nCautela com relaxantes musculares (bloqueio neuromuscular).\nNa gravidez, avaliar o risco fetal (atravessa a placenta).',
   E'Monitor renal function (creatinine) and serum levels; adjust dose in renal impairment (half-life correlates with creatinine clearance).\nAssess hearing and balance in prolonged treatment/high doses (ototoxicity may be irreversible).\nHistory of hypersensitivity to gentamicin or serious reactions to aminoglycosides contraindicates use (cross-reactivity).\nAvoid combination with other ototoxic/nephrotoxic drugs (loop diuretics, vancomycin, other aminoglycosides).\nCaution with muscle relaxants (neuromuscular blockade).\nIn pregnancy, weigh fetal risk (crosses the placenta).',
   'DailyMed/FDA (NIH/NLM) — rótulo Gentamicin Sulfate Injection (Hospira): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=977180b3-a222-4282-d485-4a3217674305',
   'DailyMed/FDA (NIH/NLM) — Gentamicin Sulfate Injection label (Hospira): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=977180b3-a222-4282-d485-4a3217674305'),

  ('leflunomida',
   'A leflunomida é um medicamento modificador da doença usado no tratamento da artrite reumatoide ativa em adultos. Alivia os sintomas e retarda a progressão da doença. Tem efeitos sobre o fígado, a medula óssea e pode prejudicar o feto, pelo que exige vigilância regular e contraceção eficaz em mulheres em idade fértil.',
   'Leflunomide is a disease-modifying medicine used to treat active rheumatoid arthritis in adults. It relieves symptoms and slows disease progression. It affects the liver and bone marrow and can harm the fetus, so regular monitoring and effective contraception in women of childbearing age are required.',
   'Imunomodulador isoxazol (inibição da di-hidroorotato desidrogenase — síntese de pirimidinas de novo), com efeito antiproliferativo e anti-inflamatório. O metabolito ativo teriflunomida é responsável pela atividade (semivida 18-19 dias; eliminação acelerada com colestiramina). Indicado na artrite reumatoide ativa do adulto. Avisos: hepatotoxicidade, imunossupressão/infeções, teratogenicidade (eliminação acelerada obrigatória antes da gravidez).',
   'Isoxazole immunomodulator (inhibition of dihydroorotate dehydrogenase — de novo pyrimidine synthesis), with antiproliferative and anti-inflammatory effects. The active metabolite teriflunomide is responsible for the activity (half-life 18-19 days; accelerated elimination with cholestyramine). Indicated in active rheumatoid arthritis in adults. Warnings: hepatotoxicity, immunosuppression/infections, teratogenicity (mandatory accelerated elimination before pregnancy).',
   E'Tratamento da artrite reumatoide ativa em adultos.',
   E'Treatment of active rheumatoid arthritis in adults.',
   E'Diarreia (17%), cefaleia (7%), náuseas (9%), rash (10%), alopecia (10%), elevação das transaminases (5%), hipertensão (10%), astenia, dor abdominal, dispepsia, boca seca.\nElevação das enzimas hepáticas (>3x LSN em 2,6-4,4% — geralmente reversível).\nHepatotoxicidade grave (falência hepática — rara), sobretudo com outros hepatotóxicos.\nImunossupressão: infeções oportunistas, sepse (raras).\nSupressão medular: pancitopenia, agranulocitose, leucopenia.\nNeuropatia periférica, doença pulmonar intersticial (rara, pode ser fatal), SJS/TEN/DRESS, úlceras cutâneas.',
   E'Diarrhoea (17%), headache (7%), nausea (9%), rash (10%), alopecia (10%), transaminase elevation (5%), hypertension (10%), asthenia, abdominal pain, dyspepsia, dry mouth.\nElevated liver enzymes (>3x ULN in 2.6-4.4% — usually reversible).\nSevere hepatotoxicity (hepatic failure — rare), especially with other hepatotoxic drugs.\nImmunosuppression: opportunistic infections, sepsis (rare).\nBone marrow suppression: pancytopenia, agranulocytosis, leukopenia.\nPeripheral neuropathy, interstitial lung disease (rare, may be fatal), SJS/TEN/DRESS, skin ulcers.',
   E'Contraindicado na gravidez (teratogénico), em insuficiência hepática grave e em hipersensibilidade; não usar com teriflunomida.\nMulheres em idade fértil: contraceção eficaz durante e após o tratamento; antes de engravidar, procedimento de eliminação acelerada (colestiramina/carvão ativado) e confirmação de níveis <0,02 mg/L.\nVigiar transaminases (mensal no início), hemograma e pressão arterial.\nEvitar associação com metotrexato sem monitorização (risco hepático); rifampicina aumenta o pico de teriflunomida.\nVigiar sinais de infeção, neuropatia periférica e doença pulmonar intersticial.\nNÃO administrar vacinas vivas durante o tratamento.',
   E'Contraindicated in pregnancy (teratogenic), severe hepatic impairment and hypersensitivity; do not use with teriflunomide.\nWomen of childbearing age: effective contraception during and after treatment; before pregnancy, accelerated elimination procedure (cholestyramine/activated charcoal) and confirmation of levels <0.02 mg/L.\nMonitor transaminases (monthly at start), blood count and blood pressure.\nAvoid combination with methotrexate without monitoring (liver risk); rifampin raises teriflunomide peak.\nMonitor for signs of infection, peripheral neuropathy and interstitial lung disease.\nDo NOT administer live vaccines during treatment.',
   'DailyMed/FDA (NIH/NLM) — rótulo Leflunomide Tablets: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2',
   'DailyMed/FDA (NIH/NLM) — Leflunomide Tablets label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2'),

  ('loratadina',
   'A loratadina é um anti-histamínico não sedativo, usado no alívio dos sintomas da rinite alérgica (espirros, corrimento nasal, comichão nos olhos e nariz). Toma-se uma vez por dia e causa pouca sonolência. Em doentes com doença do fígado ou dos rins, pode ser necessário ajustar a dose.',
   'Loratadine is a non-sedating antihistamine, used to relieve the symptoms of allergic rhinitis (sneezing, runny nose, itchy eyes and nose). It is taken once a day and causes little drowsiness. In patients with liver or kidney disease, a dose adjustment may be needed.',
   'Anti-histamínico de segunda geração, antagonista seletivo periférico dos recetores H1, com baixa sedação. É um pró-fármaco: converte-se no metabolito ativo desloratadina. Indicado na rinite alérgica e na urticária idiopática crónica. Em doença hepática ou renal, a dose recomendada é de 10 mg em dias alternados.',
   'Second-generation antihistamine, selective peripheral H1 antagonist, with low sedation. It is a prodrug: it is converted to the active metabolite desloratadine. Indicated in allergic rhinitis and chronic idiopathic urticaria. In hepatic or renal disease, the recommended dose is 10 mg every other day.',
   E'Alívio temporário dos sintomas da rinite alérgica (corrimento nasal, espirros, comichão nos olhos, nariz ou garganta).',
   E'Temporary relief of hay fever/allergic rhinitis symptoms (runny nose, sneezing, itchy, watery eyes, itching of the nose or throat).',
   E'Cefaleia, sonolência (ligeira), fadiga, boca seca.\nNáuseas, dispepsia.\nReações de hipersensibilidade (rash, urticária, angioedema, anafilaxia — raras).\nEm doses acima do recomendado pode ocorrer sonolência.',
   E'Headache, drowsiness (mild), fatigue, dry mouth.\nNausea, dyspepsia.\nHypersensitivity reactions (rash, urticaria, angioedema, anaphylaxis — rare).\nDrowsiness may occur at doses above the recommended.',
   E'Não usar em caso de alergia à loratadina ou aos seus componentes.\nDoença hepática ou renal: consultar o médico — pode ser necessária dose diferente (10 mg em dias alternados).\nNão tomar mais do que o indicado (pode causar sonolência).\nSuspender e procurar ajuda médica se ocorrer reação alérgica.\nNa gravidez/amamentação, consultar o médico.',
   E'Do not use if allergic to loratadine or its components.\nLiver or kidney disease: ask a doctor — a different dose may be needed (10 mg every other day).\nDo not take more than directed (may cause drowsiness).\nStop use and seek medical help if an allergic reaction occurs.\nIn pregnancy/breastfeeding, ask a doctor.',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Loratadine (Drug Facts) + Yim DS. Br J Clin Pharmacol 2003 (PMID 12852841): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=41f8fc1d-2d14-48da-a233-23e9c11296d9',
   'DailyMed/FDA (NIH/NLM) — OTC Loratadine label (Drug Facts) + Yim DS. Br J Clin Pharmacol 2003 (PMID 12852841): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=41f8fc1d-2d14-48da-a233-23e9c11296d9'),

  ('metamizol',
   'O metamizol é um analgésico e antipirético usado na dor aguda moderada a grave e na febre alta quando outros medicamentos não são eficazes. É eficaz, mas pode causar uma diminuição grave dos glóbulos brancos (agranulocitose), pelo que só deve ser usado quando o benefício justifica o risco e sob vigilância médica.',
   'Metamizole (dipyrone) is an analgesic and antipyretic used for moderate to severe acute pain and high fever when other medicines are not effective. It is effective, but can cause a severe decrease in white blood cells (agranulocytosis), so it should only be used when the benefit justifies the risk and under medical supervision.',
   'Analgésico/antipirético (pirazolona) com eficácia demonstrada na dor aguda moderada a grave e na febre, mas com risco de agranulocitose potencialmente fatal que exige avaliação cuidada da relação risco-benefício. Pró-fármaco: hidrolisa-se rapidamente no metabolito ativo 4-metilaminoantipirina (MAA), semivida 2,6-3,5 h. Não comercializado nos EUA; disponível em Portugal e noutros países europeus. Precauções: antecedentes hematológicos, evitar uso prolongado.',
   'Analgesic/antipyretic (pyrazolone) with proven efficacy in moderate to severe acute pain and fever, but with a risk of potentially fatal agranulocytosis that requires a careful risk-benefit assessment. Prodrug: rapidly hydrolysed to the active metabolite 4-methylaminoantipyrine (MAA), half-life 2.6-3.5 h. Not marketed in the US; available in Portugal and other European countries. Precautions: haematological history, avoid prolonged use.',
   E'Dor aguda moderada a grave (pós-operatória, cólica, dor oncológica) e febre alta refratária, quando os analgésicos convencionais (paracetamol, AINE) são insuficientes ou contraindicados.',
   E'Moderate to severe acute pain (postoperative, colic, cancer pain) and refractory high fever, when conventional analgesics (paracetamol, NSAIDs) are insufficient or contraindicated.',
   E'Agranulocitose (rara mas potencialmente fatal) — manifesta-se por febre, infeções, úlceras orais; requer suspensão imediata e hemograma.\nReações anafiláticas/anafilactoides (raras; mais frequentes por via IV).\nReações cutâneas graves (SJS, TEN — raras).\nHipotensão (sobretudo com perfusão IV rápida).\nBroncospasmo em doentes asmáticos sensíveis.\nNáuseas, vómitos, dor abdominal.',
   E'Agranulocytosis (rare but potentially fatal) — manifests as fever, infections, oral ulcers; requires immediate discontinuation and blood count.\nAnaphylactic/anaphylactoid reactions (rare; more frequent with IV).\nSevere skin reactions (SJS, TEN — rare).\nHypotension (especially with rapid IV infusion).\nBronchospasm in susceptible asthmatic patients.\nNausea, vomiting, abdominal pain.',
   E'Usar a menor dose eficaz pelo menor tempo possível; avaliar a relação risco-benefício antes de cada utilização.\nNÃO usar em doentes com antecedentes de agranulocitose ou discrasias sanguíneas, hipersensibilidade a pirazolonas, porfiria ou défice de G6PD.\nVigiar sinais de agranulocitose (febre, infeção, úlceras orais) — suspender imediatamente e fazer hemograma.\nEvitar em doentes com asma sensível a AINE/aspirina.\nPrecaução na gravidez (evitar no 3.º trimestre), insuficiência renal e hepática grave.',
   E'Use the lowest effective dose for the shortest possible time; reassess the risk-benefit ratio before each use.\nDo NOT use in patients with a history of agranulocytosis or blood dyscrasias, pyrazolone hypersensitivity, porphyria or G6PD deficiency.\nMonitor for signs of agranulocytosis (fever, infection, oral ulcers) — discontinue immediately and obtain a blood count.\nAvoid in patients with NSAID/aspirin-sensitive asthma.\nCaution in pregnancy (avoid in the 3rd trimester), severe renal and hepatic impairment.',
   'Prontuário Terapêutico INFARMED (secção 2.10) + Levy M. Clin Pharmacokinet 1995 (PMID 7758252)',
   'Prontuário Terapêutico INFARMED (section 2.10) + Levy M. Clin Pharmacokinet 1995 (PMID 7758252)'),

  ('metoclopramida',
   'A metoclopramida é um medicamento procinético e antiemético, usado no tratamento de curta duração da doença de refluxo gastroesofágico sintomática e documentada que não respondeu à terapêutica convencional, e no alívio dos sintomas da gastroparesia diabética aguda e recorrente em adultos. Pode causar efeitos extrapiramidais e discinesia tardia, pelo que o uso é limitado no tempo.',
   'Metoclopramide is a prokinetic and antiemetic medicine, used for the short-term treatment of symptomatic, documented gastroesophageal reflux that has failed conventional therapy, and for the relief of symptoms in acute and recurrent diabetic gastroparesis in adults. It can cause extrapyramidal effects and tardive dyskinesia, so use is time-limited.',
   'Procinético (antagonista dopaminérgico D2) e antiemético: aumenta o tónus e a amplitude das contrações gástricas, relaxa o piloro e o bulbo duodenal, acelera o esvaziamento gástrico e aumenta o tónus do esfíncter esofágico inferior. Eficácia demonstrada apenas em 4-12 semanas no refluxo gastroesofágico e na gastroparesia diabética. Risco de discinesia tardia e síndrome extrapiramidal — não recomendado em pediatria; semivida 5-6 h.',
   'Prokinetic (dopamine D2 antagonist) and antiemetic: increases the tone and amplitude of gastric contractions, relaxes the pylorus and duodenal bulb, accelerates gastric emptying and raises lower oesophageal sphincter tone. Efficacy shown only for 4-12 weeks in gastroesophageal reflux and in diabetic gastroparesis. Risk of tardive dyskinesia and extrapyramidal syndrome — not recommended in paediatrics; half-life 5-6 h.',
   E'Tratamento durante 4 a 12 semanas do refluxo gastroesofágico sintomático e documentado em adultos que não respondem à terapêutica convencional.\nAlívio dos sintomas da gastroparesia diabética aguda e recorrente em adultos.',
   E'Treatment for 4 to 12 weeks of symptomatic, documented gastroesophageal reflux in adults who fail to respond to conventional therapy.\nRelief of symptoms in adults with acute and recurrent diabetic gastroparesis.',
   E'Discinesia tardia (risco com uso prolongado — pode ser irreversível).\nReações extrapiramidais: distonia aguda, parkinsonismo medicamentoso, acatisia; síndrome neuroléptica maligna (rara).\nInquietação, sonolência, fadiga e lassidão (~10% com 10 mg 4x/dia).\nDepressão com ideação suicida, confusão, cefaleia, tonturas, insónia.\nHiperprolactinemia: galactorreia, amenorreia, ginecomastia, impotência.\nHipotensão, hipertensão, taquicardia supraventricular, bradicardia; retenção de líquidos.\nAgranulocitose, neutropenia, leucopenia, metaemoglobinemia (raras).',
   E'Tardive dyskinesia (risk with prolonged use — may be irreversible).\nExtrapyramidal reactions: acute dystonia, drug-induced parkinsonism, akathisia; neuroleptic malignant syndrome (rare).\nRestlessness, drowsiness, fatigue and lassitude (~10% with 10 mg 4x/day).\nDepression with suicidal ideation, confusion, headache, dizziness, insomnia.\nHyperprolactinaemia: galactorrhoea, amenorrhoea, gynaecomastia, impotence.\nHypotension, hypertension, supraventricular tachycardia, bradycardia; fluid retention.\nAgranulocytosis, neutropenia, leukopenia, methaemoglobinaemia (rare).',
   E'NÃO usar por mais de 12 semanas no refluxo; na gastroparesia, usar a menor dose eficaz pelo menor tempo (risco de discinesia tardia — caixa preta).\nContraindicado em história de discinesia tardia ou reação distónica, quando a estimulação da motilidade é perigosa (hemorragia, obstrução, perfuração GI), feocromocitoma, epilepsia e hipersensibilidade.\nNÃO recomendado em pediatria (discinesia tardia e metaemoglobinemia nos recém-nascidos).\nVigiar sinais de discinesia tardia; suspender se ocorrerem.\nEvitar com outros fármacos que prolongam o QT e com IMAO; interação com inibidores do CYP2D6 (fluoxetina) aumenta a exposição.\nAvisar para não conduzir/operar máquinas (sonolência).',
   E'Do NOT use for more than 12 weeks in reflux; in gastroparesis use the lowest effective dose for the shortest time (tardive dyskinesia risk — black box).\nContraindicated in a history of tardive dyskinesia or dystonic reaction, when motility stimulation is dangerous (GI haemorrhage, obstruction, perforation), phaeochromocytoma, epilepsy and hypersensitivity.\nNOT recommended in paediatrics (tardive dyskinesia and methaemoglobinaemia in neonates).\nMonitor for signs of tardive dyskinesia; discontinue if they occur.\nAvoid with other QT-prolonging drugs and MAOIs; interaction with CYP2D6 inhibitors (fluoxetine) increases exposure.\nWarn patients not to drive/operate machinery (somnolence).',
   'DailyMed/FDA (NIH/NLM) — rótulo Metoclopramide Tablets (IPCA): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c143e210-4ce7-44e5-b1e2-bf0e6bfde485',
   'DailyMed/FDA (NIH/NLM) — Metoclopramide Tablets label (IPCA): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c143e210-4ce7-44e5-b1e2-bf0e6bfde485')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
        indications_pt, indications_en, side_effects_pt, side_effects_en,
        precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

-- =====================================================================
-- Farmacologia (drug_pharmacology) — mesma ordem de fármacos
-- =====================================================================
INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en, absorption_pt, absorption_en,
   half_life_pt, half_life_en, source_pt, source_en, status)
SELECT d.id, v.pharmacodynamics_pt, v.pharmacodynamics_en, v.mechanism_pt, v.mechanism_en,
       v.metabolism_pt, v.metabolism_en, v.absorption_pt, v.absorption_en,
       v.half_life_pt, v.half_life_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('nitroglicerina',
   'A ação principal é o relaxamento do músculo liso vascular: dilatação das grandes veias (acumulação periférica de sangue, redução da pré-carga) e, de forma dose-dependente, das artérias (redução da pós-carga), além da dilatação das artérias coronárias epicárdicas. Reduz a pressão arterial sistólica, diastólica e média; a frequência cardíaca aumenta ligeiramente por resposta compensatória. O efeito vasodilatador começa 1-3 minutos após a toma sublingual, atinge o máximo aos 5 minutos e dura pelo menos 25 minutos. O consumo miocárdico de oxigénio diminui e a relação oferta/consumo melhora.',
   'The principal action is relaxation of vascular smooth muscle: dilation of large veins (peripheral pooling, reduced preload) and, dose-dependently, of arteries (reduced afterload), plus dilation of the large epicardial coronary arteries. It lowers systolic, diastolic and mean arterial pressure; heart rate rises slightly as a compensatory response. The vasodilatory effect begins 1-3 minutes after sublingual dosing, peaks at 5 minutes and lasts at least 25 minutes. Myocardial oxygen demand decreases and the supply/demand ratio improves.',
   'A nitroglicerina liberta óxido nítrico (NO), que ativa a guanilato ciclase e aumenta o GMPc no músculo liso e noutros tecidos; isto leva à desfosforilação das cadeias leves de miosina (que regulam a contração do músculo liso) e à vasodilatação.',
   'Nitroglycerin generates nitric oxide (NO), which activates guanylate cyclase and raises cyclic GMP in smooth muscle and other tissues; this leads to dephosphorylation of myosin light chains (which regulate smooth muscle contraction) and vasodilation.',
   'Uma redutase hepática é a principal via de metabolização para glicerol di- e mononitratos e, finalmente, glicerol e nitrato orgânico; há também metabolismo extra-hepático nos eritrócitos e na parede vascular. Os metabolitos 1,2- e 1,3-dinitroglicerina têm semividas de 36 e 32 minutos e cerca de 2% e 10% da atividade da nitroglicerina; os mononitratos são inativos.',
   'A liver reductase is the main pathway of metabolism to glycerol di- and mononitrate metabolites and ultimately glycerol and organic nitrate; there is also extrahepatic metabolism in red blood cells and vascular walls. The 1,2- and 1,3-dinitroglycerin metabolites have half-lives of 36 and 32 minutes and about 2% and 10% of nitroglycerin activity; the mononitrates are inactive.',
   'Absorção rápida após administração sublingual: as concentrações plasmáticas máximas ocorrem em média 6-7 minutos após a toma. A biodisponibilidade absoluta é de aproximadamente 40%, mas é variável devido a fatores como a hidratação sublingual e o metabolismo da mucosa.',
   'Rapid absorption after sublingual administration: mean peak plasma concentrations occur about 6-7 minutes after dosing. Absolute bioavailability is approximately 40%, but is variable due to factors such as sublingual hydration and mucosal metabolism.',
   'Semivida de eliminação muito curta — em média 2 a 3 minutos (intervalo 1,5-7,5 minutos). O clearance (cerca de 13,6 L/min) excede em muito o fluxo sanguíneo hepático; a eliminação faz-se essencialmente por metabolismo.',
   'Very short elimination half-life — on average 2 to 3 minutes (range 1.5-7.5 minutes). Clearance (about 13.6 L/min) greatly exceeds hepatic blood flow; elimination is essentially by metabolism.',
   'DailyMed/FDA — Nitroglycerin Sublingual Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=84739085-81df-4a43-8456-c9edfbf971e9',
   'DailyMed/FDA — Nitroglycerin Sublingual Tablets, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=84739085-81df-4a43-8456-c9edfbf971e9'),

  ('paracetamol',
   'Analgésico e antipirético com eficácia bem estabelecida na dor ligeira a moderada e na febre; a atividade analgésica é predominantemente central (o mecanismo exato não está completamente esclarecido), com inibição da síntese de prostaglandinas no SNC e ação sobre vias serotoninérgicas descendentes.',
   'Analgesic and antipyretic with well-established efficacy in mild to moderate pain and fever; analgesic activity is predominantly central (the exact mechanism is not fully understood), with inhibition of prostaglandin synthesis in the CNS and actions on descending serotonergic pathways.',
   'O mecanismo analgésico envolve a inibição da ciclo-oxigenase central (COX-3/COX-2) e a modulação das vias serotoninérgicas descendentes inibitórias da dor; em doses terapêuticas tem pouca atividade anti-inflamatória periférica. Em sobredosagem, o metabolito reativo N-acetil-p-benzoquinonaimina (NAPQI) esgota a glutationa e causa necrose hepatocelular.',
   'The analgesic mechanism involves inhibition of central cyclooxygenase (COX-3/COX-2) and modulation of descending inhibitory serotonergic pain pathways; at therapeutic doses it has little peripheral anti-inflammatory activity. In overdose, the reactive metabolite N-acetyl-p-benzoquinoneimine (NAPQI) depletes glutathione and causes hepatocellular necrosis.',
   'Metabolização hepática extensa: conjugação com glucuronídeo (~55%) e sulfato (~30%) e oxidação via CYP (CYP2E1, CYP1A2, CYP3A4) com formação do metabolito reativo NAPQI, normalmente conjugado com glutationa; em sobredosagem o NAPQI acumula-se e lesa os hepatócitos. Cerca de 85% da dose aparece na urina em 24 horas, sobretudo como conjugados.',
   'Extensive hepatic metabolism: glucuronide (~55%) and sulfate (~30%) conjugation and CYP-mediated oxidation (CYP2E1, CYP1A2, CYP3A4) forming the reactive metabolite NAPQI, normally conjugated with glutathione; in overdose NAPQI accumulates and damages hepatocytes. About 85% of the dose appears in urine within 24 hours, mainly as conjugates.',
   'Absorção oral rápida e quase completa no intestino delgado, dependente do esvaziamento gástrico; as concentrações máximas ocorrem 30-60 minutos após a toma. A biodisponibilidade é de cerca de 75-85% (ligeiro efeito de primeira passagem).',
   'Rapid, almost complete oral absorption in the small intestine, dependent on gastric emptying; peak concentrations occur 30-60 minutes after dosing. Bioavailability is about 75-85% (slight first-pass effect).',
   'Semivida plasmática de 1,9 a 2,5 horas em doses terapêuticas (média ~2 h), com clearance total de 4,5-5,5 mL/min/kg; prolonga-se na doença hepática e na sobredosagem.',
   'Plasma half-life of 1.9 to 2.5 hours at therapeutic doses (mean ~2 h), with a total clearance of 4.5-5.5 mL/min/kg; prolonged in liver disease and overdose.',
   'Prescott LF. Clin Pharmacokinet 1982 (PMID 7039926) + rótulo OTC DailyMed Acetaminophen: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=50e7b939-e0eb-44ea-82ea-034e844e2c29',
   'Prescott LF. Clin Pharmacokinet 1982 (PMID 7039926) + DailyMed OTC Acetaminophen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=50e7b939-e0eb-44ea-82ea-034e844e2c29'),

  ('praziquantel',
   'O praziquantel induz uma contração rápida dos esquistossomas por efeito específico na permeabilidade da membrana celular do parasita, seguida de vacuolização e desintegração do tegumento; a exposição de antigénios do parasita facilita a ação imunológica do hospedeiro.',
   'Praziquantel induces rapid contraction of schistosomes by a specific effect on parasite cell membrane permeability, followed by vacuolization and disintegration of the tegument; exposure of parasite antigens facilitates the host immune response.',
   'O mecanismo de ação exato não é totalmente conhecido: aumenta a permeabilidade da membrana do parasita ao cálcio, causando contração espástica e dano do tegumento. É ativo contra Schistosoma spp. e trematódeos hepáticos (Clonorchis sinensis/Opisthorchis viverrini).',
   'The exact mechanism of action is not fully known: it increases parasite membrane permeability to calcium, causing spastic contraction and tegument damage. Active against Schistosoma spp. and liver flukes (Clonorchis sinensis/Opisthorchis viverrini).',
   'Rapidamente metabolizado pelo sistema enzimático do citocromo P450 (CYP3A4), com efeito de primeira passagem após administração oral; cerca de 80% da dose oral é excretada pelos rins, quase exclusivamente (>99%) como metabolitos.',
   'Rapidly metabolised by the cytochrome P450 enzyme system (CYP3A4), with a first-pass effect after oral administration; about 80% of an oral dose is excreted by the kidneys, almost exclusively (>99%) as metabolites.',
   'Após administração oral, cerca de 80% da dose é absorvida, com concentrações séricas máximas 1-3 horas após a toma. Em doentes com compromisso hepático moderado a grave (Child-Pugh B/C), o Cmax e a AUC aumentam progressivamente (até 4,3x e 15x no Child-Pugh C).',
   'After oral administration about 80% of the dose is absorbed, with peak serum concentrations 1-3 hours after dosing. In patients with moderate-to-severe hepatic impairment (Child-Pugh B/C), Cmax and AUC increase progressively (up to 4.3-fold and 15-fold in Child-Pugh C).',
   'Semivida de eliminação sérica de 0,8 a 1,5 horas após administração oral (aumenta na doença hepática: ~4,7 h no Child-Pugh B e ~8,5 h no Child-Pugh C).',
   'Serum elimination half-life of 0.8 to 1.5 hours after oral administration (increases in liver disease: ~4.7 h in Child-Pugh B and ~8.5 h in Child-Pugh C).',
   'DailyMed/FDA — Biltricide (praziquantel), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34ce1cdd-648e-4f1e-8512-bf3d4cc22eb9',
   'DailyMed/FDA — Biltricide (praziquantel), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34ce1cdd-648e-4f1e-8512-bf3d4cc22eb9'),

  ('valsartana',
   'Bloqueia a vasoconstrição e a secreção de aldosterona induzidas pela angiotensina II. Uma dose oral de 80 mg inibe o efeito pressor da angiotensina II em cerca de 80% no pico, com cerca de 30% de inibição persistindo às 24 horas. Não inibe a ACE (sem efeito sobre a bradicinina — menor tosse) e não interfere com outros recetores hormonais ou canais iónicos relevantes.',
   'Blocks angiotensin II-induced vasoconstriction and aldosterone secretion. An oral 80 mg dose inhibits the pressor effect of angiotensin II by about 80% at peak, with about 30% inhibition persisting at 24 hours. It does not inhibit ACE (no effect on bradykinin — less cough) and does not interfere with other hormone receptors or relevant ion channels.',
   'Antagonista seletivo e competitivo dos recetores AT1 da angiotensina II (afinidade ~20 000x maior para AT1 do que AT2), independente das vias de síntese da angiotensina II. O bloqueio remove o feedback negativo sobre a renina (aumento de 2-3x da renina plasmática) sem ultrapassar o efeito anti-hipertensor.',
   'Selective competitive antagonist of angiotensin II AT1 receptors (affinity ~20,000-fold greater for AT1 than AT2), independent of angiotensin II synthesis pathways. Blockade removes the negative feedback on renin (2-3-fold rise in plasma renin) without overcoming the antihypertensive effect.',
   'Metabolização limitada: o principal metabolito (valeril-4-hidroxi-valsartana, cerca de 9% da dose) forma-se via CYP2C9. Não inibe os CYP450 em concentrações clinicamente relevantes — interações metabólicas pouco prováveis. Eliminação sobretudo nas fezes (~83%) e urina (~13%), maioritariamente como fármaco inalterado.',
   'Limited metabolism: the main metabolite (valeryl-4-hydroxy-valsartan, about 9% of the dose) is formed via CYP2C9. Does not inhibit CYP450 enzymes at clinically relevant concentrations — metabolic interactions unlikely. Eliminated mainly in faeces (~83%) and urine (~13%), mostly as unchanged drug.',
   'Pico plasmático 2-4 horas após a toma; biodisponibilidade absoluta ~25% (intervalo 10-35%). A comida reduz a exposição em ~40% (AUC) e o pico em ~50%, sem necessidade de ajuste. Volume de distribuição pequeno (17 L); ligação às proteínas ~95%.',
   'Peak plasma levels 2-4 hours after dosing; absolute bioavailability ~25% (range 10-35%). Food reduces exposure by ~40% (AUC) and peak by ~50%, without requiring adjustment. Small volume of distribution (17 L); protein binding ~95%.',
   'Semivida de eliminação média de cerca de 6 horas (decréscimo biexponencial); não acumula apreciavelmente com administração repetida. A exposição é ~70% maior e a semivida 35% mais longa nos idosos; duplica nos doentes com doença hepática ligeira a moderada.',
   'Mean elimination half-life of about 6 hours (bi-exponential decay); no appreciable accumulation with repeated dosing. Exposure is ~70% higher and half-life 35% longer in the elderly; doubles in patients with mild-to-moderate liver disease.',
   'DailyMed/FDA — Valsartan Tablets (Macleods), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=251ccff4-bf86-453b-9d1c-e3c1ecfd3a46',
   'DailyMed/FDA — Valsartan Tablets label (Macleods), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=251ccff4-bf86-453b-9d1c-e3c1ecfd3a46'),

  ('vancomicina',
   'Após administração oral, a vancomicina atua localmente no lúmen intestinal (ação bactericida contra C. difficile e S. aureus). Por via IV é bactericida dependente do tempo, com atividade contra Gram-positivos. A nefrotoxicidade ocorreu em 5% dos doentes com diarreia por C. difficile; ototoxicidade reportada sobretudo por via IV.',
   'After oral administration, vancomycin acts locally in the gut lumen (bactericidal activity against C. difficile and S. aureus). Given IV it is time-dependent bactericidal, active against Gram-positives. Nephrotoxicity occurred in 5% of patients with C. difficile diarrhoea; ototoxicity reported mainly with IV use.',
   'A ação bactericida contra S. aureus e as formas vegetativas de C. difficile resulta sobretudo da inibição da biossíntese da parede celular; altera também a permeabilidade da membrana bacteriana e a síntese de RNA.',
   'The bactericidal action against S. aureus and the vegetative cells of C. difficile results primarily from inhibition of cell-wall biosynthesis; it also alters bacterial membrane permeability and RNA synthesis.',
   'Praticamente não é metabolizada. Por via oral é essencialmente não absorvida, atuando no intestino; por via IV é excretada por filtração glomerular (cerca de 75% da dose em 24 horas), sem metabolismo aparente.',
   'Virtually no metabolism. Given orally it is essentially unabsorbed, acting in the gut; given IV it is excreted by glomerular filtration (about 75% of the dose in 24 hours), with no apparent metabolism.',
   'Absorção oral desprezível: após doses orais repetidas, as concentrações fecais excedem 100 mg/kg e não são detetadas concentrações sanguíneas (recuperação urinária <0,76%). Em doentes com diarreia ativa por C. difficile, podem ocorrer concentrações séricas mensuráveis; com insuficiência renal existe possibilidade de acumulação. Por via IV, distribui-se amplamente (coeficiente 0,3-0,43 L/kg); ligação proteica ~55%.',
   'Negligible oral absorption: after repeated oral doses, faecal concentrations exceed 100 mg/kg and no blood concentrations are detected (urinary recovery <0.76%). In patients with active C. difficile diarrhoea, measurable serum concentrations may occur; with renal impairment accumulation is possible. Given IV, it distributes widely (coefficient 0.3-0.43 L/kg); protein binding ~55%.',
   'Por via oral a semivida não é mensurável (ausência de absorção sistémica). Por via IV, a semivida de eliminação é de 4-6 horas em doentes com função renal normal; em doentes anéfricos a semivida média é de 7,5 dias. A semivida correlaciona-se com a depuração da creatinina.',
   'Orally the half-life is not measurable (no systemic absorption). Given IV, the elimination half-life is 4-6 hours in patients with normal renal function; in anephric patients the mean half-life is 7.5 days. Half-life correlates with creatinine clearance.',
   'DailyMed/FDA — Vancomycin HCl Capsules (secção 12) + Vancomycin Injection Hospira (secção 12): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=57d23aed-a3f7-f92e-e063-6394a90add7d',
   'DailyMed/FDA — Vancomycin HCl Capsules (section 12) + Vancomycin Injection Hospira (section 12): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=57d23aed-a3f7-f92e-e063-6394a90add7d'),
  ('sulfadoxina-pirimetamina',
   'Associação sinérgica de dois antifolatos: a pirimetamina inibe a di-hidrofolato redutase do parasita e a sulfadoxina (sulfonamida) inibe a di-hidropteroato sintase, bloqueando em dois pontos a síntese de folatos do plasmódio. Esta ação é esquizonticida sanguínea de ação lenta e prolongada, adequada à prevenção mas não ao tratamento curativo da malária aguda.',
   'Synergistic combination of two antifolates: pyrimethamine inhibits the parasite dihydrofolate reductase and sulfadoxine (a sulfonamide) inhibits dihydropteroate synthase, blocking plasmodial folate synthesis at two points. This action is slow-acting, long-lasting blood schizonticidal, suitable for prevention but not for curative treatment of acute malaria.',
   'A pirimetamina antagoniza o ácido fólico do parasita ao inibir a di-hidrofolato redutase; a sulfadoxina inibe competitivamente a di-hidropteroato sintase. O bloqueio sequencial da síntese de tetrahidrofolato é letal para o plasmódio em divisão.',
   'Pyrimethamine antagonises parasite folic acid by inhibiting dihydrofolate reductase; sulfadoxine competitively inhibits dihydropteroate synthase. The sequential blockade of tetrahydrofolate synthesis is lethal to the dividing plasmodium.',
   'A sulfadoxina é parcialmente metabolizada (N-acetilação e glucuronidação); a pirimetamina é extensamente metabolizada no fígado. Ambos são eliminados principalmente pelos rins, com semividas longas que sustentam o efeito preventivo prolongado.',
   'Sulfadoxine is partially metabolised (N-acetylation and glucuronidation); pyrimethamine is extensively metabolised in the liver. Both are eliminated mainly by the kidneys, with long half-lives that sustain the prolonged preventive effect.',
   'Biodisponibilidade oral superior a 90% para ambos os fármacos; o pico plasmático ocorre cerca de 3 horas após a toma. A sulfadoxina tem um volume de distribuição de 0,14 L/kg e a pirimetamina de 2,3 L/kg (ampla distribuição; atravessa a placenta e passa ao leite).',
   'Oral bioavailability over 90% for both drugs; peak plasma levels occur about 3 hours after dosing. Sulfadoxine has a volume of distribution of 0.14 L/kg and pyrimethamine of 2.3 L/kg (wide distribution; crosses the placenta and passes into milk).',
   'Semividas longas: cerca de 200 horas (~8-9 dias) para a sulfadoxina e cerca de 100 horas (~4 dias) para a pirimetamina; acumulam em doentes com insuficiência renal ou hepática.',
   'Long half-lives: about 200 hours (~8-9 days) for sulfadoxine and about 100 hours (~4 days) for pyrimethamine; they accumulate in patients with renal or hepatic failure.',
   'SmPC WHO-prequalificada — Sulfadoxine/Pyrimethamine (MA193), secção 5.2 Pharmacokinetic properties: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA193part4v1.pdf',
   'WHO-prequalified SmPC — Sulfadoxine/Pyrimethamine (MA193), section 5.2 Pharmacokinetic properties: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA193part4v1.pdf'),

  ('ampicilina',
   'Antibiótico beta-lactâmico bactericida (inibição da síntese da parede celular durante a fase de multiplicação ativa), com atividade contra Gram-positivos usualmente sensíveis à penicilina G e contra vários Gram-negativos. Em soro, é a penicilina com menor ligação proteica (~20% vs 60-90% das outras); uma dose oral de 500 mg produz um pico sérico médio de ~3,0 mcg/mL. Estável ao ácido gástrico.',
   'Bactericidal beta-lactam antibiotic (inhibition of cell-wall synthesis during active multiplication), active against Gram-positives usually susceptible to penicillin G and against several Gram-negatives. In serum it is the least protein-bound penicillin (~20% vs 60-90% for others); a 500 mg oral dose produces a mean peak serum level of ~3.0 mcg/mL. Acid-stable.',
   'Ação bactericida semelhante à penicilina G: liga-se às proteínas de ligação à penicilina (PBP) e inibe a transpeptidação da parede celular, levando à lise bacteriana. A resistência é mediada sobretudo por beta-lactamases que clivam o anel beta-lactâmico.',
   'Bactericidal action similar to penicillin G: binds penicillin-binding proteins (PBPs) and inhibits cell-wall transpeptidation, leading to bacterial lysis. Resistance is mediated mainly by beta-lactamases that cleave the beta-lactam ring.',
   'Excretada em grande parte inalterada na urina (secreção tubular, atrasada pela probenecida); pequena fração metabolizada. Difunde-se para a maioria dos tecidos e fluidos; a penetração no LCR e cérebro ocorre apenas com inflamação meníngea.',
   'Largely excreted unchanged in urine (tubular secretion, delayed by probenecid); a small fraction is metabolised. Diffuses into most tissues and fluids; CSF and brain penetration occurs only with meningeal inflammation.',
   'Estável ao ácido gástrico e bem absorvida no trato gastrointestinal; a absorção oral é incompleta (~40-60%) e atrasada pelos alimentos. Pico sérico ~1-2 horas após a toma oral.',
   'Acid-stable and well absorbed from the gastrointestinal tract; oral absorption is incomplete (~40-60%) and delayed by food. Peak serum levels ~1-2 hours after oral dosing.',
   'Semivida de eliminação de aproximadamente 1 hora em doentes com função renal normal (1,0-1,3 h); prolonga-se na insuficiência renal.',
   'Elimination half-life of approximately 1 hour in patients with normal renal function (1.0-1.3 h); prolonged in renal impairment.',
   'DailyMed/FDA — Ampicillin Capsules (secção 11/12) + PubMed (PMID 2660866): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4134cd79-c895-4e6e-b1d5-8e01c38bf2d1',
   'DailyMed/FDA — Ampicillin Capsules label (sections 11/12) + PubMed (PMID 2660866): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4134cd79-c895-4e6e-b1d5-8e01c38bf2d1'),

  ('lamotrigina',
   'Efeito anticonvulsivante e estabilizador do humor; a eficácia na epilepsia foi demonstrada na prevenção da propagação das crises (modelos MES, pentilenotetrazol e kindling). Não inibe a atividade mediada pelos recetores NMDA. Inibe a di-hidrofolato redutase in vitro (relevância clínica desconhecida).',
   'Anticonvulsant and mood-stabilising effect; efficacy in epilepsy was shown in preventing seizure spread (MES, pentylenetetrazol and kindling models). Does not inhibit NMDA-receptor-mediated activity. Inhibits dihydrofolate reductase in vitro (clinical relevance unknown).',
   'O mecanismo proposto envolve a inibição dos canais de sódio dependentes de voltagem, estabilizando as membranas neuronais e modulando a libertação pré-sináptica de aminoácidos excitatórios (glutamato e aspartato).',
   'The proposed mechanism involves inhibition of voltage-sensitive sodium channels, stabilising neuronal membranes and modulating presynaptic release of excitatory amino acids (glutamate and aspartate).',
   'Metabolizada predominantemente por conjugação com ácido glucurónico (metabolito principal: 2-N-glucuronídeo, inativo); auto-indução do metabolismo (~25% de redução da semivida com doses múltiplas). Indutores da glucuronidação (carbamazepina, fenitoína, fenobarbital, rifampicina, contraceptivos orais) aceleram a eliminação; o valproato inibe-a (semivida ~59 h). Recuperação urinária de 94% da dose.',
   'Metabolised predominantly by glucuronic acid conjugation (main metabolite: inactive 2-N-glucuronide); self-induction of metabolism (~25% half-life reduction with multiple doses). Glucuronidation inducers (carbamazepine, phenytoin, phenobarbital, rifampin, oral contraceptives) accelerate elimination; valproate inhibits it (half-life ~59 h). 94% of the dose is recovered in urine.',
   'Absorção oral rápida e quase completa (biodisponibilidade absoluta 98%), sem efeito de primeira passagem relevante e sem influência dos alimentos; pico plasmático 1,4-4,8 horas após a toma. Volume de distribuição 0,9-1,3 L/kg; ligação proteica ~55%.',
   'Rapid, almost complete oral absorption (absolute bioavailability 98%), without relevant first-pass effect and unaffected by food; peak plasma levels 1.4-4.8 hours after dosing. Volume of distribution 0.9-1.3 L/kg; protein binding ~55%.',
   'Semivida de eliminação de cerca de 25-33 horas em adultos saudáveis sem medicação concomitante; ~14,4 horas com indutores enzimáticos e ~58,8 horas com valproato.',
   'Elimination half-life of about 25-33 hours in healthy adults without concomitant medication; ~14.4 hours with enzyme inducers and ~58.8 hours with valproate.',
   'DailyMed/FDA — Lamotrigine Tablets (Alembic), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=60958229-5b5f-49e2-97f4-a8722138f7ce',
   'DailyMed/FDA — Lamotrigine Tablets label (Alembic), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=60958229-5b5f-49e2-97f4-a8722138f7ce'),

  ('haloperidol',
   'Antipsicótico típico com potente antagonismo dopaminérgico D2 (efeito antipsicótico e extrapiramidal dose-dependente); sem atividade anticolinérgica relevante. Pode prolongar o intervalo QT e associar-se a arritmias ventriculares (torsades de pointes), sobretudo em altas doses e em doentes predispostos.',
   'Typical antipsychotic with potent D2 dopaminergic antagonism (dose-dependent antipsychotic and extrapyramidal effect); no relevant anticholinergic activity. May prolong the QT interval and is associated with ventricular arrhythmias (torsades de pointes), especially at high doses and in predisposed patients.',
   'Antagonista dos recetores dopaminérgicos D2 centrais (mesolímbicos e nigroestriados); o bloqueio nigroestriado é responsável pelos efeitos extrapiramidais. O mecanismo preciso da ação antipsicótica não está totalmente estabelecido.',
   'Antagonist of central D2 dopamine receptors (mesolimbic and nigrostriatal); nigrostriatal blockade is responsible for the extrapyramidal effects. The precise mechanism of antipsychotic action is not fully established.',
   'Extensa metabolização hepática (CYP3A4 e CYP2D6), incluindo redução a haloperidol reduzido (metabolito ativo); cerca de 60% da dose é excretada na urina como metabolitos. A eliminação faz-se sobretudo por metabolismo, com pouco fármaco inalterado.',
   'Extensive hepatic metabolism (CYP3A4 and CYP2D6), including reduction to reduced haloperidol (an active metabolite); about 60% of the dose is excreted in urine as metabolites. Elimination is mainly by metabolism, with little unchanged drug.',
   'Biodisponibilidade oral de 60-65% (efeito de primeira passagem); pico plasmático cerca de 2-6 horas após a toma. Ligação proteica ~90%.',
   'Oral bioavailability of 60-65% (first-pass effect); peak plasma levels about 2-6 hours after dosing. Protein binding ~90%.',
   'Semivida de eliminação de cerca de 14,5-36,7 horas após dose oral única (média ~20 h); prolonga-se em alguns doentes.',
   'Elimination half-life of about 14.5-36.7 hours after a single oral dose (mean ~20 h); prolonged in some patients.',
   'DailyMed/FDA — Haloperidol Tablets + Kudo S, Ishizaki T. Clin Pharmacokinet 1999 (PMID 10628896): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb3ac3e-7459-42d3-b5ca-e0d6d27ced73',
   'DailyMed/FDA — Haloperidol Tablets label + Kudo S, Ishizaki T. Clin Pharmacokinet 1999 (PMID 10628896): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb3ac3e-7459-42d3-b5ca-e0d6d27ced73'),

  ('clozapina',
   'Antipsicótico atípico com afinidade por múltiplos recetores (H1, alfa-1A, 5-HT6, 5-HT2A, M1, D4, 5-HT2C e D2), o que explica o perfil de efeitos (sedação, hipotensão ortostática, ganho de peso, sialorreia). Causa pouca ou nenhuma elevação da prolactina. Aumenta a atividade delta/theta no EEG (risco convulsivo dose-dependente, ~3%).',
   'Atypical antipsychotic with affinity for multiple receptors (H1, alpha-1A, 5-HT6, 5-HT2A, M1, D4, 5-HT2C and D2), explaining the effect profile (sedation, orthostatic hypotension, weight gain, hypersalivation). Causes little or no prolactin elevation. Increases delta/theta EEG activity (dose-dependent seizure risk, ~3%).',
   'O mecanismo exato é desconhecido; propõe-se que a eficácia na esquizofrenia seja mediada pelo antagonismo dos recetores D2 e 5-HT2A, com menor risco extrapiramidal que os antipsicóticos típicos.',
   'The exact mechanism is unknown; efficacy in schizophrenia is proposed to be mediated by D2 and 5-HT2A antagonism, with lower extrapyramidal risk than typical antipsychotics.',
   'Quase completamente metabolizada antes da excreção (apenas vestígios inalterados na urina e fezes); substrato de múltiplos CYP (CYP1A2, CYP2D6, CYP3A4). Cerca de 50% da dose na urina e 30% nas fezes. Inibidores do CYP1A2 (fluvoxamina) elevam os níveis ~3x.',
   'Almost completely metabolised before excretion (only traces unchanged in urine and faeces); substrate of multiple CYPs (CYP1A2, CYP2D6, CYP3A4). About 50% of the dose in urine and 30% in faeces. CYP1A2 inhibitors (fluvoxamine) raise levels ~3-fold.',
   'Biodisponibilidade oral equivalente à solução (comprimidos 25/100 mg); pico em estado estacionário ~2,5 horas (1-6 h) após a toma; a comida não afeta a absorção. Ligação proteica ~97%.',
   'Oral bioavailability equivalent to the solution (25/100 mg tablets); steady-state peak ~2.5 hours (1-6 h) after dosing; food does not affect absorption. Protein binding ~97%.',
   'Semivida de eliminação média de 8 horas após dose única de 75 mg (intervalo 4-12 h) e de 12 horas em estado estacionário (intervalo 4-66 h) — farmacocinética possivelmente concentração-dependente.',
   'Mean elimination half-life of 8 hours after a single 75 mg dose (range 4-12 h) and 12 hours at steady state (range 4-66 h) — possibly concentration-dependent pharmacokinetics.',
   'DailyMed/FDA — Clozapine Tablets (Aurobindo), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5021d643-32d2-4167-b5d8-90870e68a787',
   'DailyMed/FDA — Clozapine Tablets label (Aurobindo), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5021d643-32d2-4167-b5d8-90870e68a787'),
  ('acido_folico',
   'Vitamina hidrossolúvel (folato) essencial para a síntese de nucleoproteínas e para a manutenção da eritropoiese normal. Corrige as anemias megaloblásticas por défice de folato (anemia nutricional, da gravidez, da infância, sprue tropical/não tropical). O folato sérico normal situa-se entre 5 e 15 ng/mL; níveis abaixo de 2 ng/mL associam-se habitualmente a anemia megaloblástica. É relativamente atóxico; os efeitos adversos são raros (reações alérgicas, perturbações gastrointestinais com doses de 15 mg/dia).',
   'Water-soluble vitamin (folate) essential for nucleoprotein synthesis and the maintenance of normal erythropoiesis. It corrects megaloblastic anaemias due to folate deficiency (nutritional, pregnancy, infancy, tropical/non-tropical sprue). Normal serum folate ranges from 5 to 15 ng/mL; levels below 2 ng/mL usually result in megaloblastic anaemia. Relatively non-toxic; adverse effects are rare (allergic reactions, GI upset at 15 mg/day).',
   'O ácido fólico é o precursor do ácido tetra-hidrofólico, que atua como cofator nas reações de transformilação da biossíntese de purinas e timidilatos dos ácidos nucleicos. A deficiência de síntese de timidilato explica a síntese defeituosa de ADN que leva à formação de megaloblastos e às anemias megaloblásticas e macrocíticas. A ação sobre a medula megaloblástica produz uma medula normoblástica.',
   'Folic acid is the precursor of tetrahydrofolic acid, which acts as a cofactor in transformylation reactions in the biosynthesis of purines and thymidylates of nucleic acids. Impaired thymidylate synthesis accounts for the defective DNA synthesis that leads to megaloblast formation and megaloblastic/macrocytic anaemias. Its action on megaloblastic marrow produces a normoblastic marrow.',
   'Metabolizado no fígado em ácido 7,8-di-hidrofólico e, em seguida, em ácido 5,6,7,8-tetra-hidrofólico (com a ajuda da DPNH e das redutases do folato); os derivados do tetra-hidrofólico são distribuídos por todos os tecidos, mas são armazenados principalmente no fígado. Após uma dose oral de 15 mg, até 90% da dose é recuperada na urina; a excreção é geralmente completa em 24 horas. Pequenas quantidades são recuperadas nas fezes e o folato é também excretado no leite materno.',
   'Metabolised in the liver to 7,8-dihydrofolic acid and then to 5,6,7,8-tetrahydrofolic acid (with the aid of DPNH and folate reductases); tetrahydrofolate derivatives are distributed to all body tissues but stored mainly in the liver. After a single 15 mg oral dose, up to 90% of the dose is recovered in the urine; excretion is generally complete within 24 hours. Small amounts are recovered in faeces and folate is also excreted in breast milk.',
   'Absorvido rapidamente no intestino delgado, sobretudo na porção proximal. Aparece no plasma aproximadamente 15 a 30 minutos após a dose oral; os níveis máximos são geralmente atingidos em 1 hora. Os folatos conjugados naturais são reduzidos enzimaticamente a ácido fólico no trato gastrointestinal antes da absorção. Os níveis de folato no líquido cefalorraquidiano são várias vezes superiores aos do soro.',
   'Rapidly absorbed from the small intestine, primarily from the proximal portion. It appears in plasma approximately 15 to 30 minutes after an oral dose; peak levels are generally reached within 1 hour. Naturally occurring conjugated folates are reduced enzymatically to folic acid in the GI tract prior to absorption. CSF folate levels are several times greater than serum levels.',
   'Não tem uma semivida plasmática clássica de eliminação: após doses baixas (100 mcg) apenas uma quantidade vestigial aparece na urina, enquanto doses de 5 mg ou 40 mcg/kg resultam em cerca de 50% da dose na urina e 15 mg em até 90% (maioria nas primeiras 6 horas, excreção completa em 24 horas). Os níveis eritrocitários normais de folato variam entre 175 e 316 ng/mL.',
   'No classical plasma elimination half-life: after low doses (100 mcg) only a trace amount appears in urine, whereas doses of 5 mg or 40 mcg/kg result in about 50% of the dose in urine and 15 mg in up to 90% (majority in the first 6 hours, excretion complete within 24 hours). Normal erythrocyte folate levels range from 175 to 316 ng/mL.',
   'DailyMed/FDA — Folic Acid Tablets USP, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0baa10dd-6d1d-4946-8236-566451132da3',
   'DailyMed/FDA — Folic Acid Tablets USP label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0baa10dd-6d1d-4946-8236-566451132da3'),

  ('amicacina',
   'Aminoglicosídeo bactericida de amplo espetro dirigido sobretudo a Gram-negativos (Pseudomonas, Escherichia coli, Klebsiella-Enterobacter-Serratia, Proteus, Acinetobacter), também ativo contra estafilococos e muitas estirpes resistentes à gentamicina e tobramicina. Indicado no tratamento de curta duração de infeções graves (septicemia, trato respiratório, osso e articulações, SNC incluindo meningite, pele e tecidos moles, intra-abdominais, queimaduras e infeções urinárias complicadas e recorrentes). O potencial de ototoxicidade, nefrotoxicidade e bloqueio neuromuscular limita o seu uso.',
   'Bactericidal broad-spectrum aminoglycoside directed mainly at Gram-negatives (Pseudomonas, Escherichia coli, Klebsiella-Enterobacter-Serratia, Proteus, Acinetobacter), also active against staphylococci and many gentamicin- and tobramycin-resistant strains. Indicated for short-term treatment of serious infections (septicaemia, respiratory tract, bone and joints, CNS including meningitis, skin and soft tissue, intra-abdominal, burns, and complicated/recurrent urinary tract infections). The potential for ototoxicity, nephrotoxicity and neuromuscular blockade limits its use.',
   'Liga-se ao ribossoma procariótico, inibindo a síntese proteica nas bactérias suscetíveis; é bactericida in vitro contra bactérias Gram-positivas e Gram-negativas. Resistente à degradação por várias enzimas inativadoras de aminoglicosídeos que afetam gentamicina, tobramicina e canamicina. A associação com um beta-lactâmico é sinérgica contra muitos Gram-negativos clinicamente significativos.',
   'Binds to the prokaryotic ribosome, inhibiting protein synthesis in susceptible bacteria; bactericidal in vitro against Gram-positive and Gram-negative bacteria. Resists degradation by several aminoglycoside-inactivating enzymes that affect gentamicin, tobramycin and kanamycin. Combination with a beta-lactam is synergistic against many clinically significant Gram-negatives.',
   'Excretada essencialmente por filtração glomerular sem metabolização relevante: com função renal normal, cerca de 91,9% de uma dose intramuscular é excretada inalterada na urina nas primeiras 8 horas e 98,2% em 24 horas (84% em 9 h e cerca de 94% em 24 h após perfusão IV). Na insuficiência renal a excreção é muito mais lenta, prolongando a semivida — ajustar a dose.',
   'Excreted essentially by glomerular filtration with no relevant metabolism: with normal renal function about 91.9% of an intramuscular dose is excreted unchanged in urine in the first 8 hours and 98.2% within 24 hours (84% in 9 h and about 94% within 24 h after IV infusion). In renal impairment excretion is much slower, prolonging half-life — adjust the dose.',
   'Rapidamente absorvida após administração intramuscular: picos séricos médios de cerca de 12, 16 e 21 mcg/mL 1 hora após doses de 250, 375 e 500 mg (3,7, 5 e 7,5 mg/kg); após perfusão IV de 500 mg em 30 minutos o pico médio é de 38 mcg/mL no fim da perfusão. Volume de distribuição médio de 24 L (28% do peso corporal); ligação proteica de 0 a 11% (ultrafiltração). Permanece sobretudo no espaço extracelular.',
   'Rapidly absorbed after intramuscular administration: mean peak serum concentrations of about 12, 16 and 21 mcg/mL 1 hour after 250, 375 and 500 mg doses (3.7, 5 and 7.5 mg/kg); after a 500 mg IV infusion over 30 minutes the mean peak is 38 mcg/mL at the end of the infusion. Mean volume of distribution 24 L (28% of body weight); protein binding 0 to 11% (ultrafiltration). Remains mainly in the extracellular space.',
   'Semivida sérica média ligeiramente superior a 2 horas com função renal normal; clearance sérico médio de cerca de 100 mL/min (clearance renal 94 mL/min). Prolonga-se na insuficiência renal (correlacionada inversamente com a idade pós-natal nos recém-nascidos) e na insuficiência cardíaca. Concentrações terapêuticas encontram-se no osso, coração, vesícula biliar e pulmão, além da urina, bílis e expetoração.',
   'Mean serum half-life slightly over 2 hours with normal renal function; mean serum clearance about 100 mL/min (renal clearance 94 mL/min). Prolonged in renal impairment (correlated inversely with postnatal age in neonates) and in heart failure. Therapeutic levels are found in bone, heart, gallbladder and lung, in addition to urine, bile and sputum.',
   'DailyMed/FDA — Amikacin Sulfate Injection USP (Sagent), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f260ff2a-76a0-4672-9516-91c344b67890',
   'DailyMed/FDA — Amikacin Sulfate Injection USP label (Sagent), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f260ff2a-76a0-4672-9516-91c344b67890'),

  ('azitromicina',
   'Macrólido antibacteriano bactericida/bacteriostático de largo espetro (respiratório, pele e tecidos moles, uretrite/cervicite não complicadas). Penetra extensamente nos tecidos (concentrações tecidulares muito superiores às séricas), com semivida terminal longa que permite regimes curtos (3-5 dias). Prolonga o intervalo QTc de forma dose- e concentração-dependente (máximo médio +9 ms com 1500 mg em coadministração com cloroquina).',
   'Broad-spectrum macrolide antibacterial (respiratory tract, skin and soft tissue, uncomplicated urethritis/cervicitis). Penetrates extensively into tissues (tissue concentrations far above serum), with a long terminal half-life allowing short courses (3-5 days). Prolongs the QTc interval in a dose- and concentration-dependent manner (maximum mean +9 ms with 1500 mg co-administered with chloroquine).',
   'Antibacteriano macrólido; nos modelos animais de infeção a atividade correlaciona-se com a razão AUC/CIM (área sob a curva/concentração mínima inibitória) para certos patogénicos (S. pneumoniae e S. aureus). O parâmetro farmacocinético/farmacodinâmico associado à cura clínica e microbiológica não foi totalmente elucidado nos ensaios clínicos.',
   'Macrolide antibacterial; in animal infection models the antibacterial activity correlates with the AUC/MIC ratio (area under the curve/minimum inhibitory concentration) for certain pathogens (S. pneumoniae and S. aureus). The pharmacokinetic/pharmacodynamic parameter best associated with clinical and microbiological cure has not been fully elucidated in clinical trials.',
   'Metabolização mínima (não foram realizados estudos formais in vitro/in vivo do metabolismo). A excreção biliar de azitromicina, predominantemente como fármaco inalterado, é a principal via de eliminação; ao longo de uma semana apenas cerca de 6% da dose administrada aparece inalterada na urina. A semivida terminal prolongada deve-se à extensa captação e posterior libertação do fármaco pelos tecidos.',
   'Minimal metabolism (no formal in vitro/in vivo metabolism studies were performed). Biliary excretion of azithromycin, predominantly as unchanged drug, is a major route of elimination; over the course of a week only about 6% of the administered dose appears unchanged in urine. The prolonged terminal half-life is thought to be due to extensive uptake and subsequent release of drug from tissues.',
   'Biodisponibilidade oral absoluta de 38% (cápsulas de 250 mg). Após dose oral única de 500 mg em jejum: Cmax média 0,5 mcg/mL, Tmax 2,2 horas. A ligação proteica sérica é variável, diminuindo de 51% a 0,02 mcg/mL para 7% a 2 mcg/mL. A comida aumenta a Cmax (23-56% conforme a formulação) sem alterar a AUC.',
   'Absolute oral bioavailability of 38% (250 mg capsules). After a single 500 mg oral dose under fasting conditions: mean Cmax 0.5 mcg/mL, Tmax 2.2 hours. Serum protein binding is variable, decreasing from 51% at 0.02 mcg/mL to 7% at 2 mcg/mL. Food increases Cmax (23-56% depending on formulation) without changing AUC.',
   'Semivida terminal de eliminação de aproximadamente 68 horas (padrão polifásico; clearance plasmático aparente médio de 630 mL/min) — a semivida prolongada deve-se à extensa captação tecidular e não a uma eliminação lenta do fármaco circulante. A semivida sérica na fase terminal após regime de 3 ou 5 dias é de 68,9-71,8 horas.',
   'Terminal elimination half-life of approximately 68 hours (polyphasic pattern; mean apparent plasma clearance 630 mL/min) — the prolonged half-life is due to extensive tissue uptake rather than slow elimination of circulating drug. Serum terminal half-life after 3- or 5-day regimens is 68.9-71.8 hours.',
   'DailyMed/FDA — Azithromycin Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=db52b91e-79f7-4cc1-9564-f2eee8e31c45',
   'DailyMed/FDA — Azithromycin Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=db52b91e-79f7-4cc1-9564-f2eee8e31c45'),

  ('bumetanida',
   'Diurético da ansa de ação rápida e curta duração; 1 mg de bumetanida tem potência diurética equivalente a aproximadamente 40 mg de furosemida. Indicado no edema associado a insuficiência cardíaca congestiva, doença hepática e renal, incluindo síndrome nefrótica. O início da diurese oral ocorre em 30-60 minutos, o pico entre 1-2 horas e a diurese está praticamente completa em 4 horas (4-6 h com doses mais altas).',
   'Loop diuretic with rapid onset and short duration of action; 1 mg of bumetanide has a diuretic potency equivalent to approximately 40 mg of furosemide. Indicated for oedema associated with congestive heart failure, hepatic and renal disease, including the nephrotic syndrome. Onset of oral diuresis occurs within 30-60 minutes, peak activity between 1-2 hours and diuresis is largely complete within 4 hours (4-6 h with higher doses).',
   'Inibe a reabsorção de sódio no ramo ascendente da ansa de Henle (redução da clearance de água livre durante a hidratação e da reabsorção tubular de água livre durante a hidropenia); bloqueia também a reabsorção de cloreto (é algo mais clorurético do que natriurético) e aumenta a excreção de potássio de forma dose-dependente. Pode ter ação adicional no túbulo proximal (fosfatúria); não inibe a anidrase carbónica nem tem ação relevante no túbulo distal. Diminui a excreção de ácido úrico e aumenta a uricemia.',
   'Inhibits sodium reabsorption in the ascending limb of the loop of Henle (marked reduction of free-water clearance during hydration and of tubular free-water reabsorption during hydropenia); also blocks chloride reabsorption (somewhat more chloruretic than natriuretic) and increases potassium excretion in a dose-related fashion. May have an additional action in the proximal tubule (phosphaturia); does not inhibit carbonic anhydrase nor have relevant distal tubule action. Decreases uric acid excretion and raises serum uric acid.',
   'Eliminada rapidamente; um estudo com bumetanida marcada com carbono-14 mostrou que 81% da radioatividade é excretada na urina, 45% como fármaco inalterado. Os metabolitos urinários e biliares identificados formam-se por oxidação da cadeia lateral N-butilo. A excreção biliar corresponde a apenas 2% da dose. Liga-se às proteínas plasmáticas em 94-96%.',
   'Rapidly eliminated; a carbon-14 labelled bumetanide study showed 81% of radioactivity excreted in urine, 45% as unchanged drug. The urinary and biliary metabolites identified are formed by oxidation of the N-butyl side chain. Biliary excretion amounts to only 2% of the dose. Plasma protein binding 94-96%.',
   'Resposta diurética quase igual por via oral e parentérica. Absorção oral rápida, com início da diurese em 30-60 minutos e pico de atividade entre 1-2 horas após a toma. Nos idosos (65-73 anos) o clearance total é mais baixo (1,8 vs 2,9 mL/min/kg) e as concentrações máximas são superiores (16,9 vs 10,3 ng/mL) face aos adultos jovens.',
   'Almost equal diuretic response occurs after oral and parenteral administration. Rapid oral absorption, with onset of diuresis within 30-60 minutes and peak activity between 1-2 hours after dosing. In the elderly (65-73 years) total clearance is lower (1.8 vs 2.9 mL/min/kg) and peak concentrations higher (16.9 vs 10.3 ng/mL) compared with younger adults.',
   'Semivida de eliminação de 1 a 1,5 horas em adultos com função renal normal. Nos recém-nascidos a eliminação é consideravelmente mais lenta (semivida aparente de cerca de 6 horas ao nascer, ~2,4 horas ao 1.º mês; 2,5 h <2 meses, 1,5 h 2-6 meses). Potencial ototóxico (5-6x mais potente que a furosemida nos estudos animais).',
   'Elimination half-life of 1 to 1.5 hours in adults with normal renal function. In neonates elimination is considerably slower (apparent half-life about 6 hours at birth, ~2.4 hours at 1 month; 2.5 h <2 months, 1.5 h 2-6 months). Potential for ototoxicity (5-6 times more potent than furosemide in animal studies).',
   'DailyMed/FDA — Bumetanide Tablets USP (Sandoz), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8914d8bf-61b7-4cd2-a8ef-7e1c5df37828',
   'DailyMed/FDA — Bumetanide Tablets USP label (Sandoz), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8914d8bf-61b7-4cd2-a8ef-7e1c5df37828'),

  ('buprenorfina',
   'Agonista parcial dos recetores opióides mu e antagonista dos recetores kappa, indicado no tratamento da dependência de opióides (comprimidos sublinguais, preferidos para a indução). Produz efeitos agonistas típicos limitados por um efeito teto (inclusive na depressão respiratória); prolonga o QTc em ≤15 ms nos estudos. Semivida longa (31-35 h) que permite toma diária.',
   'Partial mu-opioid receptor agonist and kappa-opioid receptor antagonist, indicated for the treatment of opioid dependence (sublingual tablets, preferred for induction). Produces typical opioid agonist effects limited by a ceiling effect (including on respiratory depression); prolongs QTc by ≤15 ms in studies. Long half-life (31-35 h) allowing daily dosing.',
   'Agonista parcial do recetor opióide mu e antagonista do recetor kappa. O efeito teto nos efeitos subjetivos e na depressão respiratória distingue-a dos agonistas totais; nos estudos de dose única ascendente (1-32 mg), para todas as medidas em que o fármaco produziu efeito houve uma dose a partir da qual não houve efeito adicional. A buprenorfina inibe CYP2D6 e CYP3A4 in vitro, mas as concentrações terapêuticas não suscitam interações clinicamente relevantes.',
   'Partial agonist at the mu-opioid receptor and antagonist at the kappa-opioid receptor. The ceiling effect on subjective effects and respiratory depression distinguishes it from full agonists; in ascending single-dose studies (1-32 mg), for every measure in which the drug produced an effect there was a dose that produced no further effect. Buprenorphine inhibits CYP2D6 and CYP3A4 in vitro, but therapeutic concentrations are not expected to raise clinically relevant interactions.',
   'Metabolizada por N-desalquilação em norbuprenorfina (principalmente via CYP3A4) e por glucuronidação; a norbuprenorfina, o principal metabolito, pode sofrer glucuronidação adicional. Estudo de balanço de massa: recuperação completa da radiatividade na urina (30%) e fezes (69%) em 11 dias; na urina, a maior parte da buprenorfina e norbuprenorfina encontra-se conjugada. Ligação proteica de aproximadamente 96% (alfa e beta globulinas).',
   'Metabolised by N-dealkylation to norbuprenorphine (mediated primarily by CYP3A4) and by glucuronidation; norbuprenorphine, the major metabolite, can undergo further glucuronidation. Mass balance study: complete recovery of radiolabel in urine (30%) and faeces (69%) within 11 days; in urine, most buprenorphine and norbuprenorphine is conjugated. Approximately 96% protein bound (alpha and beta globulin).',
   'Absorção sublingual com ampla variabilidade interindividual (baixa variabilidade intraindividual); Cmax e AUC aumentam linearmente com a dose entre 4-16 mg, embora não diretamente proporcionais. Cmax média de 1,25 ng/mL (2 mg), 2,88 ng/mL (8 mg) e 4,70 ng/mL (16 mg), com Tmax de ~1,3-1,8 horas. Nos estudos de efeitos subjetivos, o pico de efeito ocorreu após ~100 minutos.',
   'Sublingual absorption with wide inter-patient variability (low within-subject variability); Cmax and AUC increase linearly with dose between 4-16 mg, although not directly dose-proportional. Mean Cmax of 1.25 ng/mL (2 mg), 2.88 ng/mL (8 mg) and 4.70 ng/mL (16 mg), with Tmax ~1.3-1.8 hours. In subjective effect studies, peak effect occurred after ~100 minutes.',
   'Semivida média de eliminação plasmática de 31 a 35 horas após administração sublingual (31,7 h a 2 mg; 35,0 h a 8 mg; 36,5 h a 16 mg); a norbuprenorfina tem semivida de ~39-44 horas. Na insuficiência hepática moderada/grave a Cmax, AUC e semivida aumentam (até +57% na semivida na insuficiência grave).',
   'Mean plasma elimination half-life of 31 to 35 hours after sublingual administration (31.7 h at 2 mg; 35.0 h at 8 mg; 36.5 h at 16 mg); norbuprenorphine has a half-life of ~39-44 hours. In moderate/severe hepatic impairment Cmax, AUC and half-life increase (up to +57% in half-life in severe impairment).',
   'DailyMed/FDA — Buprenorphine Sublingual Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b60d514d-a88a-4fa2-a5b0-30ac29e04973',
   'DailyMed/FDA — Buprenorphine Sublingual Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b60d514d-a88a-4fa2-a5b0-30ac29e04973'),

  ('celecoxib',
   'AINE inibidor seletivo da COX-2 com propriedades analgésicas, anti-inflamatórias e antipiréticas, indicado na osteoartrite, artrite reumatoide, artrite idiopática juvenil, espondilite anquilosante, dor aguda e dismenorreia primária. Não afeta a agregação plaquetária nem prolonga o tempo de hemorragia — não substitui a aspirina na profilaxia cardiovascular. Semivida efetiva de cerca de 11 horas; metabolizado pelo CYP2C9.',
   'COX-2 selective NSAID with analgesic, anti-inflammatory and antipyretic properties, indicated for osteoarthritis, rheumatoid arthritis, juvenile idiopathic arthritis, ankylosing spondylitis, acute pain and primary dysmenorrhoea. Does not affect platelet aggregation nor prolong bleeding time — not a substitute for aspirin for cardiovascular prophylaxis. Effective half-life of about 11 hours; metabolised by CYP2C9.',
   'O mecanismo de ação assenta na inibição da síntese de prostaglandinas, principalmente por inibição da COX-2 (potente inibidor da síntese de prostaglandinas in vitro). A diminuição das prostaglandinas nos tecidos periféricos reduz a sensibilização das fibras aferentes e a ação da bradicinina na indução da dor, e medeia o efeito anti-inflamatório.',
   'The mechanism of action is believed to be inhibition of prostaglandin synthesis, primarily via inhibition of COX-2 (a potent inhibitor of prostaglandin synthesis in vitro). Reduced prostaglandins in peripheral tissues decrease sensitisation of afferent nerves and the action of bradykinin in inducing pain, and mediate the anti-inflammatory effect.',
   'Metabolizado principalmente pelo CYP2C9 em três metabolitos (álcool primário, ácido carboxílico correspondente e o seu conjugado glucurónico), inativos como inibidores da COX-1/COX-2. Eliminado predominantemente por metabolismo hepático com pouco (<3%) fármaco inalterado na urina e fezes: cerca de 57% da dose nas fezes e 27% na urina (o metabolito ácido carboxílico representa 73% da dose). O fluconazol (inibidor do CYP2C9) duplica as concentrações plasmáticas.',
   'Metabolised primarily via CYP2C9 into three metabolites (a primary alcohol, the corresponding carboxylic acid and its glucuronide conjugate), inactive as COX-1/COX-2 inhibitors. Eliminated predominantly by hepatic metabolism with little (<3%) unchanged drug in urine and faeces: about 57% of the dose in faeces and 27% in urine (the carboxylic acid metabolite accounts for 73% of the dose). Fluconazole (a CYP2C9 inhibitor) doubles plasma concentrations.',
   'Pico plasmático cerca de 3 horas após a dose oral; exposição aproximadamente proporcional à dose até 200 mg duas vezes ao dia (menos que proporcional em doses mais altas, devido à baixa solubilidade). Altamente ligado às proteínas (~97%), sobretudo albumina; volume de distribuição aparente em estado estacionário de cerca de 400 L. Com refeição rica em gordura o pico atrasa 1-2 horas com aumento de 10-20% da AUC. Estado estacionário no 5.º dia.',
   'Peak plasma levels occur approximately 3 hours after an oral dose; exposure roughly dose-proportional up to 200 mg twice daily (less than proportional at higher doses, due to low solubility). Highly protein bound (~97%), mainly to albumin; apparent steady-state volume of distribution about 400 L. A high-fat meal delays the peak by 1-2 hours with a 10-20% increase in AUC. Steady state by Day 5.',
   'Semivida efetiva de aproximadamente 11 horas em jejum (Tmax 2,8 h; clearance plasmático aparente ~500 mL/min). Em doentes com compromisso hepático ligeiro/moderado (Child-Pugh A/B) a AUC em estado estacionário aumenta ~40% e ~180% — reduzir a dose ~50% na insuficiência moderada. Nos metabolizadores lentos CYP2C9*3/*3 os níveis podem ser 3-7x superiores.',
   'Effective half-life of approximately 11 hours under fasting conditions (Tmax 2.8 h; apparent plasma clearance ~500 mL/min). In patients with mild/moderate hepatic impairment (Child-Pugh A/B) steady-state AUC increases ~40% and ~180% — reduce the dose by ~50% in moderate impairment. In CYP2C9*3/*3 poor metabolisers levels may be 3-7-fold higher.',
   'DailyMed/FDA — Celecoxib Capsules, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2c86ece8-1cf5-4688-91b1-8aef5d60b7e4',
   'DailyMed/FDA — Celecoxib Capsules label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2c86ece8-1cf5-4688-91b1-8aef5d60b7e4'),

  ('codeina',
   'Analgésico opióide (agonista mu relativamente seletivo, com afinidade muito mais fraca que a morfina) usado na dor ligeira a moderada em que é apropriado um opióide e as alternativas são inadequadas (habitualmente associado ao paracetamol). O efeito analgésico depende em parte da conversão em morfina (CYP2D6); atinge o pico em ~2 horas e persiste 4-6 horas. Risco de depressão respiratória, dependência, abuso e desvio.',
   'Opioid analgesic (relatively selective mu-opioid agonist, with much weaker affinity than morphine) used for mild to moderate pain where an opioid is appropriate and alternatives are inadequate (usually combined with paracetamol/acetaminophen). The analgesic effect depends in part on conversion to morphine (CYP2D6); peaks within ~2 hours and lasts 4-6 hours. Risk of respiratory depression, addiction, abuse and diversion.',
   'Agonista opióide relativamente seletivo para o recetor mu, com afinidade muito mais fraca que a morfina; acredita-se que as propriedades analgésicas resultem da sua conversão em morfina. Produz depressão respiratória por ação direta nos centros respiratórios do tronco cerebral, miose, redução da motilidade gastrointestinal (obstipação), vasodilatação periférica e efeitos endócrinos (inibição de ACTH, cortisol e LH).',
   'Opioid agonist relatively selective for the mu-opioid receptor, with much weaker affinity than morphine; its analgesic properties are believed to come from its conversion to morphine. Produces respiratory depression by direct action on brainstem respiratory centres, miosis, reduced GI motility (constipation), peripheral vasodilation and endocrine effects (inhibition of ACTH, cortisol and LH).',
   'Cerca de 70-80% da dose é metabolizada: conjugação com ácido glucurónico em codeína-6-glucuronídeo (C6G; UGT2B7/2B4), O-desmetilação em morfina (~5-10%; CYP2D6) e N-desmetilação em norcodeína (~10%; CYP3A4). A morfina e a M6G têm atividade analgésica. A eliminação é essencialmente renal: ~90% da dose oral é excretada na urina em 24 horas (codeína livre e conjugada ~70%, norcodeína ~10%, morfina ~10%, normorfina 4%, hidrocodona 1%).',
   'About 70-80% of the dose is metabolised: conjugation with glucuronic acid to codeine-6-glucuronide (C6G; UGT2B7/2B4), O-demethylation to morphine (~5-10%; CYP2D6) and N-demethylation to norcodeine (~10%; CYP3A4). Morphine and M6G have analgesic activity. Elimination is essentially renal: about 90% of an oral dose is excreted in urine within 24 hours (free and conjugated codeine ~70%, norcodeine ~10%, morphine ~10%, normorphine 4%, hydrocodone 1%).',
   'Rapidamente absorvida no trato gastrointestinal e rapidamente distribuída pelos tecidos, com captação preferencial nos órgãos parenquimatosos (fígado, baço, rim); atravessa a barreira hematoencefálica e encontra-se no tecido fetal e no leite materno. Ligação às proteínas plasmáticas de apenas 7-25%. Não se acumula nos tecidos. O efeito analgésico atinge o pico em ~2 horas e persiste 4-6 horas.',
   'Rapidly absorbed from the GI tract and rapidly distributed to body tissues, with preferential uptake by parenchymatous organs (liver, spleen, kidney); crosses the blood-brain barrier and is found in fetal tissue and breast milk. Plasma protein binding of only 7-25%. Does not accumulate in tissues. The analgesic effect peaks within ~2 hours and persists 4-6 hours.',
   'Semivida plasmática de cerca de 2,9 horas. Nos metabolizadores ultrarrápidos do CYP2D6 a conversão em morfina é mais rápida e completa, com níveis séricos de morfina superiores ao esperado e risco de depressão respiratória fatal mesmo em doses habituais; inibidores do CYP3A4 podem aumentar a conversão em morfina (via 2D6) e inibidores do CYP2D6 reduzi-la.',
   'Plasma half-life of about 2.9 hours. In CYP2D6 ultra-rapid metabolisers conversion to morphine is more rapid and complete, with higher than expected serum morphine levels and risk of fatal respiratory depression even at labelled doses; CYP3A4 inhibitors can increase conversion to morphine (via 2D6) and CYP2D6 inhibitors reduce it.',
   'DailyMed/FDA — Acetaminophen and Codeine Phosphate Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=eadc80fa-13c3-471a-a22f-6fe7e1ab290f',
   'DailyMed/FDA — Acetaminophen and Codeine Phosphate Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=eadc80fa-13c3-471a-a22f-6fe7e1ab290f'),

  ('desloratadina',
   'Anti-histamínico H1 tricíclico de ação prolongada, não sedativo (não atravessa de forma relevante a barreira hematoencefálica), indicado na rinite alérgica e urticária. Efeito anti-histamínico (wheal and flare) ao fim de 1 hora, persistindo até 24 horas, sem taquifilaxia em 28 dias. Não prolonga o QTc de forma clinicamente relevante (aumento médio de 8,1 ms pelo método de Bazett com 45 mg/dia, sem eventos adversos).',
   'Long-acting tricyclic H1 antihistamine, non-sedating (does not readily cross the blood-brain barrier), indicated for allergic rhinitis and urticaria. Antihistaminic effect (wheal and flare) within 1 hour, persisting up to 24 hours, without tachyphylaxis over 28 days. No clinically relevant QTc prolongation (mean increase of 8.1 ms by Bazett method at 45 mg/day, with no adverse events).',
   'Antagonista seletivo de ação prolongada dos recetores H1 da histamina (interação significativa com o recetor H1 humano a 2-3 ng/mL); inibe a libertação de histamina pelos mastócitos in vitro. Não atravessa facilmente a barreira hematoencefálica (estudos com distribuição tecidular radiomarcada e ligação ao recetor H1).',
   'Long-acting selective histamine H1-receptor antagonist (significant interaction with the human H1 receptor at 2-3 ng/mL); inhibits histamine release from human mast cells in vitro. Does not readily cross the blood-brain barrier (radiolabelled tissue distribution and H1-receptor binding studies).',
   'Extensamente metabolizada em 3-hidroxidesloratadina (metabolito ativo), que é depois glucuronidada; as enzimas responsáveis não foram identificadas. Cerca de 6% da população são metabolizadores lentos (semivida >50 h ou razão de AUC 3-OH/desloratadina <0,1; mais frequente em negros, 17%). Estudo de balanço de massa: recuperação de ~87% da dose, distribuída igualmente na urina e fezes como produtos metabólicos.',
   'Extensively metabolised to 3-hydroxydesloratadine (an active metabolite), which is subsequently glucuronidated; the responsible enzymes have not been identified. About 6% of the population are poor metabolisers (half-life >50 h or 3-OH/desloratadine AUC ratio <0.1; more frequent in Blacks, 17%). Mass balance study: recovery of ~87% of the dose, equally distributed in urine and faeces as metabolic products.',
   'Tmax de cerca de 3 horas após dose oral de 5 mg (Cmax média em estado estacionário ~4 ng/mL, AUC 56,9 ng·h/mL). Nem a comida nem o sumo de toranja afetam a biodisponibilidade. Ligação às proteínas plasmáticas de 82-87% (desloratadina) e 85-89% (3-hidroxidesloratadina). Cmax e AUC proporcionais à dose entre 5-20 mg.',
   'Tmax of about 3 hours after a 5 mg oral dose (mean steady-state Cmax ~4 ng/mL, AUC 56.9 ng·h/mL). Neither food nor grapefruit juice affects bioavailability. Plasma protein binding of 82-87% (desloratadine) and 85-89% (3-hydroxydesloratadine). Cmax and AUC dose-proportional between 5-20 mg.',
   'Semivida média de eliminação plasmática de aproximadamente 27 horas (33,7 h em idosos ≥65 anos); a 3-hidroxidesloratadina tem Tmax e semivida semelhantes. Na insuficiência hepática a AUC aumenta ~2,4x e a semivida prolonga-se; na insuficiência renal grave a AUC aumenta ~2,5x. Permite toma única diária.',
   'Mean plasma elimination half-life of approximately 27 hours (33.7 h in elderly subjects ≥65 years); 3-hydroxydesloratadine shows similar Tmax and half-life. In hepatic impairment AUC increases ~2.4-fold and half-life is prolonged; in severe renal impairment AUC increases ~2.5-fold. Allows once-daily dosing.',
   'DailyMed/FDA — Desloratadine Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c',
   'DailyMed/FDA — Desloratadine Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c'),

  ('domperidona',
   'Procinético e antiemético, antagonista periférico dos recetores D2 da dopamina, sem passagem relevante da barreira hematoencefálica (baixa incidência de efeitos extrapiramidais). Aumenta a motilidade gástrica e o peristaltismo duodenal. Risco de prolongamento do QT e arritmias ventriculares — contraindicado com inibidores potentes do CYP3A4 e em doentes com QT prolongado; biodisponibilidade oral ~15% (efeito de primeira passagem) e semivida 7-9 h.',
   'Prokinetic and antiemetic, peripheral dopamine D2 receptor antagonist, without relevant blood-brain barrier crossing (low incidence of extrapyramidal effects). Increases gastric motility and duodenal peristalsis. Risk of QT prolongation and ventricular arrhythmias — contraindicated with potent CYP3A4 inhibitors and in patients with QT prolongation; oral bioavailability ~15% (first-pass effect) and half-life 7-9 h.',
   'Antagonista periférico dos recetores D2 da dopamina; a baixa passagem da barreira hematoencefálica explica a baixa incidência de efeitos extrapiramidais. O efeito procinético resulta do aumento da motilidade do trato gastrointestinal superior (tónus e amplitude das contrações gástricas, relaxamento do piloro, peristaltismo duodenal) e do tónus do esfíncter esofágico inferior.',
   'Peripheral dopamine D2 receptor antagonist; the low blood-brain barrier crossing explains the low incidence of extrapyramidal effects. The prokinetic effect results from increased upper GI motility (gastric tone and amplitude of contractions, pyloric relaxation, duodenal peristalsis) and lower oesophageal sphincter tone.',
   'Metabolismo hepático rápido e extenso por hidroxilação e N-desalquilação; o CYP3A4 é a principal forma do citocromo P450 envolvida na N-desalquilação, e o CYP3A4, CYP1A2 e CYP2E1 estão envolvidos na hidroxilação aromática. Excreção urinária e fecal de 31% e 66% da dose oral, respetivamente; a proporção excretada inalterada é pequena (~1% na urina, 10% da excreção fecal).',
   'Rapid and extensive hepatic metabolism by hydroxylation and N-dealkylation; CYP3A4 is the major cytochrome P450 form involved in N-dealkylation, and CYP3A4, CYP1A2 and CYP2E1 are involved in aromatic hydroxylation. Urinary and faecal excretion amount to 31% and 66% of the oral dose, respectively; the proportion excreted unchanged is small (~1% in urine, 10% of faecal excretion).',
   'Em jejum, absorção oral rápida com pico plasmático aos 30-60 minutos. A baixa biodisponibilidade oral absoluta (~15%) deve-se a um extenso metabolismo de primeira passagem na parede intestinal e no fígado. A toma após refeição aumenta a biodisponibilidade; a acidez gástrica reduzida prejudica a absorção. Liga-se às proteínas plasmáticas em 91-93%.',
   'Under fasting conditions, rapid oral absorption with peak plasma concentrations at 30-60 minutes. The low absolute oral bioavailability (~15%) is due to extensive first-pass metabolism in the gut wall and liver. Taking after a meal increases bioavailability; reduced gastric acidity impairs absorption. Plasma protein binding 91-93%.',
   'Semivida plasmática de 7-9 horas após dose oral única em indivíduos saudáveis; prolonga-se na insuficiência renal grave (a semivida de eliminação aumentou de 7,4 para 20,8 horas em doentes com insuficiência renal grave) — reduzir a frequência das tomas nesses doentes.',
   'Plasma half-life of 7-9 hours after a single oral dose in healthy subjects; prolonged in severe renal insufficiency (elimination half-life increased from 7.4 to 20.8 hours in patients with severe renal insufficiency) — reduce the dosing frequency in these patients.',
   'EMA/Comissão Europeia — SmPC Motilium (domperidona), secção 5.2 (resumo das características do medicamento aprovado na UE): https://ec.europa.eu/health/documents/community-register/',
   'EMA/European Commission — Motilium (domperidone) SmPC, section 5.2 (EU-approved summary of product characteristics): https://ec.europa.eu/health/documents/community-register/'),

  ('doxiciclina',
   'Tetraciclina bacteriostática de largo espetro (Gram-positivos e Gram-negativos, bactérias atípicas), indicada em múltiplas infeções (respiratórias, urinárias, pele, sexualmente transmissíveis, doença de Lyme, brucelose, cólera, peste, etc.). Quase completamente absorvida por via oral; semivida sérica de 18-22 horas independente da função renal (pode ser usada na insuficiência renal sem ajuste).',
   'Broad-spectrum bacteriostatic tetracycline (Gram-positives and Gram-negatives, atypical bacteria), indicated in many infections (respiratory, urinary, skin, sexually transmitted, Lyme disease, brucellosis, cholera, plague, etc.). Almost completely absorbed orally; serum half-life of 18-22 hours independent of renal function (can be used in renal impairment without adjustment).',
   'Inibe a síntese proteica bacteriana por ligação à subunidade ribossómica 30S; atividade bacteriostática contra um largo espetro de bactérias Gram-positivas e Gram-negativas. A resistência cruzada com outras tetraciclinas é comum.',
   'Inhibits bacterial protein synthesis by binding to the 30S ribosomal subunit; bacteriostatic activity against a broad range of Gram-positive and Gram-negative bacteria. Cross-resistance with other tetracyclines is common.',
   'Concentrada pelo fígado na bílis e excretada na urina e fezes em concentrações elevadas e na forma biologicamente ativa. Excreção renal de cerca de 40% em 72 horas em indivíduos com função normal (clearance de creatinina ~75 mL/min), podendo cair para 1-5%/72 h na insuficiência renal grave; a hemodiálise não altera a semivida sérica. As tetraciclinas atravessam a placenta e encontram-se nos tecidos fetais.',
   'Concentrated by the liver in the bile and excreted in urine and faeces at high concentrations and in a biologically active form. Renal excretion of about 40%/72 hours in individuals with normal function (creatinine clearance ~75 mL/min), which may fall to 1-5%/72 h in severe renal insufficiency; haemodialysis does not alter serum half-life. Tetracyclines cross the placenta and are found in fetal tissues.',
   'Virtualmente completamente absorvida após administração oral. Após uma dose de 200 mg, os adultos normais atingem níveis séricos máximos de 2,6 mcg/mL às 2 horas, diminuindo para 1,45 mcg/mL às 24 horas. As tetraciclinas são prontamente absorvidas e ligam-se às proteínas plasmáticas em grau variável.',
   'Virtually completely absorbed after oral administration. Following a 200 mg dose, normal adults achieve mean peak serum levels of 2.6 mcg/mL at 2 hours, decreasing to 1.45 mcg/mL at 24 hours. Tetracyclines are readily absorbed and bound to plasma proteins to a varying degree.',
   'Semivida sérica de 18-22 horas, sem diferença significativa entre indivíduos com função renal normal e com insuficiência renal grave (o que a distingue das outras tetraciclinas, de eliminação renal). A hemodiálise não altera a semivida.',
   'Serum half-life of 18-22 hours, with no significant difference between individuals with normal renal function and severe renal impairment (which distinguishes it from the other, renally eliminated tetracyclines). Haemodialysis does not alter the half-life.',
   'DailyMed/FDA — Doxycycline Hyclate Capsules, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=bcc95094-80ed-4023-b2a6-955a4810bfbe',
   'DailyMed/FDA — Doxycycline Hyclate Capsules label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=bcc95094-80ed-4023-b2a6-955a4810bfbe'),

  ('fexofenadina',
   'Anti-histamínico H1 não sedativo (antagonista periférico) de venda livre, indicado no alívio temporário dos sintomas da rinite alérgica e outras alergias do trato respiratório superior (coriza, espirros, comichão nasal/da garganta, olhos lacrimejantes e com comichão). Não atravessa a barreira hematoencefálica de forma relevante — sem sedação nas doses recomendadas. Substrato da glicoproteína-P (P-gp).',
   'Non-sedating H1 antihistamine (peripheral antagonist), available over-the-counter, indicated for the temporary relief of symptoms of hay fever and other upper respiratory allergies (runny nose, sneezing, itchy nose/throat, itchy and watery eyes). Does not cross the blood-brain barrier to a relevant degree — no sedation at recommended doses. Substrate of P-glycoprotein (P-gp).',
   'Antagonista seletivo periférico dos recetores H1 da histamina, sem efeitos anticolinérgicos ou sedativos relevantes (não penetra no SNC de forma significativa). A farmacocinética depende da glicoproteína-P: a P-gp medeia a absorção e a excreção do fármaco, e a inibição da P-gp (ex.: piperina) aumenta a sua biodisponibilidade.',
   'Selective peripheral H1 histamine receptor antagonist, without relevant anticholinergic or sedative effects (does not significantly penetrate the CNS). Its pharmacokinetics depend on P-glycoprotein: P-gp mediates the absorption and excretion of the drug, and P-gp inhibition (e.g., piperine) increases its bioavailability.',
   'Praticamente não é metabolizada: cerca de 95% da dose é excretada inalterada (aproximadamente 80% nas fezes e 11-12% na urina). Não sofre metabolização hepática relevante pelo citocromo P450, o que minimiza as interações metabólicas; a eliminação depende sobretudo da excreção biliar/fecal mediada pela P-gp.',
   'Essentially not metabolised: about 95% of the dose is excreted unchanged (approximately 80% in faeces and 11-12% in urine). No relevant hepatic cytochrome P450 metabolism, which minimises metabolic interactions; elimination depends mainly on P-gp-mediated biliary/faecal excretion.',
   'Rapidamente absorvida após administração oral, com pico plasmático em cerca de 1-3 horas; biodisponibilidade absoluta de aproximadamente 33% (rápida absorção, Cmax em poucas horas). A farmacocinética é linear até 240 mg/dia. A toma com sumo de frutas (toranja, laranja, maçã) pode reduzir a absorção por inibição dos transportadores OATP.',
   'Rapidly absorbed after oral administration, with peak plasma concentrations in about 1-3 hours; absolute bioavailability of approximately 33% (rapid absorption, Cmax within a few hours). Pharmacokinetics are linear up to 240 mg/day. Taking with fruit juices (grapefruit, orange, apple) may reduce absorption via OATP transporter inhibition.',
   'Semivida média de eliminação de aproximadamente 14,4 horas com 60 mg duas vezes ao dia em voluntários saudáveis (permite toma duas vezes ao dia; com 120-180 mg a semivida é semelhante, cerca de 11-15 horas). A insuficiência renal reduz o clearance e prolonga a semivida.',
   'Mean elimination half-life of approximately 14.4 hours at 60 mg twice daily in healthy volunteers (allowing twice-daily dosing; at 120-180 mg the half-life is similar, about 11-15 hours). Renal impairment reduces clearance and prolongs the half-life.',
   'DailyMed/FDA — rótulo OTC Fexofenadine Hydrochloride (Drug Facts) + revisão sistemática Clin Pharmacokinet 2024 (PMC11677975); t½: rótulo ALLEGRA FDA 2005: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb',
   'DailyMed/FDA — OTC Fexofenadine Hydrochloride label (Drug Facts) + Clin Pharmacokinet 2024 systematic review (PMC11677975); t½: ALLEGRA FDA 2005 label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb'),

  ('ferro',
   'Suplemento mineral essencial (sulfato ferroso) usado no tratamento e prevenção da anemia ferropénica e na reposição de ferro em situações de défice (gravidez, hemorragias, má absorção). A absorção oral é limitada (cerca de 10-20% do ferro elementar em doentes com défice) e regulada pela hepcidina; a sobredosagem acidental é uma causa importante de intoxicação fatal em crianças — manter fora do alcance.',
   'Essential mineral supplement (ferrous sulfate) used for the treatment and prevention of iron-deficiency anaemia and for iron replacement in deficiency states (pregnancy, bleeding, malabsorption). Oral absorption is limited (about 10-20% of elemental iron in iron-depleted patients) and regulated by hepcidin; accidental overdose is an important cause of fatal poisoning in children — keep out of reach.',
   'O ferro é um componente essencial da hemoglobina (transporte de oxigénio) e de numerosas enzimas (citocromos, mioglobina). A absorção intestinal é regulada pela hepcidina: o ferro absorvido aumenta a hepcidina, que por sua vez reduz a absorção de doses subsequentes (mecanismo de feedback). O ferro em excesso é armazenado como ferritina e hemossiderina.',
   'Iron is an essential component of haemoglobin (oxygen transport) and of numerous enzymes (cytochromes, myoglobin). Intestinal absorption is regulated by hepcidin: absorbed iron raises hepcidin, which in turn reduces absorption of subsequent doses (feedback mechanism). Excess iron is stored as ferritin and haemosiderin.',
   'O ferro não é metabolizado no sentido clássico: o ferro absorvido liga-se à transferrina no plasma e é transportado para a medula óssea (eritropoiese) e locais de armazenamento. A absorção de uma dose oral é inversamente proporcional às reservas de ferro; tomar com alimentos, chá, café, leite ou antiácidos reduz a absorção, enquanto a vitamina C a aumenta.',
   'Iron is not metabolised in the classic sense: absorbed iron binds to transferrin in plasma and is transported to the bone marrow (erythropoiesis) and storage sites. Absorption of an oral dose is inversely proportional to iron stores; taking with food, tea, coffee, milk or antacids reduces absorption, while vitamin C increases it.',
   'A absorção oral ocorre principalmente no duodeno e jejuno proximal. Em mulheres com défice de ferro, doses diárias aumentam a hepcidina e reduzem a absorção fracionada de ferro em 35-45% (doses em dias alternados otimizam a absorção). A biodisponibilidade é maior em jejum (30 minutos antes das refeições). Cerca de 10-20 mg de ferro elementar são absorvidos por dia com a terapêutica oral.',
   'Oral absorption occurs mainly in the duodenum and proximal jejunum. In iron-depleted women, daily doses raise hepcidin and reduce fractional iron absorption by 35-45% (alternate-day dosing optimises absorption). Bioavailability is highest when fasting (30 minutes before meals). About 10-20 mg of elemental iron are absorbed per day with oral therapy.',
   'Não se aplica uma semivida clássica de eliminação: o ferro circulante (ligado à transferrina) tem um tempo de trânsito rápido para a medula óssea e armazenamento, e o excesso é sequestrado como ferritina/hemossiderina. A resposta terapêutica avalia-se pela subida da hemoglobina (1-2 g/dL em 2-4 semanas) e pela normalização da ferritina.',
   'No classical elimination half-life applies: circulating iron (bound to transferrin) is rapidly taken up by the bone marrow and storage sites, and excess is sequestered as ferritin/haemosiderin. Therapeutic response is assessed by the rise in haemoglobin (1-2 g/dL within 2-4 weeks) and normalisation of ferritin.',
   'DailyMed/FDA — rótulo OTC Ferrous Sulfate (Drug Facts) + PubMed: Moretti D et al., Blood 2015;126:1981-9 (PMID 26289639) e Stoffel NU et al., Lancet Haematol 2017 (PMID 29032957): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e88a847-397b-4ddb-83d7-42c9b963a0b7',
   'DailyMed/FDA — OTC Ferrous Sulfate label (Drug Facts) + PubMed: Moretti D et al., Blood 2015;126:1981-9 (PMID 26289639) and Stoffel NU et al., Lancet Haematol 2017 (PMID 29032957): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e88a847-397b-4ddb-83d7-42c9b963a0b7'),

  ('fentanilo',
   'Agonista opióide mu de elevada potência (cerca de 100x a morfina), em sistema transdérmico de libertação contínua (72 h) para dor grave e persistente em doentes tolerantes a opióides. NÃO indicado como analgésico à procura (prn), dor aguda ou pós-operatória, nem em doentes não tolerantes. Depressão respiratória potencialmente fatal; metabolizado por CYP3A4 (interações com inibidores/indutores). Semivida após remoção ~20-27 h.',
   'High-potency mu opioid agonist (about 100x morphine), as a transdermal continuous-release system (72 h) for severe and persistent pain in opioid-tolerant patients. NOT indicated as an as-needed (prn) analgesic, acute or postoperative pain, nor in non-tolerant patients. Potentially fatal respiratory depression; metabolised by CYP3A4 (interactions with inhibitors/inducers). Half-life after removal ~20-27 h.',
   'Agonista opióide que interage predominantemente com os recetores mu, distribuídos no cérebro, medula espinhal e outros tecidos. Produz depressão respiratória por ação direta nos centros respiratórios do tronco cerebral, miose, redução da motilidade gastrointestinal, vasodilatação periférica e efeitos endócrinos. A libertação de histamina clinicamente significativa é rara com o fentanilo (até 50 mcg/kg).',
   'Opioid agonist that interacts predominantly with mu receptors, distributed in the brain, spinal cord and other tissues. Produces respiratory depression by direct action on brainstem respiratory centres, miosis, reduced GI motility, peripheral vasodilation and endocrine effects. Clinically significant histamine release is rare with fentanyl (up to 50 mcg/kg).',
   'Metabolizado principalmente pelo CYP3A4 (o metabolito principal, norfentanilo, é inativo); cerca de 75% da dose é excretada na urina (sobretudo como metabolitos) e 9% nas fezes. Menos de 10% é excretado como fármaco inalterado na urina. A insuficiência hepática pode reduzir o clearance — monitorizar.',
   'Metabolised mainly by CYP3A4 (the major metabolite, norfentanyl, is inactive); about 75% of the dose is excreted in urine (mostly as metabolites) and 9% in faeces. Less than 10% is excreted as unchanged drug in urine. Hepatic impairment may reduce clearance — monitor.',
   'Com o sistema transdérmico, as concentrações séricas aumentam gradualmente nas primeiras 72 horas de aplicação. O calor sobre o adesivo aumenta a exposição média em 120% e o nível máximo em 61% — não aplicar calor. Após a remoção, as concentrações séricas diminuem gradualmente (absorção contínua da pele), caindo ~50% em 20-27 horas.',
   'With the transdermal system, serum concentrations increase gradually over the first 72 hours of application. Heat over the patch increases mean exposure by 120% and maximum level by 61% — do not apply heat. After removal, serum concentrations decline gradually (continued skin absorption), falling ~50% in 20-27 hours.',
   'Semivida aparente após perfusão IV de aproximadamente 7 horas (intervalo 3-12 h); após remoção do adesivo, as concentrações séricas caem ~50% em 20-27 horas (refletindo a absorção contínua da pele, não a eliminação do fármaco). Em doentes cirúrgicos a semivida é de 3-12 h; na insuficiência hepática 4-12 h.',
   'Apparent half-life after IV infusion of approximately 7 hours (range 3-12 h); after patch removal serum concentrations fall ~50% in 20-27 hours (reflecting continued skin absorption, not drug elimination). In surgical patients the half-life is 3-12 h; in hepatic impairment 4-12 h.',
   'DailyMed/FDA — Fentanyl Transdermal System, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e15a7e9b-8025-49dd-9a6d-bafcccf1959f',
   'DailyMed/FDA — Fentanyl Transdermal System label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e15a7e9b-8025-49dd-9a6d-bafcccf1959f'),

  ('flecainida',
   'Antiarrítmico da classe IC (estabilizador de membrana), usado na prevenção e tratamento de arritmias ventriculares e supraventriculares (incluindo fibrilhação auricular em doentes selecionados sem doença estrutural). Efeito inotrópico negativo e risco proarrítmico — reservado a doentes com supervisão especializada. Absorção oral quase completa, sem efeito de primeira passagem; semivida ~20 h (12-27 h).',
   'Class IC antiarrhythmic (membrane stabiliser), used for the prevention and treatment of ventricular and supraventricular arrhythmias (including atrial fibrillation in selected patients without structural heart disease). Negative inotropic effect and proarrhythmic risk — reserved for patients under specialist supervision. Almost complete oral absorption with no first-pass effect; half-life ~20 h (12-27 h).',
   'Atividade anestésica local; pertence ao grupo dos antiarrítmicos estabilizadores de membrana (classe IC). Produz diminuição dose-dependente da condução intracardíaca em todas as partes do coração, com maior efeito no sistema His-Purkinje (condução H-V); efeitos nos períodos refratários observam-se apenas no ventrículo. Suprime os batimentos ventriculares prematuros e a taquicardia ventricular recorrente (níveis plasmáticos 0,2-1 mcg/mL).',
   'Local anaesthetic activity; belongs to the membrane-stabilising (Class IC) group of antiarrhythmics. Produces a dose-related decrease in intracardiac conduction in all parts of the heart, with the greatest effect on the His-Purkinje system (H-V conduction); effects on refractory periods are observed only in the ventricle. Suppresses premature ventricular complexes and recurrent ventricular tachycardia (plasma levels 0.2-1 mcg/mL).',
   'Metabolizada no fígado, envolvendo o CYP2D6 (citocromo P450IID6); os dois principais metabolitos urinários são a meta-O-desalquilflecainida (ativa, cerca de 1/5 da potência) e a meta-O-desalquil-lactama (inativa). Cerca de 30% de uma dose oral (10-50%) é excretada inalterada na urina e apenas 5% nas fezes. A eliminação depende da função renal; urina muito alcalina (pH ≥8) retarda a eliminação.',
   'Metabolised in the liver, involving CYP2D6 (cytochrome P450IID6); the two major urinary metabolites are meta-O-dealkylflecainide (active, about one-fifth as potent) and the meta-O-dealkylated lactam (inactive). About 30% of an oral dose (10-50%) is excreted unchanged in urine and only 5% in faeces. Elimination depends on renal function; very alkaline urine (pH ≥8) slows elimination.',
   'Absorção oral quase completa, com picos plasmáticos às ~3 horas (intervalo 1-6 h); sem metabolismo de primeira passagem relevante. A comida e os antiácidos não afetam a absorção (o leite pode inibi-la em lactentes). Ligação às proteínas plasmáticas de ~40%. O estado estacionário é atingido em 3-5 dias com toma múltipla.',
   'Almost complete oral absorption, with peak plasma levels at ~3 hours (range 1-6 h); no relevant first-pass metabolism. Food and antacids do not affect absorption (milk may inhibit it in infants). Plasma protein binding ~40%. Steady state is reached within 3-5 days of multiple dosing.',
   'Semivida plasmática aparente média de ~20 horas após doses orais múltiplas (intervalo 12-27 h); ~14 h em voluntários saudáveis, ~19 h na insuficiência cardíaca classe III NYHA, prolongada na insuficiência renal. Em crianças de 1-12 anos ~8 h; em adolescentes 11-12 h. Níveis plasmáticos acima de 0,7-1 mcg/mL associam-se a mais efeitos cardíacos adversos.',
   'Mean apparent plasma half-life of ~20 hours after multiple oral doses (range 12-27 h); ~14 h in healthy volunteers, ~19 h in NYHA class III heart failure, prolonged in renal impairment. In children aged 1-12 years ~8 h; in adolescents 11-12 h. Plasma levels above 0.7-1 mcg/mL are associated with more cardiac adverse effects.',
   'DailyMed/FDA — Flecainide Acetate Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=74c1eb2a-a37f-4f33-86bf-51e0d1d0c2bc',
   'DailyMed/FDA — Flecainide Acetate Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=74c1eb2a-a37f-4f33-86bf-51e0d1d0c2bc'),

  ('gentamicina',
   'Aminoglicosídeo bactericida de largo espetro (sobretudo Gram-negativos, incluindo Pseudomonas; também estafilococos), usado em infeções graves (septicemia, respiratórias, urinárias complicadas, intra-abdominais, SNC, pele e tecidos moles, ossos). Potencial de ototoxicidade, nefrotoxicidade e bloqueio neuromuscular — monitorizar função renal e níveis. Pico sérico até 4x a dose única IM (mg/kg); ≥70% excretado na urina em 24 h.',
   'Broad-spectrum bactericidal aminoglycoside (mainly Gram-negatives, including Pseudomonas; also staphylococci), used in serious infections (septicaemia, respiratory, complicated urinary, intra-abdominal, CNS, skin and soft tissue, bone). Potential for ototoxicity, nephrotoxicity and neuromuscular blockade — monitor renal function and levels. Peak serum levels up to 4x the single IM dose (mg/kg); ≥70% excreted in urine within 24 h.',
   'Antibiótico aminoglicosídeo bactericida: liga-se à subunidade ribossómica bacteriana (30S) e inibe a síntese proteica, com efeito bactericida contra bactérias suscetíveis. Como todos os aminoglicosídeos, tem potencial de toxicidade auditiva, vestibular e renal e de bloqueio neuromuscular.',
   'Bactericidal aminoglycoside antibiotic: binds to the bacterial ribosomal subunit (30S) and inhibits protein synthesis, with bactericidal effect against susceptible bacteria. Like all aminoglycosides, it has the potential for auditory, vestibular and renal toxicity and neuromuscular blockade.',
   'Praticamente sem transformação metabólica; excretada principalmente por filtração glomerular. Geralmente 70% ou mais da dose é recuperável na urina em 24 horas (concentrações urinárias acima de 100 mcg/mL); pequenas quantidades retêm-se nos tecidos, sobretudo nos rins (detetáveis na urina semanas após a suspensão). Na insuficiência renal a eliminação é mais lenta — ajustar a dose.',
   'Little, if any, metabolic transformation; excreted principally by glomerular filtration. Generally 70% or more of the dose is recoverable in urine within 24 hours (urinary concentrations above 100 mcg/mL); small amounts are retained in tissues, especially the kidneys (detectable in urine weeks after discontinuation). In renal impairment elimination is slower — adjust the dose.',
   'Após administração intramuscular, os picos séricos ocorrem habitualmente aos 30-60 minutos, com níveis mensuráveis durante 6-8 horas; por perfusão IV em 2 horas as concentrações são semelhantes. Distribui-se no líquido extracelular (picos mais baixos com grande volume de líquido extracelular, febre e queimaduras). Ligação proteica baixa (0-30%).',
   'After intramuscular administration, peak serum concentrations usually occur within 30-60 minutes, with measurable levels for 6-8 hours; IV infusion over 2 hours gives similar concentrations. Distributed in extracellular fluid (lower peaks with large extracellular fluid volume, fever and burns). Low protein binding (0-30%).',
   'Semivida de 2-3 horas em doentes com função renal normal (24-48 h na insuficiência renal significativa); 1 mg/kg IM produz pico até 4 mcg/mL. Com doses de 4 mg/kg/dia ou mais durante 7-10 dias pode haver subida progressiva dos níveis; nos queimados graves a semivida pode diminuir significativamente.',
   'Half-life of 2-3 hours in patients with normal renal function (24-48 h in significant renal impairment); 1 mg/kg IM produces a peak of up to 4 mcg/mL. With doses of 4 mg/kg/day or more for 7-10 days there may be a progressive rise in levels; in severely burned patients the half-life may decrease significantly.',
   'DailyMed/FDA — Gentamicin Sulfate Injection USP + serviço de farmacocinética clínica (t½ 2-3 h com função renal normal): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=977180b3-a222-4282-d485-4a3217674305',
   'DailyMed/FDA — Gentamicin Sulfate Injection USP label + clinical pharmacokinetics service (t½ 2-3 h with normal renal function): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=977180b3-a222-4282-d485-4a3217674305'),

  ('leflunomida',
   'Imunomodulador (derivado isoxazólico) com atividade anti-inflamatória e antiproliferativa, indicado no tratamento da artrite reumatoide ativa em adultos (e da artrite psoriática). O metabolito ativo, teriflunomida, é responsável por praticamente toda a atividade in vivo. Devido à semivida muito longa (18-19 dias), usa-se dose de ataque de 100 mg/dia durante 3 dias para atingir rapidamente o estado estacionário.',
   'Immunomodulator (isoxazole derivative) with anti-inflammatory and antiproliferative activity, indicated for the treatment of active rheumatoid arthritis in adults (and psoriatic arthritis). The active metabolite, teriflunomide, is responsible for essentially all of the in vivo activity. Because of the very long half-life (18-19 days), a loading dose of 100 mg/day for 3 days is used to reach steady state rapidly.',
   'Inibe a di-hidroorotato desidrogenase (enzima mitocondrial envolvida na síntese de novo de pirimidinas) e tem atividade antiproliferativa; vários modelos experimentais in vivo e in vitro demonstram efeito anti-inflamatório. O metabolito ativo teriflunomida é responsável por essencialmente toda a atividade in vivo do fármaco.',
   'Inhibits dihydroorotate dehydrogenase (a mitochondrial enzyme involved in de novo pyrimidine synthesis) and has antiproliferative activity; several in vivo and in vitro experimental models demonstrate an anti-inflammatory effect. The active metabolite teriflunomide is responsible for essentially all of the in vivo activity.',
   'A leflunomida é metabolizada no metabolito ativo teriflunomida e em muitos metabolitos menores (in vitro, o CYP1A2, CYP2C19 e CYP3A4 estão envolvidos no metabolismo da leflunomida; a teriflunomida não é metabolizada pelo CYP450). A teriflunomida é eliminada por excreção biliar direta do fármaco inalterado e excreção renal de metabolitos: em 21 dias, 60,1% da dose é excretada nas fezes (37,5%) e urina (22,6%). A colestiramina acelera a eliminação.',
   'Leflunomide is metabolised to the active metabolite teriflunomide and many minor metabolites (in vitro, CYP1A2, CYP2C19 and CYP3A4 are involved in leflunomide metabolism; teriflunomide is not metabolised by CYP450). Teriflunomide is eliminated by direct biliary excretion of unchanged drug and renal excretion of metabolites: over 21 days, 60.1% of the dose is excreted in faeces (37.5%) and urine (22.6%). Cholestyramine accelerates elimination.',
   'Após administração oral, os picos de teriflunomida ocorrem entre 6-12 horas após a toma. Devido à semivida muito longa (18-19 dias), usa-se dose de ataque de 100 mg/dia durante 3 dias; sem dose de ataque, o estado estacionário demoraria cerca de 2 meses. As concentrações são proporcionais à dose. Extensamente ligada às proteínas plasmáticas (>99%), distribuída sobretudo no plasma; volume de distribuição de 11 L. A comida não afeta significativamente as concentrações.',
   'After oral administration, peak teriflunomide concentrations occur between 6-12 hours after dosing. Because of the very long half-life (18-19 days), a loading dose of 100 mg/day for 3 days is used; without a loading dose, steady state would take about two months. Concentrations are dose proportional. Extensively bound to plasma proteins (>99%), distributed mainly in plasma; volume of distribution 11 L. Food does not significantly affect concentrations.',
   'Semivida mediana de 18-19 dias em voluntários saudáveis (teriflunomida). Sem procedimento de eliminação acelerada, pode demorar até 2 anos a atingir concentrações plasmáticas de teriflunomida inferiores a 0,02 mg/L. A colestiramina ou carvão ativado aceleram a eliminação.',
   'Median half-life of 18-19 days in healthy volunteers (teriflunomide). Without an accelerated elimination procedure, it may take up to 2 years to reach plasma teriflunomide concentrations below 0.02 mg/L. Cholestyramine or activated charcoal accelerate elimination.',
   'DailyMed/FDA — Leflunomide Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2',
   'DailyMed/FDA — Leflunomide Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc044417-cd9a-42f6-8a3d-a14e7c2f81a2'),

  ('loratadina',
   'Anti-histamínico H1 não sedativo de venda livre, indicado no alívio temporário dos sintomas da rinite alérgica e outras alergias do trato respiratório superior (coriza, espirros, comichão nasal/da garganta, olhos lacrimejantes e com comichão). Início de ação rápido (1-3 horas), efeito máximo às 8-12 horas e duração de 24 horas. O metabolito ativo, desloratadina, tem semivida de ~27 horas.',
   'Non-sedating H1 antihistamine available over-the-counter, indicated for the temporary relief of symptoms of hay fever and other upper respiratory allergies (runny nose, sneezing, itchy nose/throat, itchy and watery eyes). Fast onset of action (1-3 hours), peak effect at 8-12 hours and 24-hour duration. The active metabolite, desloratadine, has a half-life of ~27 hours.',
   'Antagonista seletivo periférico dos recetores H1 da histamina, sem sedação relevante nas doses recomendadas (não penetra no SNC de forma significativa). O efeito anti-histamínico periférico alivia os sintomas nasais e oculares da alergia.',
   'Selective peripheral H1 histamine receptor antagonist, without relevant sedation at recommended doses (does not significantly penetrate the CNS). The peripheral antihistaminic effect relieves the nasal and ocular symptoms of allergy.',
   'Extensamente metabolizada no fígado no metabolito ativo desloratadina (via CYP3A4 e CYP2D6) e noutros metabolitos. Cerca de 40% da dose é excretada na urina e 40% nas fezes, sobretudo como metabolitos conjugados; apenas ~1% aparece inalterado. A insuficiência hepática ou renal reduz a depuração — considerar doses em dias alternados ou doses mais baixas.',
   'Extensively metabolised in the liver to the active metabolite desloratadine (via CYP3A4 and CYP2D6) and other metabolites. About 40% of the dose is excreted in urine and 40% in faeces, mainly as conjugated metabolites; only ~1% appears unchanged. Hepatic or renal impairment reduces clearance — consider alternate-day or reduced dosing.',
   'Rapidamente absorvida após administração oral, com pico plasmático em cerca de 1-2 horas; a toma com alimentos aumenta ligeiramente a biodisponibilidade (AUC e Cmax) sem relevância clínica. Início de ação em 1-3 horas, com efeito máximo às 8-12 horas. Ligação às proteínas plasmáticas de 97-99%.',
   'Rapidly absorbed after oral administration, with peak plasma concentrations in about 1-2 hours; taking with food slightly increases bioavailability (AUC and Cmax) without clinical relevance. Onset of action within 1-3 hours, with peak effect at 8-12 hours. Plasma protein binding of 97-99%.',
   'Semivida média de eliminação de aproximadamente 8-14 horas (média ~11 h; intervalo 3-20 h) para a loratadina, com semivida mais longa (~28 h) para o metabolito ativo desloratadina — o que permite toma única diária. Na insuficiência hepática crónica a semivida prolonga-se (ajustar a dose).',
   'Mean elimination half-life of approximately 8-14 hours (mean ~11 h; range 3-20 h) for loratadine, with a longer half-life (~28 h) for the active metabolite desloratadine — allowing once-daily dosing. In chronic hepatic impairment the half-life is prolonged (adjust the dose).',
   'DailyMed/FDA — rótulo OTC Loratadine (Drug Facts) + StatPearls/PubMed (onset 1-3 h, pico 8-12 h; desloratadina t½ ~27 h, PMID 12169042): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=41f8fc1d-2d14-48da-a233-23e9c11296d9',
   'DailyMed/FDA — OTC Loratadine label (Drug Facts) + StatPearls/PubMed (onset 1-3 h, peak 8-12 h; desloratadine t½ ~27 h, PMID 12169042): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=41f8fc1d-2d14-48da-a233-23e9c11296d9'),

  ('metamizol',
   'Analgésico e antipirético não opióide (pirazolona), com efeito espasmolítico, usado na dor aguda moderada a grave e na febre alta quando outros fármacos não são adequados. Não tem efeito anti-inflamatório relevante. Associado a risco raro mas grave de agranulocitose — usar a menor dose eficaz e a duração mais curta, e suspender se surgirem sinais de infeção (febre, odinofagia, estomatite).',
   'Non-opioid analgesic and antipyretic (pyrazolone), with spasmolytic effect, used for acute moderate to severe pain and high fever when other drugs are not suitable. No relevant anti-inflammatory effect. Associated with a rare but serious risk of agranulocytosis — use the lowest effective dose for the shortest duration, and discontinue if signs of infection appear (fever, sore throat, stomatitis).',
   'O metamizol é uma pró-fármaco: hidrolisa-se rapidamente (de forma não enzimática) no metabolito ativo 4-metilaminoantipirina (MAA), responsável pelo efeito analgésico/antipirético. O mecanismo analgésico envolve a inibição da síntese de prostaglandinas no SNC e a modulação de vias centrais (sistema endocanabinoide e recetores TRPA1); não inibe de forma relevante a COX periférica (sem efeito anti-inflamatório/antiagregante).',
   'Metamizole is a prodrug: it hydrolyses rapidly (non-enzymatically) to the active metabolite 4-methylaminoantipyrine (MAA), responsible for the analgesic/antipyretic effect. The analgesic mechanism involves inhibition of prostaglandin synthesis in the CNS and modulation of central pathways (endocannabinoid system and TRPA1 receptors); it does not relevantly inhibit peripheral COX (no anti-inflammatory/antiplatelet effect).',
   'O MAA é depois metabolizado por oxidação e N-desmetilação em 4-aminoantipirina (AA) e 4-formilaminoantipirina (FAA), metabolitos também ativos e excretados por via renal; uma fração é acetilada (N-acetil-AA). A agranulocitose associada ao metamizol é idiossincrática (não dose-dependente), provavelmente imuno-mediada.',
   'MAA is subsequently metabolised by oxidation and N-demethylation to 4-aminoantipyrine (AA) and 4-formylaminoantipyrine (FAA), also active metabolites excreted renally; a fraction is acetylated (N-acetyl-AA). Metamizole-associated agranulocytosis is idiosyncratic (not dose-dependent), probably immune-mediated.',
   'Rapidamente absorvida por via oral: o MAA (metabolito ativo) atinge o pico plasmático em cerca de 1-2 horas, com biodisponibilidade oral de aproximadamente 85% (comprimidos). A administração IV/IM produz picos mais rápidos. O início da analgesia oral ocorre em 30-60 minutos.',
   'Rapidly absorbed orally: MAA (the active metabolite) reaches peak plasma concentrations in about 1-2 hours, with oral bioavailability of approximately 85% (tablets). IV/IM administration produces faster peaks. Onset of oral analgesia occurs within 30-60 minutes.',
   'Semivida de eliminação do metabolito ativo MAA de aproximadamente 3 horas (2,6-3,7 h); os metabolitos AA e FAA têm semividas de cerca de 3,5-5 horas. Em doentes com cirrose hepática a semivida do MAA pode quadruplicar. A eliminação é essencialmente renal (metabolitos).',
   'Elimination half-life of the active metabolite MAA of approximately 3 hours (2.6-3.7 h); the AA and FAA metabolites have half-lives of about 3.5-5 hours. In patients with liver cirrhosis the half-life of MAA may quadruple. Elimination is essentially renal (metabolites).',
   'PubMed — Levy M et al., Clinical Pharmacokinetics of Dipyrone and its Metabolites, Clin Pharmacokinet 1995;28(3):216-34 (PMID 7758252); corroboração Prontuário Terapêutico INFARMED (metamizol, 10.1.1): https://pubmed.ncbi.nlm.nih.gov/7758252/',
   'PubMed — Levy M et al., Clinical Pharmacokinetics of Dipyrone and its Metabolites, Clin Pharmacokinet 1995;28(3):216-34 (PMID 7758252); corroborated by Prontuário Terapêutico INFARMED (metamizole, 10.1.1): https://pubmed.ncbi.nlm.nih.gov/7758252/'),

  ('metoclopramida',
   'Procinético e antiemético (antagonista dopaminérgico D2 e agonista 5-HT4/antagonista 5-HT3), indicado no tratamento de curta duração da náusea e vómito, da gastroparesia diabética e da doença de refluxo gastroesofágico. Aumenta o tónus do esfíncter esofágico inferior e acelera o esvaziamento gástrico. Risco de efeitos extrapiramidais (incluindo discinesia tardia) com uso prolongado — limitar a duração do tratamento.',
   'Prokinetic and antiemetic (dopamine D2 antagonist and 5-HT4 agonist/5-HT3 antagonist), indicated for the short-term treatment of nausea and vomiting, diabetic gastroparesis and gastro-oesophageal reflux disease. Increases lower oesophageal sphincter tone and accelerates gastric emptying. Risk of extrapyramidal effects (including tardive dyskinesia) with prolonged use — limit treatment duration.',
   'Estimula a motilidade do trato gastrointestinal superior sem estimular as secreções gástrica, biliar ou pancreática: aumenta o tónus e a amplitude das contrações gástricas (antral), relaxa o esfíncter pilórico e o bolbo duodenal e aumenta o peristaltismo do duodeno e jejuno, acelerando o esvaziamento gástrico e o trânsito intestinal; aumenta o tónus em repouso do esfíncter esofágico inferior. Parece sensibilizar os tecidos à ação da acetilcolina; o efeito é abolido por anticolinérgicos.',
   'Stimulates motility of the upper GI tract without stimulating gastric, biliary or pancreatic secretions: increases the tone and amplitude of gastric (especially antral) contractions, relaxes the pyloric sphincter and duodenal bulb and increases peristalsis of the duodenum and jejunum, accelerating gastric emptying and intestinal transit; increases resting lower oesophageal sphincter tone. It seems to sensitise tissues to the action of acetylcholine; the effect is abolished by anticholinergic drugs.',
   'Metabolizada no fígado por oxidação e por conjugação com glucurónido e sulfato; o principal metabolito oxidativo (monodesetilmetoclopramida) forma-se sobretudo pelo CYP2D6, enzima sujeita a variabilidade genética. Cerca de 85% da radioatividade de uma dose oral aparece na urina em 72 horas; apenas 18-22% é recuperada como metoclopramida livre nas primeiras 36 horas.',
   'Metabolised in the liver by oxidation and by glucuronide and sulphate conjugation; the major oxidative metabolite (monodeethylmetoclopramide) is formed primarily by CYP2D6, an enzyme subject to genetic variability. Approximately 85% of the radioactivity of an oral dose appears in urine within 72 hours; only 18-22% is recovered as free metoclopramide within 36 hours.',
   'Biodisponibilidade oral absoluta de 80% ± 15,5% (face à dose IV de 20 mg); picos plasmáticos cerca de 1-2 horas após dose oral. Não se liga extensamente às proteínas plasmáticas (~30%); volume de distribuição elevado (~3,5 L/kg), sugerindo distribuição extensa nos tecidos.',
   'Absolute oral bioavailability of 80% ± 15.5% (relative to a 20 mg IV dose); peak plasma concentrations about 1-2 hours after an oral dose. Not extensively bound to plasma proteins (~30%); high volume of distribution (~3.5 L/kg), suggesting extensive tissue distribution.',
   'Semivida média de eliminação de 5-6 horas em doentes com função renal normal (a farmacocinética é linear entre 20-100 mg). A insuficiência renal grave prolonga a semivida e reduz o clearance — reduzir a dose. A semivida pode prolongar-se na insuficiência hepática (menor clearance).',
   'Mean elimination half-life of 5-6 hours in subjects with normal renal function (pharmacokinetics are linear between 20-100 mg). Severe renal impairment prolongs the half-life and reduces clearance — reduce the dose. Half-life may be prolonged in hepatic impairment (lower clearance).',
   'DailyMed/FDA — Metoclopramide Tablets USP, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c143e210-4ce7-44e5-b1e2-bf0e6bfde485',
   'DailyMed/FDA — Metoclopramide Tablets USP label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c143e210-4ce7-44e5-b1e2-bf0e6bfde485'),

  ('febuxostat',
   'Inibidor seletivo da xantina oxidase (não purínico), indicado no tratamento da hiperuricemia crónica com depósitos de urato (gota, tofo gotoso, urolitíase) em adultos. Reduz o ácido úrico sérico de forma dose-dependente (40-55% com 40-80 mg/dia) e aumenta a xantina sérica. Sem efeito no intervalo QTc até 300 mg/dia. Semivida terminal aparente de 5-8 horas.',
   'Selective (non-purine) xanthine oxidase inhibitor, indicated for the treatment of chronic hyperuricaemia with urate deposition (gout, tophaceous gout, urate urolithiasis) in adults. Reduces serum uric acid dose-dependently (40-55% at 40-80 mg/day) and increases serum xanthine. No effect on the QTc interval up to 300 mg/day. Apparent terminal half-life of 5-8 hours.',
   'Inibidor seletivo da xantina oxidase: diminui o ácido úrico sérico ao bloquear a oxidação da hipoxantina e xantina em ácido úrico; não se espera que iniba outras enzimas envolvidas na síntese e metabolismo das purinas e pirimidinas em concentrações terapêuticas. Aumenta a excreção urinária de xantina e reduz a excreção urinária de ácido úrico.',
   'Selective xanthine oxidase inhibitor: lowers serum uric acid by blocking the oxidation of hypoxanthine and xanthine to uric acid; not expected to inhibit other enzymes involved in purine and pyrimidine synthesis and metabolism at therapeutic concentrations. Increases urinary xanthine excretion and decreases urinary uric acid excretion.',
   'Metabolizado por conjugação com glucurónido (via UGT, incluindo UGT1A1, 1A3, 1A9, 2B7) e oxidação pelo CYP (CYP1A2, 2C8, 2C9) e enzimas não-P450. Aproximadamente 49% da dose é recuperada na urina (como fármaco, metabolitos acilglucurónidos e oxidativos) e 45% nas fezes; menos de 1% excretado inalterado na urina.',
   'Metabolised by glucuronide conjugation (via UGT, including UGT1A1, 1A3, 1A9, 2B7) and oxidation by CYP (CYP1A2, 2C8, 2C9) and non-P450 enzymes. Approximately 49% of the dose is recovered in urine (as drug, acylglucuronide and oxidative metabolites) and 45% in faeces; less than 1% excreted unchanged in urine.',
   'Concentrações plasmáticas máximas entre 1-1,5 horas após a toma; a absorção é de pelo menos 49% (radioatividade recuperada na urina). Com 40 mg e 80 mg/dia, Cmax de ~1,6 e ~2,6 mcg/mL. Com refeição rica em gordura a Cmax diminui 49% e a AUC 18% (sem alteração clínica no efeito); os antiácidos atrasam a absorção ~1 hora (-31% Cmax, -15% AUC, sem relevância clínica). Volume de distribuição aparente ~50 L.',
   'Peak plasma concentrations between 1-1.5 hours after dosing; absorption is at least 49% (radioactivity recovered in urine). At 40 mg and 80 mg/day, Cmax of ~1.6 and ~2.6 mcg/mL. With a high-fat meal Cmax decreases 49% and AUC 18% (no clinical change in effect); antacids delay absorption ~1 hour (-31% Cmax, -15% AUC, not clinically significant). Apparent volume of distribution ~50 L.',
   'Semivida terminal aparente média de aproximadamente 5-8 horas; Cmax e AUC proporcionais à dose entre 10-120 mg, sem acumulação com administração diária. Nos doentes com insuficiência hepática grave (Child-Pugh C) a exposição aumenta — não recomendado.',
   'Mean apparent terminal half-life of approximately 5-8 hours; Cmax and AUC dose-proportional between 10-120 mg, with no accumulation with daily administration. In patients with severe hepatic impairment (Child-Pugh C) exposure increases — not recommended.',
   'DailyMed/FDA — Febuxostat Tablets (ULORIC), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=54de10ef-fe5f-4930-b91d-6bbb04c664bd',
   'DailyMed/FDA — Febuxostat Tablets (ULORIC) label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=54de10ef-fe5f-4930-b91d-6bbb04c664bd')
) AS v(slug, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
        metabolism_pt, metabolism_en, absorption_pt, absorption_en,
        half_life_pt, half_life_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
